    {"id": "q-m203-s01-030", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What bleach dilution is used for routine surfaces during a C. difficile outbreak or a large blood spill?", "choices": ["1:10", "1:100", "1:1000", "Undiluted"], "correct": 0, "explanation": "1:10 for C. diff surfaces and large spills; 1:100 for small spills (< 10 mL); 1:50 for 5 minutes for home semicritical items.", "srcItem": "Sterilization"},
    {"id": "q-m203-s01-031", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What skin prep is used before central line insertion (CDC bundle)?", "choices": ["2% chlorhexidine in alcohol, scrubbed 30 seconds", "Povidone-iodine, left on for 2 seconds", "70% alcohol alone, wiped on once", "Soap and water, rinsed and dried"], "correct": 0, "explanation": "Chlorhexidine 2% in 70% isopropyl alcohol scrubbed into the site for 30 seconds.", "srcItem": "Sterilization"},
    {"id": "q-m203-s01-032", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is VAP defined for exam purposes?", "choices": ["Pneumonia ≥ 48 hours after intubation, not present on admission", "Pneumonia that appears within the first 24 hours of intubation", "Any pneumonia at all in a patient on a ventilator", "Pneumonia that first appears after the patient is extubated"], "correct": 0, "explanation": "Safest answer: 48 hours or more after intubation, in a patient not admitted with pneumonia. (The deck says 48–72 hours.)", "srcItem": "VAP"},
    {"id": "q-m203-s01-033", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the PRIMARY mechanism of VAP?", "choices": ["Microaspiration of secretions pooled above the cuff", "Contamination of the wall oxygen supply", "Airborne spread from other ICU patients", "Blood-borne spread from infected IV lines"], "correct": 0, "explanation": "The ETT bypasses upper-airway defenses and secretions leak past the cuff. The single greatest risk factor is prolonged ventilation.", "srcItem": "VAP"},
    {"id": "q-m203-s01-034", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "VAP affects what percentage of ventilated patients?", "choices": ["10–25%", "1–2%", "50–60%", "75–90%"], "correct": 0, "explanation": "VAP affects 10–25% of ventilated patients, ~25% of ICU infections, with mortality 33–50%.", "srcItem": "VAP"},
    {"id": "q-m203-s01-035", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which findings raise suspicion of VAP?", "choices": ["New infiltrates plus fever, high WBC, purulent sputum", "Clear chest x-ray with a low-grade fever", "Improving compliance and a falling PIP", "Normal WBC with thin, white secretions"], "correct": 0, "explanation": "New or progressive infiltrates plus clinical signs. Confirmation requires a lower respiratory tract culture obtained before starting antibiotics.", "srcItem": "VAP"},
    {"id": "q-m203-s01-036", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "To what angle should the head of the bed be elevated to prevent VAP?", "choices": ["30–45 degrees", "0–10 degrees", "10–20 degrees", "60–90 degrees"], "correct": 0, "explanation": "HOB 30–45° unless contraindicated (e.g., after neurosurgery, severe hypotension).", "srcItem": "VAP"},
    {"id": "q-m203-s01-037", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which is part of the VAP prevention bundle?", "choices": ["Daily sedation vacation with a spontaneous breathing trial", "Changing the ventilator circuit every 24 hours", "Supine positioning at 0 degrees", "Routine nasal intubation"], "correct": 0, "explanation": "Bundle: HOB 30–45°, sedation vacation + SBT, peptic ulcer prophylaxis, DVT prophylaxis, chlorhexidine oral care, subglottic ETT, closed suction.", "srcItem": "VAP"},
    {"id": "q-m203-s01-038", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which agent is used for daily oral care to prevent VAP?", "choices": ["Chlorhexidine", "Hydrogen peroxide 3%", "Normal saline only", "Glutaraldehyde"], "correct": 0, "explanation": "Daily oral care with chlorhexidine, plus brushing teeth, rotating the ETT position every 24 hours, and moisturizer.", "srcItem": "VAP"},
    {"id": "q-m203-s01-039", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which suction system does the AARC endorse to reduce VAP?", "choices": ["In-line (closed) suction", "Open suction with a new catheter every pass", "Oral Yankauer suction only", "Nasotracheal suction"], "correct": 0, "explanation": "Closed suction means the circuit is never broken.", "srcItem": "VAP"},
    {"id": "q-m203-s01-040", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which route of intubation reduces VAP risk?", "choices": ["Oral", "Nasal", "Either — no difference", "Nasal with a larger tube"], "correct": 0, "explanation": "Use the oral route; nasal intubation causes sinusitis and more VAP. Avoid intubation entirely with NIV where possible.", "srcItem": "VAP"},
    {"id": "q-m203-s01-041", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "According to the deck, what is the single best way to prevent VAP?", "choices": ["Early liberation from the ventilator", "Prophylactic antibiotics for all patients", "Changing the circuit every day", "Using a larger endotracheal tube"], "correct": 0, "explanation": "Extubate as early as it is safe. Remember: cuff 20–30 cm H₂O, HOB 30–45°, wash hands, extubate early.", "srcItem": "VAP"},
    {"id": "q-m203-s01-042", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient has been ventilated for 10 days and develops VAP. Which organisms are most likely?", "choices": ["Resistant organisms including MRSA", "Upper-airway flora like S. pneumoniae", "Only viruses", "Only anaerobes from the mouth"], "correct": 0, "explanation": "First 48 hr: H. influenzae, S. pneumoniae. 3–7 days: gram-negative bacilli. > 7 days: resistant organisms including MRSA.", "srcItem": "VAP"},
    {"id": "q-m203-s01-043", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why is TB classically an UPPER-lobe disease?", "choices": ["It is aerobic and thrives where O₂ tension is highest", "The upper lobes receive the most blood flow", "Gravity carries the bacilli to the apices", "The lower lobes have more macrophages to kill it"], "correct": 0, "explanation": "Aerobic bacillus → lung apices. Its waxy capsule resists disinfectants and needs acid-fast staining.", "srcItem": "Tuberculosis"},
    {"id": "q-m203-s01-044", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why must a bronchoscope used on a TB patient be sterilized rather than just disinfected?", "choices": ["Its waxy capsule resists many disinfectants", "TB is spread only through the blood", "Bronchoscopes are noncritical items", "Sterilization is faster than disinfection"], "correct": 0, "explanation": "The waxy capsule resists disinfectants, so TB/hepatitis B exposure escalates a scope to sterilization.", "srcItem": "Tuberculosis"},
    {"id": "q-m203-s01-045", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is TB transmitted?", "choices": ["Airborne droplet nuclei from coughs and sneezes", "Direct skin-to-skin contact with the patient", "Contaminated food and drinking water", "Blood transfusion from an infected donor"], "correct": 0, "explanation": "Droplet nuclei (0.5–1.0 μm) stay airborne for hours — hence airborne precautions.", "srcItem": "Tuberculosis"},
    {"id": "q-m203-s01-046", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which statement about LATENT TB is correct?", "choices": ["Walled off, asymptomatic, and not infectious", "Active disease that is highly contagious", "Night sweats with bloody sputum", "The same thing as miliary TB"], "correct": 0, "explanation": "Latent: sealed in tubercles, dormant, asymptomatic, not infectious. Reactivation TB is highly infectious.", "srcItem": "Tuberculosis"},
    {"id": "q-m203-s01-047", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which set of symptoms suggests REACTIVATION (active) TB?", "choices": ["Low-grade fever, night sweats, weight loss, bloody sputum", "High fever, inspiratory stridor, drooling, and tripod position", "Wheezing that fully reverses after a dose of albuterol", "Pink frothy sputum with orthopnea and leg edema"], "correct": 0, "explanation": "Reactivation: low-grade fever, fatigue, night sweats, violent cough, green or bloody sputum, chest pain, anorexia, weight loss.", "srcItem": "Tuberculosis"},
    {"id": "q-m203-s01-048", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which test is recommended to diagnose LATENT TB infection?", "choices": ["Tuberculin skin test (PPD)", "Serial sputum AFB smears", "A chest x-ray alone", "Bronchoscopy with lavage"], "correct": 0, "explanation": "Heuer: skin test for latent TB; serial sputum AFB for active TB; CXR and IGRA added to confirm.", "srcItem": "Tuberculosis"},
    {"id": "q-m203-s01-049", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "When is a Mantoux (PPD) skin test read?", "choices": ["48–72 hours after injection", "15–30 minutes after injection", "7 days after injection", "24 hours after injection"], "correct": 0, "explanation": "Read the induration at 48–72 hours.", "srcItem": "Tuberculosis"},
    {"id": "q-m203-s01-050", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Using the deck's thresholds, a PPD induration of 12 mm is:", "choices": ["Positive — exposure or latent TB", "Negative", "Suspicious only", "Diagnostic of active TB"], "correct": 0, "explanation": "Deck: < 5 mm negative; 5–9 mm suspicious; ≥ 10 mm positive. Positive means exposure or latent TB, not necessarily active disease.", "srcItem": "Tuberculosis"},
    {"id": "q-m203-s01-051", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How many sputum samples are collected for AFB testing?", "choices": ["3, including an early-morning sample", "1 sample collected at any time", "5 samples spread over one week", "2 samples taken 1 hour apart"], "correct": 0, "explanation": "3 samples over 8–24 hours, each ≥ 5 mL of deep lung secretions; saliva is not acceptable.", "srcItem": "Tuberculosis"},
    {"id": "q-m203-s01-052", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What solution is used for sputum induction?", "choices": ["Hypertonic saline (3–10%) by nebulizer", "Sterile water by nebulizer", "Albuterol by MDI", "Normal saline instilled into the airway"], "correct": 0, "explanation": "Hypertonic saline via ultrasonic or continuous jet nebulizer for 15–20 min, in a negative-pressure room with the RT in an N95.", "srcItem": "Tuberculosis"},
    {"id": "q-m203-s01-053", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "During sputum induction, the FEV₁ falls 22% from baseline. What should the RT do?", "choices": ["Stop the procedure", "Continue for the full 20 minutes", "Switch to sterile water", "Increase the saline concentration"], "correct": 0, "explanation": "Stop if FEV₁ falls ≥ 20%. Pretreat reactive-airway patients with a fast-acting β-agonist.", "srcItem": "Tuberculosis"},
    {"id": "q-m203-s01-054", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which chest x-ray finding is classic for advanced TB?", "choices": ["Upper-lobe cavitary lesions", "Bilateral lower-lobe effusions", "Butterfly-pattern perihilar infiltrates", "Hyperlucent lower lobes with bullae"], "correct": 0, "explanation": "Upper-lobe/apical disease: Ghon nodule early, cavitation in advanced disease, calcification and fibrosis when chronic; miliary = tiny nodules throughout.", "srcItem": "Tuberculosis"},
    {"id": "q-m203-s01-055", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the induction phase of the 6-month TB regimen?", "choices": ["INH, RIF, PZA and EMB for 2 months", "INH alone for 1 full year", "RIF and INH for 6 months only", "PZA and EMB for 4 months only"], "correct": 0, "explanation": "Induction 2 months INH + RIF + PZA + EMB/SM; continuation 4 months INH + RIF. INH alone for 1 year is prophylaxis.", "srcItem": "Tuberculosis"},
    {"id": "q-m203-s01-056", "topic": "m203-s01", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is multidrug-resistant TB from noncompliance countered?", "choices": ["Directly Observed Therapy (DOT)", "Shortening the regimen", "Using INH alone", "Stopping treatment when symptoms improve"], "correct": 0, "explanation": "DOT: a healthcare worker watches each dose. Once resistance is documented, add ≥ 3 more antibiotics and extend the course.", "srcItem": "Tuberculosis"},
    {"id": "q-m203-s02-001", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the standard working pressure of piped hospital O₂ and air?", "choices": ["50 psi", "2200 psi", "15 psi", "500 psi"], "correct": 0, "explanation": "Piped wall gas runs at 50 psi — what ventilators, blenders and flowmeters are built for.", "srcItem": "Oxygen cylinders"},
    {"id": "q-m203-s02-002", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A full O₂ cylinder is assumed to be at what pressure for duration calculations?", "choices": ["2200 psi", "50 psi", "500 psi", "3000 psi"], "correct": 0, "explanation": "Heuer's table assumes 2200 psi, but filling pressures vary — always check the gauge first.", "srcItem": "Oxygen cylinders"},
    {"id": "q-m203-s02-003", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which safety system is used on the yoke of small cylinders (e.g., E cylinders)?", "choices": ["Pin Index Safety System (PISS)", "Diameter Index Safety System (DISS)", "American Standard Safety System (ASSS)", "Quick-connect wall system"], "correct": 0, "explanation": "PISS = small-cylinder yoke. DISS = threaded connection off 50-psi piped sources (ventilators, blenders, suction).", "srcItem": "Oxygen cylinders"},
    {"id": "q-m203-s02-004", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A small cylinder with a PISS regulator is hissing. What is the most likely cause?", "choices": ["A loose connection or a bad washer", "The cylinder is nearly empty", "Normal venting of excess pressure", "The flowmeter is set too high"], "correct": 0, "explanation": "Hissing = loose connection or missing/damaged washer. Tighten the regulator or replace the washer.", "srcItem": "Oxygen cylinders"},
    {"id": "q-m203-s02-005", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "After opening a cylinder valve fully, what should the RT do?", "choices": ["Turn it back half a turn", "Leave it fully open", "Close it one full turn", "Tap the gauge"], "correct": 0, "explanation": "Open slowly all the way, then back half a turn so the valve doesn't \"freeze\" fully open.", "srcItem": "Oxygen cylinders"},
    {"id": "q-m203-s02-006", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "When should an O₂ cylinder be changed out per Heuer?", "choices": ["When pressure drops below 500 psi", "When pressure drops below 1000 psi", "Only when completely empty", "When pressure drops below 50 psi"], "correct": 0, "explanation": "Change out 15–30 minutes before empty, or when below 500 psi.", "srcItem": "Oxygen cylinders"},
    {"id": "q-m203-s02-007", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How should a large cylinder be transported?", "choices": ["Chained to a wheeled cart", "Carried by hand", "Laid flat on the patient's bed", "Rolled on its base"], "correct": 0, "explanation": "Large cylinders go chained to a wheeled cart; small ones in the gurney or wheelchair holder.", "srcItem": "Oxygen cylinders"},
    {"id": "q-m203-s02-008", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which O₂ cylinder may be taken into the MRI suite?", "choices": ["An aluminum cylinder", "A steel E cylinder", "Any cylinder if it is full", "A steel cylinder with a brass regulator"], "correct": 0, "explanation": "Iron-free equipment only — the magnet can turn a steel cylinder into a projectile.", "srcItem": "Oxygen cylinders"},
    {"id": "q-m203-s02-009", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "For a transport with a possible delay, how much O₂ should be carried?", "choices": ["At least twice the volume needed for a one-way trip", "Exactly the volume for a one-way trip", "Half a cylinder", "Whatever is in the cylinder"], "correct": 0, "explanation": "The transport deck: an E cylinder must be full, and carry at least twice the one-way volume.", "srcItem": "Oxygen cylinders"},
    {"id": "q-m203-s02-010", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the duration-of-flow formula for a gas cylinder?", "choices": ["(gauge pressure × cylinder factor) ÷ flow", "(cylinder factor ÷ gauge pressure) × flow", "(gauge pressure ÷ flow) − cylinder factor", "flow × gauge pressure ÷ 60"], "correct": 0, "explanation": "Duration (min) = (psig × factor) ÷ L/min.", "srcItem": "Cylinder factors"},
    {"id": "q-m203-s02-011", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the cylinder factor for an E cylinder?", "choices": ["0.28 L/psig", "0.16 L/psig", "3.14 L/psig", "2.41 L/psig"], "correct": 0, "explanation": "D 0.16, E 0.28, G 2.41 (Heuer also prints 2.14), H/K 3.14.", "srcItem": "Cylinder factors"},
    {"id": "q-m203-s02-012", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the cylinder factor for an H or K cylinder?", "choices": ["3.14 L/psig", "0.28 L/psig", "2.41 L/psig", "0.16 L/psig"], "correct": 0, "explanation": "H/K = 3.14.", "srcItem": "Cylinder factors"},
    {"id": "q-m203-s02-013", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the cylinder factor for a D cylinder?", "choices": ["0.16 L/psig", "0.28 L/psig", "0.07 L/psig", "0.11 L/psig"], "correct": 0, "explanation": "D = 0.16; E = 0.28.", "srcItem": "Cylinder factors"},
    {"id": "q-m203-s02-014", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An E cylinder reads 800 psi and is running at 5 L/min. How long until it is empty?", "choices": ["About 45 minutes", "About 28 minutes", "About 160 minutes", "About 72 minutes"], "correct": 0, "explanation": "(800 × 0.28) ÷ 5 = 224 ÷ 5 = 44.8 ≈ 45 min (Heuer Problem B.26).", "srcItem": "Cylinder factors"},
    {"id": "q-m203-s02-015", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A full E cylinder (2200 psi) runs at 3 L/min. Using the 500-psi change-out rule, how long until it must be changed?", "choices": ["About 2 hours 39 minutes", "About 3 hours 25 minutes", "About 1 hour 30 minutes", "About 45 minutes"], "correct": 0, "explanation": "(2200 − 500) × 0.28 ÷ 3 = 476 ÷ 3 = 158.7 min.", "srcItem": "Cylinder factors"},
    {"id": "q-m203-s02-016", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An H cylinder reads 1800 psi and the patient needs 6 L/min. How long will it last?", "choices": ["About 15.7 hours", "About 1.4 hours", "About 9.4 hours", "About 21 hours"], "correct": 0, "explanation": "(1800 × 3.14) ÷ 6 = 5652 ÷ 6 = 942 min = 15.7 hr.", "srcItem": "Cylinder factors"},
    {"id": "q-m203-s02-017", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A D cylinder reads 1000 psi at 2 L/min. How long will it last?", "choices": ["80 minutes", "140 minutes", "50 minutes", "32 minutes"], "correct": 0, "explanation": "(1000 × 0.16) ÷ 2 = 160 ÷ 2 = 80 min.", "srcItem": "Cylinder factors"},
    {"id": "q-m203-s02-018", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An E cylinder reads 1500 psi at 4 L/min. How long will it last?", "choices": ["105 minutes", "60 minutes", "168 minutes", "75 minutes"], "correct": 0, "explanation": "(1500 × 0.28) ÷ 4 = 420 ÷ 4 = 105 min.", "srcItem": "Cylinder factors"},
    {"id": "q-m203-s02-019", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "As a ballpark, how long does a full E cylinder last at 10 L/min?", "choices": ["About 1 hour", "About 10 hours", "About 10 minutes", "About 3 hours"], "correct": 0, "explanation": "Full E at 10 L/min ≈ 1 hr; full H at 10 L/min ≈ 10 hr.", "srcItem": "Cylinder factors"},
    {"id": "q-m203-s02-020", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "1 liter of liquid oxygen vaporizes into about how many liters of gas?", "choices": ["860 L", "344 L", "100 L", "2200 L"], "correct": 0, "explanation": "1 L liquid = 860 L gas; 1 lb LOX ≈ 344 L gas.", "srcItem": "LOX"},
    {"id": "q-m203-s02-021", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "1 pound of liquid oxygen yields about how many liters of gaseous O₂?", "choices": ["344 L", "860 L", "28 L", "100 L"], "correct": 0, "explanation": "Gaseous O₂ (L) = LOX weight (lb) × 344.", "srcItem": "LOX"},
    {"id": "q-m203-s02-022", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A home LOX base unit holds 75 lb and runs at 2 L/min continuously. About how long will it last?", "choices": ["About 9 days", "About 2 days", "About 30 days", "About 18 hours"], "correct": 0, "explanation": "75 × 344 = 25,800 L ÷ 2 = 12,900 min ≈ 215 hr ≈ 9 days.", "srcItem": "LOX"},
    {"id": "q-m203-s02-023", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A LOX reservoir holds 50 lb, running at 2 L/min. About how long will it last?", "choices": ["About 6 days", "About 12 days", "About 1 day", "About 3 days"], "correct": 0, "explanation": "50 × 344 = 17,200 L ÷ 2 = 8,600 min ≈ 143 hr ≈ 6 days.", "srcItem": "LOX"},
    {"id": "q-m203-s02-024", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient's stationary LOX tank makes an occasional, intermittent hissing sound. What should the RT tell the patient?", "choices": ["This is normal venting — keep the tank upright", "Switch to backup O₂ and call the supplier", "Turn the tank off immediately", "Tighten the regulator washer"], "correct": 0, "explanation": "Intermittent hissing is normal. Loud, constant hissing with visible mist is a problem → backup O₂, call supplier.", "srcItem": "LOX"},
    {"id": "q-m203-s02-025", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A LOX tank makes loud, constant hissing with a steady stream of mist. What should be done?", "choices": ["Switch to backup O₂ and call the supplier", "Nothing — continuous hissing is normal", "Lay the tank on its side to stop venting", "Increase the flow rate to use the gas up"], "correct": 0, "explanation": "Loud constant hissing + mist is a malfunction.", "srcItem": "LOX"},
    {"id": "q-m203-s02-026", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How long does a typical full portable LOX unit last with a demand-flow device?", "choices": ["8 hours or more", "About 1 hour", "About 24 hours", "About 3 days"], "correct": 0, "explanation": "~1 L LOX, < 6 lb, 8+ hours with a conserving device.", "srcItem": "LOX"},
    {"id": "q-m203-s02-027", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How does an oxygen concentrator produce O₂?", "choices": ["A sieve adsorbs nitrogen from room air", "It vaporizes stored liquid oxygen", "It splits water into H₂ and O₂", "It compresses room air to 2200 psi"], "correct": 0, "explanation": "The sieve adsorbs nitrogen, CO₂ and water vapor, letting O₂ pass through.", "srcItem": "Concentrators"},
    {"id": "q-m203-s02-028", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What O₂ concentration does a concentrator produce?", "choices": ["About 90–95% up to 10 L/min", "100% at any flow setting", "About 50–60% at low flows", "About 21%, the same as room air"], "correct": 0, "explanation": "90–95% up to 10 L/min. Higher flow = less contact time with the sieve.", "srcItem": "Concentrators"},
    {"id": "q-m203-s02-029", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A concentrator's analyzed output is below 85–90% of the manufacturer's spec. What is the cause and action?", "choices": ["Exhausted sieve — use backup, replace the unit", "Dirty intake filter — clean it and continue", "Flow set too low — increase it and recheck", "Normal for concentrators — no action needed"], "correct": 0, "explanation": "Exhausted sodium-aluminum pellets → gaseous backup and replace/service the concentrator.", "srcItem": "Concentrators"},
    {"id": "q-m203-s02-030", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A concentrator alarm sounds. What is the first thing to check?", "choices": ["Dirty or blocked intake filters", "The LOX reservoir level", "The PISS regulator washer", "A wrong cylinder factor"], "correct": 0, "explanation": "Clean the intake filters and keep the unit away from walls and curtains.", "srcItem": "Concentrators"},
    {"id": "q-m203-s02-031", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient using a concentrator at 4 L/min by cannula complains of nasal dryness. What should the RT do?", "choices": ["Add a bubble humidifier", "Reduce the flow to 1 L/min", "Switch to LOX", "Change to a nonrebreather"], "correct": 0, "explanation": "At ≥ 4 L/min, add a bubble humidifier for nasal dryness.", "srcItem": "Concentrators"},
    {"id": "q-m203-s02-032", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Most portable oxygen concentrators deliver pulse-dose only. What is their limit?", "choices": ["About 30% O₂ or less", "About 60% O₂", "100% O₂", "About 45% O₂"], "correct": 0, "explanation": "Pulse-dose POCs suit patients needing ≤ 30% O₂; only continuous-flow units exceed 30%.", "srcItem": "Concentrators"},
    {"id": "q-m203-s02-033", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "For air travel with a POC, how much battery should the patient carry?", "choices": ["At least 150% of the one-way travel time", "Exactly the flight time", "One spare battery only", "None — airlines provide power"], "correct": 0, "explanation": "Airlines aren't required to supply electricity or oxygen; carry battery for ≥ 150% of one-way travel.", "srcItem": "Concentrators"},
    {"id": "q-m203-s02-034", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which home O₂ system is the most cost-efficient for continuous low-flow O₂?", "choices": ["An oxygen concentrator", "A liquid oxygen system", "Several H cylinders", "Several E cylinders"], "correct": 0, "explanation": "Concentrators are the most cost-efficient for continuous low-flow; they never run out while powered.", "srcItem": "Home O₂ devices"},
    {"id": "q-m203-s02-035", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient with restricted activity needs home O₂. What system should the RT recommend?", "choices": ["Concentrator plus a backup cylinder", "A portable LOX unit by itself", "E cylinders delivered weekly", "A portable concentrator by itself"], "correct": 0, "explanation": "Restricted activity → concentrator + backup cylinder. Ambulatory → always add a portable source.", "srcItem": "Home O₂ devices"},
    {"id": "q-m203-s02-036", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An active, ambulatory home O₂ patient needs extended flow duration. What should be added?", "choices": ["An O₂-conserving device", "A larger H cylinder", "A bubble humidifier", "A nonrebreather mask"], "correct": 0, "explanation": "Conserving devices cut O₂ use by 50–75%, doubling or tripling duration.", "srcItem": "Home O₂ devices"},
    {"id": "q-m203-s02-037", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "By how much do O₂-conserving devices reduce O₂ usage?", "choices": ["50–75%", "5–10%", "90–100%", "About 25%"], "correct": 0, "explanation": "50–75%, doubling or tripling duration of flow from any source.", "srcItem": "Home O₂ devices"},
    {"id": "q-m203-s02-038", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient uses O₂ only during sleep. What system is sufficient?", "choices": ["A stationary system only", "A portable LOX unit", "A pulse-dose POC", "Multiple E cylinders"], "correct": 0, "explanation": "Sleep-only users don't need a portable source.", "srcItem": "Home O₂ devices"},
    {"id": "q-m203-s02-039", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A demand-flow device fails. What continuous flow should be used as a backup?", "choices": ["2–3 times the conserving-device setting", "The same setting", "Half the setting", "10 L/min regardless of setting"], "correct": 0, "explanation": "If the conserving device fails, switch to continuous O₂ at 2–3× the conserving-device flow.", "srcItem": "Home O₂ devices"},
    {"id": "q-m203-s02-040", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What are the Medicare qualifying criteria for home O₂ at rest?", "choices": ["SpO₂ ≤ 88% or PaO₂ ≤ 55 torr", "SpO₂ ≤ 92% or PaO₂ ≤ 65 torr", "SpO₂ ≤ 95% or PaO₂ ≤ 75 torr", "SpO₂ ≤ 85% and PaO₂ ≤ 45 torr"], "correct": 0, "explanation": "For a hospitalized patient, the value must be obtained no sooner than 48 hours before discharge.", "srcItem": "Home O₂ devices"},
    {"id": "q-m203-s02-041", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On a nasal cannula, each 1 L/min adds roughly how much to the FiO₂?", "choices": ["About 4%", "About 10%", "About 1%", "About 20%"], "correct": 0, "explanation": "1 L ≈ 24%, 2 L ≈ 28%, up to 6 L ≈ 44–45%.", "srcItem": "Flow and delivered O₂"},
    {"id": "q-m203-s02-042", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Approximately what FiO₂ does a nasal cannula at 3 L/min deliver?", "choices": ["About 32%", "About 24%", "About 40%", "About 50%"], "correct": 0, "explanation": "21% + (3 × 4%) ≈ 33%, i.e., about 32%.", "srcItem": "Flow and delivered O₂"},
    {"id": "q-m203-s02-043", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On a low-flow device, which patient change LOWERS the delivered FiO₂?", "choices": ["Faster rate and larger tidal volume", "Slower rate and smaller volume", "Smaller tidal volume alone", "Lower minute ventilation"], "correct": 0, "explanation": "Higher inspiratory flow, VT, rate or minute ventilation → more room-air dilution → lower FiO₂.", "srcItem": "Flow and delivered O₂"},
    {"id": "q-m203-s02-044", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why are low-flow devices ordered in L/min rather than as an FiO₂?", "choices": ["FiO₂ varies with breathing pattern", "They always deliver exactly 28%", "FiO₂ cannot be measured at all", "Only high-flow devices use L/min"], "correct": 0, "explanation": "Low-flow gas is less than the patient's inspiratory flow, so it is diluted with room air — FiO₂ is variable.", "srcItem": "Flow and delivered O₂"},
    {"id": "q-m203-s02-045", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On a high-flow air-entrainment device, how should oxygenation be adjusted?", "choices": ["Change the FiO₂, not the flow", "Change the flow, not the FiO₂", "Change both together always", "Add a reservoir bag"], "correct": 0, "explanation": "Turning the flow down doesn't change FiO₂ but may fail to meet demand, making FiO₂ variable again.", "srcItem": "Flow and delivered O₂"},
    {"id": "q-m203-s02-046", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Aerosol tubing is completely filled with water and there is no gurgling sound. What should the RT do?", "choices": ["Drain the tubing and add a water trap", "Increase the flow to 15 L/min", "Replace the nebulizer unit", "Lower the FiO₂ setting"], "correct": 0, "explanation": "Tubing blocked by condensate → drain and add a water trap at low points.", "srcItem": "Condensate"},
    {"id": "q-m203-s02-047", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "The analyzed O₂% on an air-entrainment nebulizer is HIGHER than set. What is the likely cause?", "choices": ["Condensate causing back pressure", "A leak at the humidifier jar", "A disconnected O₂ source", "A flowmeter set too low"], "correct": 0, "explanation": "Back pressure acts like a partially obstructed entrainment port → less air entrained → higher O₂%. Drain and add a water trap.", "srcItem": "Condensate"},
    {"id": "q-m203-s02-048", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why does condensate (rainout) form in heated circuits?", "choices": ["Saturated gas cools along the tubing", "The humidifier jar is overfilled", "The patient exhales too much water", "The set gas flow is too low"], "correct": 0, "explanation": "Fixes: heated-wire circuit, inline water trap, or an HME for temporary use.", "srcItem": "Condensate"},
    {"id": "q-m203-s02-049", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "In an air-entrainment device, what happens when the entrainment port is made LARGER?", "choices": ["Lower FiO₂ and higher total flow", "Higher FiO₂ and higher total flow", "Higher FiO₂ and lower total flow", "Lower FiO₂ and lower total flow"], "correct": 0, "explanation": "Bigger ports / smaller jets → more air → lower FiO₂, higher total flow.", "srcItem": "Air-entrainment"},
    {"id": "q-m203-s02-050", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the air-to-O₂ ratio for 40% O₂?", "choices": ["3:1", "1:1", "5:1", "10:1"], "correct": 0, "explanation": "(100 − 40) ÷ (40 − 21) = 60 ÷ 19 ≈ 3:1.", "srcItem": "Air-entrainment"},
    {"id": "q-m203-s02-051", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the air-to-O₂ ratio for 60% O₂?", "choices": ["1:1", "3:1", "1.7:1", "0.6:1"], "correct": 0, "explanation": "60% is the pivot at 1:1. Below 60% the ratio is > 1:1; above 60% it is < 1:1.", "srcItem": "Air-entrainment"},
    {"id": "q-m203-s02-052", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the air-to-O₂ ratio for 28% O₂?", "choices": ["10:1", "5:1", "25:1", "3:1"], "correct": 0, "explanation": "(100 − 28) ÷ (28 − 21) = 72 ÷ 7 ≈ 10:1. 24% = 25:1; 35% = 5:1.", "srcItem": "Air-entrainment"},
    {"id": "q-m203-s02-053", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A 35% air-entrainment mask is set at 8 L/min. What is the total flow?", "choices": ["48 L/min", "40 L/min", "32 L/min", "56 L/min"], "correct": 0, "explanation": "35% = 5:1 → 6 total parts × 8 = 48 L/min (Heuer B.27/B.28).", "srcItem": "Air-entrainment"},
    {"id": "q-m203-s02-054", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A 40% air-entrainment mask is set at 8 L/min. Does it meet a 40 L/min inspiratory demand?", "choices": ["No — total flow is 32 L/min", "Yes — total flow is 48 L/min", "Yes — total flow is 40 L/min", "No — total flow is 24 L/min"], "correct": 0, "explanation": "40% = 3:1 → 4 parts × 8 = 32 L/min < 40. Raise input to 12 L/min → 48 L/min.", "srcItem": "Air-entrainment"},
    {"id": "q-m203-s02-055", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A 28% Venturi mask runs at 4 L/min. What is the total flow?", "choices": ["44 L/min", "40 L/min", "28 L/min", "112 L/min"], "correct": 0, "explanation": "28% = 10:1 → 11 parts × 4 = 44 L/min.", "srcItem": "Air-entrainment"},
    {"id": "q-m203-s02-056", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What total flow does Heuer say ensures a stable FiO₂?", "choices": ["At least 40 L/min", "At least 10 L/min", "At least 15 L/min", "At least 100 L/min"], "correct": 0, "explanation": "\"The best way to ensure a stable FIO₂ is to provide a total flow of at least 40 L/min.\"", "srcItem": "Air-entrainment"},
    {"id": "q-m203-s02-057", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient needs 70% O₂ with a high inspiratory flow demand. Which is the best approach?", "choices": ["A blender system or heated HFNC", "One entrainment nebulizer at 15 L/min", "A nasal cannula at 6 L/min", "A 28% Venturi mask at 4 L/min"], "correct": 0, "explanation": "At 70%, 15 × 1.6 = 24 L/min — entrainment fails. Above 0.60 at > 40 L/min, use a blender system or HFNC.", "srcItem": "Air-entrainment"},
    {"id": "q-m203-s02-058", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Raising the O₂ input flow on an air-entrainment device changes:", "choices": ["The total flow, not the FiO₂", "The FiO₂, not the total flow", "Both FiO₂ and total flow", "Neither"], "correct": 0, "explanation": "The ratio (and FiO₂) is set by the port/jet; input flow changes total flow.", "srcItem": "Air-entrainment"},
    {"id": "q-m203-s02-059", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the minimum flow for a nonrebreather mask?", "choices": ["10 L/min — enough to keep the bag up", "2 L/min — enough for most adults", "6 L/min — same as a simple mask", "4 L/min — to prevent CO₂ buildup"], "correct": 0, "explanation": "Minimum 10 L/min — the flow that keeps the reservoir bag from collapsing.", "srcItem": "NRB"},
    {"id": "q-m203-s02-060", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What FiO₂ does a nonrebreather deliver per Heuer?", "choices": ["60–80%", "100%", "24–44%", "40–50%"], "correct": 0, "explanation": "Heuer Table 6-1: 60–80%. It is a low-flow/variable-performance reservoir device.", "srcItem": "NRB"},
    {"id": "q-m203-s02-061", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "The NRB reservoir bag collapses when the patient inhales. What should the RT do?", "choices": ["Increase the flow", "Decrease the flow", "Replace the mask", "Nothing — this is normal"], "correct": 0, "explanation": "A collapsing bag = flow too low or minute ventilation increased — turn it up.", "srcItem": "NRB"},
    {"id": "q-m203-s02-062", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "The NRB bag stays fully inflated during inhalation. What is the first likely cause?", "choices": ["Flow is too high", "Flow is too low", "The patient is apneic only", "The O₂ tubing is disconnected"], "correct": 0, "explanation": "Too much flow → decrease until the bag deflates slightly on inspiration. If flow is right: large mask leak, then a jammed/reversed valve.", "srcItem": "NRB"},
    {"id": "q-m203-s02-063", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A physician orders an NRB for a patient in respiratory arrest. What should the RT recommend?", "choices": ["A bag-valve-mask with 100% O₂", "An NRB at 15 L/min", "A nasal cannula at 6 L/min", "A Venturi mask at 50%"], "correct": 0, "explanation": "An NRB does not provide ventilation. Recommend a BVM that can give 100% O₂ and ventilate.", "srcItem": "NRB"},
    {"id": "q-m203-s02-064", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient's SpO₂ rises only from 83% to 87% when switched from a simple mask to an NRB. What should the RT recommend?", "choices": ["HFNC at 20–40 L/min or mask CPAP", "A nasal cannula at 6 L/min", "Continuing the NRB unchanged", "A 28% Venturi mask"], "correct": 0, "explanation": "The patient can't meet high inspiratory demand or is shunting. HFNC titrated to SpO₂, or mask CPAP.", "srcItem": "NRB"},
    {"id": "q-m203-s02-065", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What happens if the valves are removed from a nonrebreather?", "choices": ["It becomes a partial rebreathing mask", "It delivers 100% O₂", "It becomes a Venturi mask", "It becomes a simple mask with no bag"], "correct": 0, "explanation": "Hess: removing the valves converts the NRB to a partial rebreather (6–10 L/min, 40–70%).", "srcItem": "NRB"},
    {"id": "q-m203-s02-066", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is a Briggs adaptor?", "choices": ["A T-piece joining aerosol tubing to an airway", "A valve that adds PEEP to a circuit", "A regulator for small O₂ cylinders", "A type of high-flow nasal cannula"], "correct": 0, "explanation": "The T-piece (Briggs adapter) is an LVN interface: inspiratory limb in, stem to the airway, expiratory arm open.", "srcItem": "Briggs adaptor"},
    {"id": "q-m203-s02-067", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why is reservoir tubing added to the expiratory limb of a Briggs adaptor?", "choices": ["So the patient draws source gas instead of room air", "To add PEEP", "To collect condensate", "To increase the O₂ percentage above the set value"], "correct": 0, "explanation": "It keeps the FiO₂ stable when the patient's demand exceeds the nebulizer output.", "srcItem": "Briggs adaptor"},
    {"id": "q-m203-s02-068", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On a T-piece, the aerosol mist disappears during inspiration. What does this mean?", "choices": ["Flow is inadequate for demand", "The FiO₂ is set too high", "The nebulizer is overfilled", "The patient is hypoventilating"], "correct": 0, "explanation": "Fix: maximize input flow, add expiratory reservoir tubing, or run nebulizers in parallel.", "srcItem": "Briggs adaptor"},
    {"id": "q-m203-s02-069", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is a T-piece used during weaning?", "choices": ["For an SBT with no ventilator support", "To deliver 10 cm H₂O of PEEP", "To deliver pressure support", "To measure the patient's NIF"], "correct": 0, "explanation": "A T-piece SBT gives no assistance; the patient does all the work, typically for 30 minutes.", "srcItem": "Briggs adaptor"},
    {"id": "q-m203-s02-070", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why is a Bourdon gauge used on transport cylinders instead of a Thorpe tube?", "choices": ["It is not affected by gravity", "It is more accurate with back pressure", "It measures FiO₂", "It is cheaper"], "correct": 0, "explanation": "A Thorpe tube floats a ball in a vertical tube and must stay upright; a Bourdon gauge reads the same at any angle.", "srcItem": "Bourdon vs Thorpe"},
    {"id": "q-m203-s02-071", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A Bourdon gauge's outlet becomes completely obstructed. What does the gauge show?", "choices": ["It still shows flow", "It shows zero flow", "It sounds a flow alarm", "It shows double the flow"], "correct": 0, "explanation": "A Bourdon gauge is a pressure gauge calibrated in L/min; back pressure makes it over-read. A fully obstructed Bourdon still reads flow.", "srcItem": "Bourdon vs Thorpe"},
    {"id": "q-m203-s02-072", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which flowmeter shows the ACTUAL outlet flow regardless of downstream resistance?", "choices": ["Pressure-compensated Thorpe tube", "Bourdon gauge", "Uncompensated Thorpe tube", "Flow restrictor"], "correct": 0, "explanation": "A pressure-compensated Thorpe tube displays actual flow regardless of downstream resistance.", "srcItem": "Bourdon vs Thorpe"},
    {"id": "q-m203-s02-073", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How should the accuracy of an O₂ blender be checked?", "choices": ["Check it with a calibrated O₂ analyzer", "Trust the dial setting on the blender", "Check the flowmeter ball position", "Check the cylinder pressure gauge"], "correct": 0, "explanation": "Verify with a second instrument. If off, check both source pressures and leaks, then replace the blender.", "srcItem": "Bourdon vs Thorpe"},
    {"id": "q-m203-s02-074", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "80/20 heliox is run through an O₂ flowmeter set at 10 L/min. What is the actual flow?", "choices": ["18 L/min", "10 L/min", "8 L/min", "12.5 L/min"], "correct": 0, "explanation": "Correction factors: 80/20 = 1.8; 70/30 = 1.6; 60/40 = 1.4. 10 × 1.8 = 18 L/min.", "srcItem": "Bourdon vs Thorpe"},
    {"id": "q-m203-s02-075", "topic": "m203-s02", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "70/30 heliox is run through an O₂ flowmeter set at 8 L/min. What is the actual flow?", "choices": ["12.8 L/min", "14.4 L/min", "8 L/min", "11.2 L/min"], "correct": 0, "explanation": "70/30 factor = 1.6 → 8 × 1.6 = 12.8 L/min.", "srcItem": "Bourdon vs Thorpe"},
    {"id": "q-m203-s03-001", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "When should a patient prime an MDI?", "choices": ["When new or unused for a few days", "Before every single puff", "Only when the canister is cold", "Never — it wastes medication"], "correct": 0, "explanation": "Shake and prime (waste a dose into the air) if new or unused for a few days. Warm a cold canister in the hands.", "srcItem": "MDI education"},
    {"id": "q-m203-s03-002", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Using the open-mouth MDI technique, how far from the mouth should the MDI be held?", "choices": ["About 2 inches (two finger widths)", "Sealed directly on the lips", "About 6 inches from the mouth", "About 12 inches from the mouth"], "correct": 0, "explanation": "Open-mouth: 2 inches away with the tongue down, which enhances lung deposition.", "srcItem": "MDI education"},
    {"id": "q-m203-s03-003", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "When should the patient actuate the MDI?", "choices": ["At the start of a slow, deep breath", "Just before starting to inhale", "At the very end of inhalation", "During a slow exhalation"], "correct": 0, "explanation": "Actuate at the start of a slow, deep 3–5 second inhalation — not before, not after.", "srcItem": "MDI education"},
    {"id": "q-m203-s03-004", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How long should the patient hold the breath after an MDI puff?", "choices": ["10 seconds", "2 seconds", "30 seconds", "No breath-hold is needed"], "correct": 0, "explanation": "A 10-second breath-hold allows maximum deposition (gravitational settling).", "srcItem": "MDI education"},
    {"id": "q-m203-s03-005", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How long should the patient wait between MDI puffs?", "choices": ["About 1 minute", "About 5 seconds", "About 10 minutes", "No wait is needed"], "correct": 0, "explanation": "Wait about 1 minute between puffs.", "srcItem": "MDI education"},
    {"id": "q-m203-s03-006", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why must a patient rinse and spit after using a steroid MDI?", "choices": ["To prevent thrush and reduce absorption", "To remove the propellant taste only", "To rinse the MDI mouthpiece clean", "To speed up the drug's onset"], "correct": 0, "explanation": "Rinse and spit prevents pharyngitis and thrush and reduces the drug swallowed.", "srcItem": "MDI education"},
    {"id": "q-m203-s03-007", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How should the RT confirm the patient learned MDI technique?", "choices": ["Ask for a return demonstration (teach-back)", "Ask whether the patient understood", "Give a printed handout", "Watch the patient take the first home dose"], "correct": 0, "explanation": "Confirm learning with a return demonstration: \"Show me how you'll use your inhaler at home.\"", "srcItem": "MDI education"},
    {"id": "q-m203-s03-008", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An adult who is not acutely ill cannot coordinate MDI actuation with breathing. What should the RT recommend?", "choices": ["Add a valved holding chamber (or a breath-actuated MDI)", "Switch to a DPI with a spacer", "Stop the MDI and use oral medication", "Tell the patient to actuate twice per breath"], "correct": 0, "explanation": "Heuer: add a holding chamber; a breath-actuated MDI is the alternative.", "srcItem": "MDI education"},
    {"id": "q-m203-s03-009", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the main advantage of a spacer or valved holding chamber?", "choices": ["Less throat deposition, less coordination", "A faster onset of drug action", "A higher dose delivered per puff", "No need to rinse after steroids"], "correct": 0, "explanation": "The propellant dries and large particles fall out — less throat deposition and less thrush with steroids.", "srcItem": "MDI education"},
    {"id": "q-m203-s03-010", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How does a valved holding chamber differ from a plain spacer?", "choices": ["A one-way valve holds the aerosol until inhalation", "It has no valve and requires perfect timing", "It is designed for use with DPIs only", "It turns the MDI dose into a nebulized mist"], "correct": 0, "explanation": "The valve stops the patient from exhaling into the chamber and gives a bit more deposition. VHCs are preferred.", "srcItem": "MDI education"},
    {"id": "q-m203-s03-011", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How many MDI puffs should be actuated into a holding chamber per inhalation?", "choices": ["One", "Two", "Four", "As many as prescribed at once"], "correct": 0, "explanation": "Actuate only once per inhalation — never stack puffs into the chamber.", "srcItem": "MDI education"},
    {"id": "q-m203-s03-012", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A small child uses an MDI with a holding chamber and face mask. How many breaths per actuation?", "choices": ["3–5 breaths", "1 breath", "10–12 breaths", "20 breaths"], "correct": 0, "explanation": "With a mask, 3–5 breaths per actuation. The mask cuts lung deposition by 50% — wean to a mouthpiece when possible.", "srcItem": "MDI education"},
    {"id": "q-m203-s03-013", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How should a plastic valved holding chamber be cleaned?", "choices": ["Monthly in dilute detergent, then air-dried", "Daily with alcohol, then towel-dried", "Weekly in bleach, then rinsed", "Never — replace it every month"], "correct": 0, "explanation": "Air-dry; hand-drying builds an electrostatic charge that pulls drug onto the walls.", "srcItem": "MDI education"},
    {"id": "q-m203-s03-014", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which device must NEVER be used with a spacer or holding chamber?", "choices": ["A dry-powder inhaler", "A pressurized MDI", "A small-volume nebulizer", "An MDI with a mask"], "correct": 0, "explanation": "DPIs, breath-actuated MDIs and Respimat cannot be used with a spacer or VHC.", "srcItem": "MDI education"},
    {"id": "q-m203-s03-015", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "The pMDI is the method of choice for children under 5 years old ONLY when:", "choices": ["It is used with a spacer or valved holding chamber", "The child can hold the breath 10 seconds", "It is breath-actuated", "It is used without a mask"], "correct": 0, "explanation": "Under 5 years: pMDI only with a reservoir device.", "srcItem": "Aerosol modalities"},
    {"id": "q-m203-s03-016", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How does a dry-powder inhaler work?", "choices": ["The patient's inspiratory flow disperses it", "A propellant sprays the drug out", "Compressed gas nebulizes the drug", "A vibrating mesh creates a mist"], "correct": 0, "explanation": "DPIs are breath-actuated — no propellant, no timing problem, but they need a high inspiratory flow.", "srcItem": "Aerosol modalities"},
    {"id": "q-m203-s03-017", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What inspiratory flow does a DPI require (Heuer Ch 12)?", "choices": ["A rapid, deep inhalation of about 60 L/min", "A slow inhalation of about 10 L/min", "A normal tidal breath", "A 3–5 second slow inhalation at 30 L/min"], "correct": 0, "explanation": "Heuer: rapid, deep inhalation at 60 L/min (the deck says 30–90 L/min). Children under 4 usually can't generate it.", "srcItem": "Aerosol modalities"},
    {"id": "q-m203-s03-018", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which instruction about DPIs is correct?", "choices": ["Never exhale into the device after loading it", "Rinse the device in water after each use", "Use it with a spacer for better deposition", "Inhale slowly over 5 seconds"], "correct": 0, "explanation": "Exhaling into it loses the dose and cakes the powder. Keep it dry; never use with a spacer.", "srcItem": "Aerosol modalities"},
    {"id": "q-m203-s03-019", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An acutely ill adult cannot use an MDI or DPI. Which device is the fallback?", "choices": ["Small-volume jet nebulizer", "Dry-powder inhaler", "Breath-actuated MDI", "SPAG-2 generator"], "correct": 0, "explanation": "The SVN needs the least coordination — slow tidal breathing with occasional deep breaths, any age.", "srcItem": "Aerosol modalities"},
    {"id": "q-m203-s03-020", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What gas flow should power a small-volume jet nebulizer?", "choices": ["6–8 L/min of O₂ or air", "2–3 L/min", "12–15 L/min", "50 psi unrestricted"], "correct": 0, "explanation": "6–8 L/min produces the optimal 1–5 μm particle size.", "srcItem": "Aerosol modalities"},
    {"id": "q-m203-s03-021", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why is a mouthpiece preferred over a face mask for SVN treatments?", "choices": ["A face mask cuts lung deposition by about 50%", "A mouthpiece increases the drug dose", "A face mask cannot be used with oxygen", "A mouthpiece speeds the treatment"], "correct": 0, "explanation": "Mask use halves lung deposition. Avoid \"blow-by\" in infants.", "srcItem": "Aerosol modalities"},
    {"id": "q-m203-s03-022", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which nebulizer should be avoided for suspensions because its crystal's heat can degrade some drugs?", "choices": ["Ultrasonic nebulizer", "Vibrating-mesh nebulizer", "Jet nebulizer", "SPAG-2 generator"], "correct": 0, "explanation": "The USN's piezoelectric crystal generates heat; not for suspensions.", "srcItem": "Aerosol modalities"},
    {"id": "q-m203-s03-023", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which nebulizer is preferred for mechanically ventilated patients and adds no gas flow to the circuit?", "choices": ["Vibrating-mesh nebulizer", "Jet nebulizer", "Ultrasonic nebulizer", "SPAG-2"], "correct": 0, "explanation": "Vibrating mesh: electric, no propellant or compressor, uniform fine mist, preferred in-line.", "srcItem": "Aerosol modalities"},
    {"id": "q-m203-s03-024", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which device is used to deliver aerosolized ribavirin for RSV?", "choices": ["SPAG-2", "Vibrating-mesh nebulizer", "Dry-powder inhaler", "Ultrasonic nebulizer"], "correct": 0, "explanation": "The Small Particle Aerosol Generator (≈1.3 μm). Replace the reservoir solution every 24 hours.", "srcItem": "Aerosol modalities"},
    {"id": "q-m203-s03-025", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What particle size range is the bronchoactive target for bronchodilators?", "choices": ["2–5 μm", "Over 10 μm", "5–10 μm", "Under 1 μm"], "correct": 0, "explanation": "> 10 μm → upper airway; 5–10 μm → upper airway/first generations; 2–5 μm → lower respiratory tract; < 1 μm largely exhaled.", "srcItem": "Aerosol modalities"},
    {"id": "q-m203-s03-026", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Where do aerosol particles larger than 10 μm deposit?", "choices": ["Upper airway (nose, mouth)", "Alveoli", "Terminal bronchioles", "They are all exhaled"], "correct": 0, "explanation": "Particles > 10 μm deposit in the upper airway.", "srcItem": "Aerosol modalities"},
    {"id": "q-m203-s03-027", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What MMAD is recommended for pentamidine to maximize alveolar deposition?", "choices": ["1–2 μm", "5–10 μm", "10–15 μm", "Over 20 μm"], "correct": 0, "explanation": "1–2 μm for pentamidine.", "srcItem": "Aerosol modalities"},
    {"id": "q-m203-s03-028", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which deposition mechanism does the 10-second breath-hold take advantage of?", "choices": ["Gravitational settling", "Inertial impaction", "Brownian diffusion", "Hygroscopic growth"], "correct": 0, "explanation": "Sedimentation depends on particle size and time. Inertial impaction occurs in large, fast-flow airways; diffusion dominates < 1 μm.", "srcItem": "Aerosol modalities"},
    {"id": "q-m203-s03-029", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A spacer and slow inhalation are designed to reduce which deposition mechanism?", "choices": ["Inertial impaction in large airways", "Gravitational settling in alveoli", "Diffusion in terminal airways", "Hygroscopic particle growth"], "correct": 0, "explanation": "Inertial impaction depends on mass and velocity; it happens where flow is fastest.", "srcItem": "Aerosol modalities"},
    {"id": "q-m203-s03-030", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the mechanism of incentive spirometry?", "choices": ["A slow, held maximal breath that reopens alveoli", "Forced exhalation against a resistor", "Positive pressure delivered by a machine", "Vibration that loosens airway secretions"], "correct": 0, "explanation": "A slow inspiration to near TLC, held, raises transpulmonary pressure and restores FRC.", "srcItem": "Incentive spirometry"},
    {"id": "q-m203-s03-031", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the main indication for incentive spirometry?", "choices": ["Treating atelectasis in a cooperative patient", "Removing thick secretions in cystic fibrosis", "Reversing acute bronchospasm in asthma", "Ventilating an apneic patient"], "correct": 0, "explanation": "Heuer: IS is no longer recommended for routine post-op prophylaxis — early mobilization is primary. It remains appropriate for documented or suspected atelectasis.", "srcItem": "Incentive spirometry"},
    {"id": "q-m203-s03-032", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What minimum inspiratory capacity should a patient generate to use IS effectively?", "choices": ["At least 33% of predicted", "At least 80% of predicted", "At least 10 mL/kg", "At least 5 mL/kg"], "correct": 0, "explanation": "If the patient can't cooperate or generate IC > 33% of predicted, recommend IPPB or intermittent CPAP.", "srcItem": "Incentive spirometry"},
    {"id": "q-m203-s03-033", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A post-op patient cannot cooperate with incentive spirometry. What should the RT recommend?", "choices": ["IPPB or intermittent CPAP", "More frequent IS sessions", "PEP therapy", "An MDI with a spacer"], "correct": 0, "explanation": "Escalate per the Lung Expansion Therapy Protocol.", "srcItem": "Incentive spirometry"},
    {"id": "q-m203-s03-034", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How long should the patient hold the breath at the end of an IS inspiration?", "choices": ["5–10 seconds", "1 second", "30 seconds", "No hold is needed"], "correct": 0, "explanation": "Inhale slowly to full IC, hold 5–10 seconds, exhale, then rest.", "srcItem": "Incentive spirometry"},
    {"id": "q-m203-s03-035", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How often should incentive spirometry be performed?", "choices": ["6–10 maximal breaths per hour awake", "Once a day, 5 breaths", "Every 4 hours, 2 breaths", "Continuously for 20 minutes"], "correct": 0, "explanation": "6–10 SMIs per hour while awake (the deck teaches ~10 breaths hourly).", "srcItem": "Incentive spirometry"},
    {"id": "q-m203-s03-036", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "When should the RT teach incentive spirometry to a surgical patient?", "choices": ["Pre-op, to set the post-op target", "Only after the first post-op day", "Only if atelectasis shows on x-ray", "At discharge, for home use"], "correct": 0, "explanation": "Teach preoperatively; the deck's target is at least half the pre-op IC.", "srcItem": "Incentive spirometry"},
    {"id": "q-m203-s03-037", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the most common reason incentive spirometry fails?", "choices": ["Pain", "Excess secretions", "Low FiO₂", "Device malfunction"], "correct": 0, "explanation": "Pain is the primary hazard — medicate and splint the incision.", "srcItem": "Incentive spirometry"},
    {"id": "q-m203-s03-038", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient becomes dizzy with tingling fingers during IS. What should the RT do?", "choices": ["Lengthen the rest between breaths", "Increase the volume goal", "Stop IS permanently", "Add oxygen"], "correct": 0, "explanation": "Breaths are too frequent → hyperventilation. Allow adequate recovery time.", "srcItem": "Incentive spirometry"},
    {"id": "q-m203-s03-039", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient is blowing into the incentive spirometer instead of inhaling. What should the RT do?", "choices": ["Re-teach slow inhalation through it", "Replace the device with a new one", "Increase the target volume", "Switch the patient to PEP therapy"], "correct": 0, "explanation": "Blowing into the indicator is the classic error — the patient must inhale through it.", "srcItem": "Incentive spirometry"},
    {"id": "q-m203-s03-040", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "When can incentive spirometry be discontinued per Heuer?", "choices": ["> 60–70% predicted IC and atelectasis resolved", "After 24 hours, regardless of volume achieved", "When the patient reaches 500 mL once", "When breath sounds become diminished"], "correct": 0, "explanation": "Discontinue at > 60–70% predicted IC with improved breath sounds, oxygenation and respiratory rate.", "srcItem": "Incentive spirometry"},
    {"id": "q-m203-s03-041", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How does PEP therapy help clear secretions?", "choices": ["Back-pressure splints airways and gets air behind mucus", "It creates positive pressure during inspiration", "It vibrates the chest wall from the outside", "It chemically thins mucus in the airways"], "correct": 0, "explanation": "PEP prevents premature airway closure and uses collateral channels to push secretions proximally.", "srcItem": "PEP"},
    {"id": "q-m203-s03-042", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the therapeutic PEP working range?", "choices": ["10–20 cm H₂O", "2–5 cm H₂O", "30–40 cm H₂O", "50–60 cm H₂O"], "correct": 0, "explanation": "Devices generate 6–25 cm H₂O; start at the lowest setting and titrate to 10–20 cm H₂O.", "srcItem": "PEP"},
    {"id": "q-m203-s03-043", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How should PEP exhalation be performed?", "choices": ["Active, not forced, I:E 1:3 to 1:4", "As forcefully as possible, I:E 1:1", "Passively, with no effort at all", "Quickly, with an I:E of 2:1"], "correct": 0, "explanation": "Sets of 10–20 breaths with active, not forced, exhalation; then huff cough. Repeat 4–8 cycles, ≤ 20 minutes.", "srcItem": "PEP"},
    {"id": "q-m203-s03-044", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "After each set of 10–20 PEP breaths, the patient should:", "choices": ["Cough or perform huff coughs (FET)", "Rest for 30 minutes", "Use the incentive spirometer", "Lie flat"], "correct": 0, "explanation": "The forced expiratory technique: 2–3 huffs with the glottis open, then rest.", "srcItem": "PEP"},
    {"id": "q-m203-s03-045", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which condition is a contraindication to PEP therapy?", "choices": ["Untreated pneumothorax", "Cystic fibrosis", "Bronchiectasis", "COPD with mucus plugging"], "correct": 0, "explanation": "Also: hemodynamic instability, bullous emphysema, ↑ ICP, sinusitis, epistaxis, middle-ear problems.", "srcItem": "PEP"},
    {"id": "q-m203-s03-046", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How does PEP differ from PEEP?", "choices": ["PEP: exhaled resistance, spontaneous patient; PEEP: vent baseline", "PEP and PEEP are two names for the same therapy", "PEP acts on inspiration; PEEP acts only on exhalation", "PEP is used only on ventilated, intubated patients"], "correct": 0, "explanation": "PEP = handheld, exhalation only, returns to zero, for airway clearance. PEEP = machine baseline, never returns to zero, for oxygenation.", "srcItem": "PEP"},
    {"id": "q-m203-s03-047", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which vibratory PEP device is gravity-dependent and must be held at the correct angle?", "choices": ["Flutter valve", "Acapella device", "TheraPEP device", "EZPap device"], "correct": 0, "explanation": "The Flutter's steel ball is gravity-dependent. The Acapella works in any position and accepts a nebulizer.", "srcItem": "PEP"},
    {"id": "q-m203-s03-048", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "At what frequency do vibratory PEP devices oscillate?", "choices": ["10–30 Hz", "1–2 Hz", "100–200 Hz", "3–15 Hz"], "correct": 0, "explanation": "Vibratory PEP (Flutter, Acapella, Aerobika) oscillates at 10–30 Hz.", "srcItem": "PEP"},
    {"id": "q-m203-s03-049", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A PEP device generates no pressure. What is the most likely cause?", "choices": ["A leak at a connection or the mouth seal", "An obstructed outlet port", "The setting is too high", "The patient is exhaling too slowly"], "correct": 0, "explanation": "No pressure = leak. Unexpectedly HIGH pressure = obstructed outlet port (hand or bedding).", "srcItem": "PEP"},
    {"id": "q-m203-s03-050", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How does the RT confirm a vibratory PEP device is set correctly?", "choices": ["Vibrations felt over central airways", "The patient reports feeling nothing", "The pressure gauge reads zero", "The patient coughs right away"], "correct": 0, "explanation": "If you can't feel the vibrations, the settings are wrong.", "srcItem": "PEP"},
    {"id": "q-m203-s03-051", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How does cromolyn sodium work?", "choices": ["It stabilizes mast cells", "It relaxes smooth muscle", "It blocks muscarinic receptors", "It blocks leukotriene receptors"], "correct": 0, "explanation": "Cromolyn (Intal) is a mast cell stabilizer with no bronchodilator activity.", "srcItem": "Cromolyn"},
    {"id": "q-m203-s03-052", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient in an acute asthma attack asks to use cromolyn. What should the RT do?", "choices": ["Give a SABA — cromolyn is preventive only", "Give cromolyn by SVN immediately", "Double the usual cromolyn dose", "Give cromolyn through a spacer"], "correct": 0, "explanation": "Cromolyn cannot reverse bronchoconstriction that has already happened. In an attack, give albuterol.", "srcItem": "Cromolyn"},
    {"id": "q-m203-s03-053", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How long does cromolyn take to improve symptoms?", "choices": ["2–4 weeks", "15 minutes", "24 hours", "6 months"], "correct": 0, "explanation": "Tell the patient to keep taking it even though nothing seems to happen at first.", "srcItem": "Cromolyn"},
    {"id": "q-m203-s03-054", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the SVN dose of cromolyn sodium?", "choices": ["20 mg (2 mL ampule) QID", "2.5 mg every 4 hours", "1 mg once daily", "200 mg twice daily"], "correct": 0, "explanation": "SVN 20 mg/2 mL (1%) QID. MDI 1 mg/puff, 2–4 puffs QID.", "srcItem": "Cromolyn"},
    {"id": "q-m203-s03-055", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "For which patient is cromolyn a reasonable prophylactic choice per Heuer?", "choices": ["A child 2 years old or younger", "An adult in status asthmaticus", "A COPD patient with hypercapnia", "A patient needing rescue therapy"], "correct": 0, "explanation": "Heuer pairs prophylaxis in patients ≤ 2 years with montelukast or cromolyn. Safer, though less potent, than steroids.", "srcItem": "Cromolyn"},
    {"id": "q-m203-s03-056", "topic": "m203-s03", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What are the typical side effects of cromolyn?", "choices": ["Mild local cough and throat irritation", "Tachycardia and tremor", "Oral thrush and adrenal suppression", "Hypokalemia and hyperglycemia"], "correct": 0, "explanation": "Mild, local and poorly absorbed — why it is used in toddlers.", "srcItem": "Cromolyn"},
    {"id": "q-m203-s04-001", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What does a Levy-Jennings chart plot?", "choices": ["Control results over time vs the mean and ±2 SD", "Patient ABG results over a hospital stay", "Flow–volume loops from spirometry", "Analyzer temperature over each day"], "correct": 0, "explanation": "A record of standard (control) sample measurements used to statistically evaluate analyzer performance.", "srcItem": "Levy-Jennings"},
    {"id": "q-m203-s04-002", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What are the usual control limits on a Levy-Jennings chart?", "choices": ["±2 SD from the mean", "±1 SD from the mean", "±5% of the mean", "±10 mm Hg of the mean"], "correct": 0, "explanation": "Values inside ±2 SD = in control. A value outside ±2 SD indicates an analytical error.", "srcItem": "Levy-Jennings"},
    {"id": "q-m203-s04-003", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A single control value falls outside ±2 SD, and the next values return to normal. What type of error is this?", "choices": ["Random error", "Systematic (bias) error", "A shift", "A trend"], "correct": 0, "explanation": "Random error: an isolated point. Reanalyze after two-point calibration; if back in control, no further action.", "srcItem": "Levy-Jennings"},
    {"id": "q-m203-s04-004", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Control values drift progressively upward over successive runs. What is this called?", "choices": ["A trend (bias error)", "A random error", "A shift (bias error)", "Normal precision"], "correct": 0, "explanation": "A trend = gradual deterioration (aging electrode, degrading buffer). It is a bias error.", "srcItem": "Levy-Jennings"},
    {"id": "q-m203-s04-005", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Control values jump abruptly to a new level and stay there. What is this called?", "choices": ["A shift (bias error)", "A trend (bias error)", "A random error", "Proficiency failure"], "correct": 0, "explanation": "A shift = abrupt change (new reagent lot, replaced electrode, new gas cylinder). Also a bias error.", "srcItem": "Levy-Jennings"},
    {"id": "q-m203-s04-006", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "The Levy-Jennings chart shows a systematic (bias) error. What must happen?", "choices": ["Stop patient testing until it is fixed", "Continue testing and note the error", "Rerun the control once and continue", "Widen the control limits to ±3 SD"], "correct": 0, "explanation": "Bias is always serious. Troubleshoot, repair or replace, recalibrate, and confirm controls before resuming.", "srcItem": "Levy-Jennings"},
    {"id": "q-m203-s04-007", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How many levels of control media must be run for blood gas analyzer calibration verification?", "choices": ["3 levels, at least daily", "1 level, once a week", "2 levels, once a month", "5 levels, every hour"], "correct": 0, "explanation": "At least 3 levels (acidotic, normal, alkalotic) spanning the reportable range, at least daily and after maintenance.", "srcItem": "Levy-Jennings"},
    {"id": "q-m203-s04-008", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the gold standard for verifying PO₂ and PCO₂ on a blood gas analyzer?", "choices": ["Tonometry", "Two-point calibration only", "Proficiency testing", "A Levy-Jennings chart"], "correct": 0, "explanation": "Tonometry equilibrates a liquid medium to a reference gas of known partial pressures.", "srcItem": "Levy-Jennings"},
    {"id": "q-m203-s04-009", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Per the deck's Westgard framing, two or more consecutive controls outside the acceptable range indicate:", "choices": ["Out of control — recalibrate or replace", "A warning only — keep running", "Normal random scatter", "A need for proficiency testing"], "correct": 0, "explanation": "One control outside = warning; two or more consecutive outside = out of control.", "srcItem": "Levy-Jennings"},
    {"id": "q-m203-s04-010", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "In proficiency testing, who provides the samples?", "choices": ["An outside agency sends blind samples", "The lab's own control ampules", "The manufacturer's service tech", "The RT draws a sample from a healthy volunteer"], "correct": 0, "explanation": "The agency compares the lab's results to its own and to peer labs. Certification is needed for Medicare/Medicaid reimbursement.", "srcItem": "Levy-Jennings"},
    {"id": "q-m203-s04-011", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is a point-of-care analyzer?", "choices": ["A device that runs lab tests at the bedside", "A bench analyzer in the central lab", "A pulse oximeter with a finger probe", "A capnograph on the ventilator"], "correct": 0, "explanation": "POCT: collection, measurement and reporting at or near the site of care. Most use disposable, self-calibrating cartridges.", "srcItem": "Point-of-care analyzers"},
    {"id": "q-m203-s04-012", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which is an example of a point-of-care analyzer?", "choices": ["Abbott i-STAT", "Bench CO-oximeter", "Body plethysmograph", "Thorpe tube flowmeter"], "correct": 0, "explanation": "The i-STAT returns ABG results in about 90 seconds and can run electrolytes, Hb, glucose, lactate and BUN.", "srcItem": "Point-of-care analyzers"},
    {"id": "q-m203-s04-013", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How soon must an i-STAT sample be analyzed, and should it be iced?", "choices": ["Within 3 minutes; do NOT ice it", "Within 30 minutes; ice it", "Within 1 hour; ice it", "Within 10 minutes; do not ice it"], "correct": 0, "explanation": "i-STAT: analyze within 3 minutes, not on ice.", "srcItem": "Point-of-care analyzers"},
    {"id": "q-m203-s04-014", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the best way to validate POCT measurements?", "choices": ["Run the same sample on a bench analyzer too", "Run the same cartridge a second time", "Compare with the pulse oximeter reading", "Check the i-STAT power-on self-test"], "correct": 0, "explanation": "Inter-instrumental comparison is Heuer's T4 tip.", "srcItem": "Point-of-care analyzers"},
    {"id": "q-m203-s04-015", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A POCT device fails to calibrate twice with new cartridges. What should the RT do?", "choices": ["Take it out of service; use another or the lab", "Keep trying new cartridges until it passes", "Report the results with a comment", "Calibrate it manually with room air"], "correct": 0, "explanation": "Rerun once with a new cartridge; if it fails again, take it out of service.", "srcItem": "Point-of-care analyzers"},
    {"id": "q-m203-s04-016", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A POCT PO₂ is below 40 torr in a patient showing signs of severe hypoxemia. What should the RT do?", "choices": ["Increase the FiO₂ now and confirm later", "Wait for a central lab repeat before acting", "Ignore it as a cartridge error", "Repeat the test three times first"], "correct": 0, "explanation": "Never wait for a repeat when findings are life-threatening and match the patient's condition.", "srcItem": "Point-of-care analyzers"},
    {"id": "q-m203-s04-017", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is QC performed on a pulse oximeter?", "choices": ["Check it on a healthy person (pulse, 97–100%, signal loss)", "Calibrate it with 100% O₂ and then room air", "Run three levels of liquid control solution", "Compare it against a capnograph reading"], "correct": 0, "explanation": "Oximeters measure relative light intensity, so they get operational verification using a \"biological control.\"", "srcItem": "Pulse oximeter QC"},
    {"id": "q-m203-s04-018", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On a healthy subject, a pulse oximeter reads 93%. What should the RT do?", "choices": ["Remove the oximeter from service", "Accept it as normal", "Recalibrate it with room air", "Move the probe to the ear and accept any value"], "correct": 0, "explanation": "Failure criteria: wrong pulse rate, SpO₂ < 97% on a healthy subject, or failure to detect loss of signal.", "srcItem": "Pulse oximeter QC"},
    {"id": "q-m203-s04-019", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How accurate is a pulse oximeter with good perfusion?", "choices": ["±2–4%", "±0.5%", "±10%", "±15–20%"], "correct": 0, "explanation": "Relatively accurate (±2–4%) with good perfusion.", "srcItem": "Pulse oximeter QC"},
    {"id": "q-m203-s04-020", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How does carbon monoxide poisoning affect a standard pulse oximeter reading?", "choices": ["Falsely HIGH SpO₂", "Falsely LOW SpO₂", "No effect", "The oximeter shows zero"], "correct": 0, "explanation": "Two-wavelength oximeters read COHb as oxygenated Hb. Use a CO-oximeter.", "srcItem": "Pulse oximeter QC"},
    {"id": "q-m203-s04-021", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the MOST common source of pulse oximeter errors and false alarms?", "choices": ["Motion artifact", "Nail polish", "Ambient light", "Dark skin pigmentation"], "correct": 0, "explanation": "Motion artifact — relocate the sensor.", "srcItem": "Pulse oximeter QC"},
    {"id": "q-m203-s04-022", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient wearing dark nail polish has an SpO₂ reading. What effect does the polish have?", "choices": ["Falsely high SpO₂ by 3–5%", "Falsely low SpO₂ by 10%", "No effect", "The reading will be zero"], "correct": 0, "explanation": "Dark pigmentation and nail polish read falsely high. Remove polish or rotate the probe 90° in an emergency.", "srcItem": "Pulse oximeter QC"},
    {"id": "q-m203-s04-023", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient given methylene blue has a pulse oximeter reading. What effect does the dye have?", "choices": ["Falsely LOW SpO₂", "Falsely HIGH SpO₂", "No effect", "The pulse rate reads double"], "correct": 0, "explanation": "Vascular dyes cause falsely low readings — correlate with an arterial SaO₂.", "srcItem": "Pulse oximeter QC"},
    {"id": "q-m203-s04-024", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A probe fitted too tightly causes venous pulsation. What happens to the SpO₂?", "choices": ["Falsely low", "Falsely high", "No change", "It alternates high and low"], "correct": 0, "explanation": "Venous pooling/pulsation → falsely low SpO₂.", "srcItem": "Pulse oximeter QC"},
    {"id": "q-m203-s04-025", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Before believing an SpO₂ reading, what should the RT check?", "choices": ["Its pulse rate matches the actual pulse", "The FiO₂ is set at 21%", "The probe is on the index finger", "The patient is lying flat"], "correct": 0, "explanation": "Make sure the oximeter is actually seeing the patient's pulse.", "srcItem": "Pulse oximeter QC"},
    {"id": "q-m203-s04-026", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What are the two calibration points for an oxygen analyzer?", "choices": ["100% O₂ and 21% room air", "50% O₂ and 21% room air", "100% O₂ and 0%", "40% and 60% O₂"], "correct": 0, "explanation": "Expose to 100%, adjust to 100%, then confirm 21% (±2%) in room air.", "srcItem": "O₂ analyzer QC"},
    {"id": "q-m203-s04-027", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How accurate are polarographic and galvanic oxygen analyzers?", "choices": ["Within ±2%", "Within ±10%", "Within ±0.1%", "Within ±5 mm Hg"], "correct": 0, "explanation": "Both are generally accurate to within ±2%.", "srcItem": "O₂ analyzer QC"},
    {"id": "q-m203-s04-028", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An oxygen analyzer fails its two-point calibration. What does Heuer's T4 tip recommend?", "choices": ["Replace the probe", "Recalibrate at 50% only", "Use it anyway and note the error", "Replace the flowmeter"], "correct": 0, "explanation": "Failure to reach 100% or 21% suggests a damaged probe or defective analyzer. Also check for condensate on the membrane.", "srcItem": "O₂ analyzer QC"},
    {"id": "q-m203-s04-029", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An oxygen analyzer reads 0%. What are the likely causes?", "choices": ["Dead battery or bad/disconnected probe", "Too much oxygen flowing past it", "Condensate on the membrane only", "Contaminated room air"], "correct": 0, "explanation": "A 0% reading suggests a dead battery, disconnected probe or dead probe.", "srcItem": "O₂ analyzer QC"},
    {"id": "q-m203-s04-030", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which type of oxygen analyzer requires external power to maintain the electrode reaction?", "choices": ["Polarographic (Clark)", "Galvanic fuel cell", "Both types equally", "Neither type"], "correct": 0, "explanation": "Polarographic needs external power; galvanic cells don't (though both need power for alarms).", "srcItem": "O₂ analyzer QC"},
    {"id": "q-m203-s04-031", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What size syringe is used to calibrate a spirometer's volume?", "choices": ["3.0 L", "1.0 L", "5.0 L", "500 mL"], "correct": 0, "explanation": "A large-volume 3.0-L calibration syringe.", "srcItem": "Spirometry calibration"},
    {"id": "q-m203-s04-032", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the ATS volume accuracy standard for diagnostic spirometers?", "choices": ["±3% or ±50 mL (larger)", "±10% or ±100 mL (larger)", "±1% or ±10 mL (larger)", "±5% or ±200 mL (larger)"], "correct": 0, "explanation": "±3% or ±50 mL. For the 3.0-L syringe, ±3% = 90 mL governs.", "srcItem": "Spirometry calibration"},
    {"id": "q-m203-s04-033", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A spirometer is checked with a 3.0-L syringe. What range of readings is acceptable?", "choices": ["2.91–3.09 L", "2.85–3.15 L", "2.95–3.05 L", "2.70–3.30 L"], "correct": 0, "explanation": "3.0 L ± 3% (90 mL) = 2.91–3.09 L.", "srcItem": "Spirometry calibration"},
    {"id": "q-m203-s04-034", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How often is spirometer volume calibration checked?", "choices": ["Daily", "Weekly", "Quarterly", "Annually"], "correct": 0, "explanation": "Leaks and volume: daily. Flow linearity: weekly. Volume linearity and time: quarterly.", "srcItem": "Spirometry calibration"},
    {"id": "q-m203-s04-035", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "During a spirometer leak test, how much volume loss is allowed?", "choices": ["Less than 10 mL in 1 minute at 3 cm H₂O", "Less than 100 mL in 1 minute", "Less than 50 mL in 10 seconds", "No more than 3% of the volume"], "correct": 0, "explanation": "Pressurize to 3 cm H₂O for 1 minute; the leak must be < 10 mL.", "srcItem": "Spirometry calibration"},
    {"id": "q-m203-s04-036", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A 3.0-L syringe calibration reads 3.30 L. What is the most likely cause?", "choices": ["BTPS correction was left ON", "A leak in the tubing", "The syringe was not fully emptied", "The patient did not seal the mouthpiece"], "correct": 0, "explanation": "BTPS on makes the calibrating volume read ~10% high. For high readings, also recheck zeroing and temperature.", "srcItem": "Spirometry calibration"},
    {"id": "q-m203-s04-037", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A 3.0-L syringe calibration reads 2.80 L. What should the RT do FIRST?", "choices": ["Repeat the leak check", "Turn BTPS correction on", "Recalibrate the flow sensor", "Test patients and adjust results"], "correct": 0, "explanation": "Low volume → repeat the leak check first. Don't test patients until the cause is found and calibration is accurate.", "srcItem": "Spirometry calibration"},
    {"id": "q-m203-s04-038", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How many acceptable FVC maneuvers does the ATS require?", "choices": ["At least 3", "At least 1", "At least 5", "Exactly 8"], "correct": 0, "explanation": "Get at least three error-free maneuvers.", "srcItem": "Spirometry calibration"},
    {"id": "q-m203-s04-039", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the ATS repeatability criterion for FVC and FEV₁?", "choices": ["The two largest values must be within 150 mL", "All values must be within 50 mL", "The two largest values must be within 500 mL", "The best value must exceed 80% predicted"], "correct": 0, "explanation": "The two largest FVC and FEV₁ values must each be within 0.150 L.", "srcItem": "Spirometry calibration"},
    {"id": "q-m203-s04-040", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the minimum exhalation time for an acceptable FVC maneuver?", "choices": ["6 seconds", "1 second", "3 seconds", "15 seconds"], "correct": 0, "explanation": "At least 6 seconds (severe COPD may take up to 15).", "srcItem": "Spirometry calibration"},
    {"id": "q-m203-s04-041", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An FVC curve has an S-shaped, slow start with a back-extrapolated volume over 150 mL. What is the error, and the coaching cue?", "choices": ["Slow/false start — \"Don't hesitate\"", "Early termination — \"Blow out longer\"", "Cough — \"Take a deeper breath\"", "Variable effort — \"Relax\""], "correct": 0, "explanation": "Back-extrapolated volume ≥ 5% of FVC or 150 mL = unacceptable slow start.", "srcItem": "Spirometry calibration"},
    {"id": "q-m203-s04-042", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which artery is preferred for an ABG, and why?", "choices": ["Radial — superficial with collateral flow", "Brachial — larger and easier to feel", "Femoral — highest blood flow", "Dorsalis pedis — least painful site"], "correct": 0, "explanation": "Radial on the nondominant wrist. Brachial, femoral and dorsalis pedis carry greater risk.", "srcItem": "ABG sampling"},
    {"id": "q-m203-s04-043", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "During a modified Allen's test, how quickly should the palm flush after the ulnar artery is released?", "choices": ["Within 5–10 seconds", "Within 30–60 seconds", "Within 1 second", "After 2 minutes"], "correct": 0, "explanation": "A prolonged delay means inadequate ulnar flow — test the other wrist; if both fail, use the brachial artery.", "srcItem": "ABG sampling"},
    {"id": "q-m203-s04-044", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How long should pressure be held after an arterial puncture?", "choices": ["At least 5 minutes, more if anticoagulated", "About 30 seconds for all patients", "About 1 minute for all patients", "No pressure is needed after an ABG"], "correct": 0, "explanation": "Deck: at least 5 minutes; recheck the site after 20 minutes.", "srcItem": "ABG sampling"},
    {"id": "q-m203-s04-045", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What must be documented with every ABG sample?", "choices": ["FiO₂, device, and vent settings", "The patient's most recent meal", "The syringe brand and lot", "The RT's shift start time"], "correct": 0, "explanation": "Always document FiO₂, device, vent mode/settings and related assessments.", "srcItem": "ABG sampling"},
    {"id": "q-m203-s04-046", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Within what time must an ABG in a plastic syringe at room temperature be analyzed (Heuer)?", "choices": ["Less than 30 minutes", "Less than 2 hours", "Less than 5 minutes", "Less than 24 hours"], "correct": 0, "explanation": "Heuer: < 30 min. Shunt study < 5 min. High WBC/platelets: immediately. > 30 min: glass syringe on ice (0–4°C).", "srcItem": "ABG sampling"},
    {"id": "q-m203-s04-047", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An ABG sample will not be run for 45 minutes. How should it be stored?", "choices": ["In a glass syringe chilled to 0–4°C", "In a plastic syringe at room temperature", "In a plastic syringe in a warm water bath", "Uncapped on the counter"], "correct": 0, "explanation": "Chilling slows cellular metabolism and preserves the values.", "srcItem": "ABG sampling"},
    {"id": "q-m203-s04-048", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which are the three analytical stages of ABG error?", "choices": ["Preanalytical, analytical, postanalytical", "Collection, transport, storage", "Calibration, verification, proficiency", "Sampling, icing, reporting"], "correct": 0, "explanation": "Preanalytical (before analysis), analytical (during measurement), postanalytical (data handling and reporting).", "srcItem": "ABG sampling"},
    {"id": "q-m203-s04-049", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An air bubble in the sample is which type of error?", "choices": ["Preanalytical", "Analytical", "Postanalytical", "Interpretation"], "correct": 0, "explanation": "Heuer's three most common preanalytical errors: air bubbles, venous admixture, continued metabolism.", "srcItem": "ABG sampling"},
    {"id": "q-m203-s04-050", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A drifting analyzer electrode or contaminated buffer is which type of error?", "choices": ["Analytical", "Preanalytical", "Postanalytical", "Interpretation"], "correct": 0, "explanation": "Analytical errors happen while the analyzer runs the sample.", "srcItem": "ABG sampling"},
    {"id": "q-m203-s04-051", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Entering the wrong patient information on the ABG report is which type of error?", "choices": ["Postanalytical", "Preanalytical", "Analytical", "Random"], "correct": 0, "explanation": "Postanalytical: transcription errors, wrong patient info, failing to record FiO₂.", "srcItem": "ABG sampling"},
    {"id": "q-m203-s04-052", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How does an air bubble in an ABG sample affect the results?", "choices": ["↓ PCO₂, ↑ pH, variable PO₂", "↑ PCO₂, ↓ pH, ↓ PO₂", "↑ PCO₂, ↑ pH, ↑ PO₂", "No change in any value"], "correct": 0, "explanation": "CO₂ diffuses into the bubble; PO₂ is pulled toward room air (~150 torr) — falsely high if true PO₂ was lower, falsely low if higher.", "srcItem": "ABG sampling"},
    {"id": "q-m203-s04-053", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An ABG sample sat at room temperature for 2 hours without ice. How are the results affected?", "choices": ["↑ PCO₂, ↓ PO₂, ↓ pH", "↓ PCO₂, ↑ PO₂, ↑ pH", "No change", "↓ PCO₂ and ↓ PO₂ only"], "correct": 0, "explanation": "Continued metabolism: cells make CO₂ and consume O₂ → falsely acidotic. The opposite of an air bubble on PCO₂ and pH.", "srcItem": "ABG sampling"},
    {"id": "q-m203-s04-054", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How does venous admixture affect an ABG sample?", "choices": ["↑ PCO₂, ↓ pH, ↓ PO₂", "↓ PCO₂, ↑ pH, ↑ PO₂", "Only the pH changes", "No effect"], "correct": 0, "explanation": "Recognized by no pulsation as the syringe fills and darker blood.", "srcItem": "ABG sampling"},
    {"id": "q-m203-s04-055", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How does too much heparin in the syringe affect the ABG?", "choices": ["↓ PaCO₂, PaO₂ toward 150, ↓ pH", "↑ PaCO₂, ↑ pH, no PaO₂ change", "No effect on any measured value", "PaO₂ falls to zero, pH unchanged"], "correct": 0, "explanation": "Heparin dilutes the sample and is acidic, so pH drifts toward 7.0.", "srcItem": "ABG sampling"},
    {"id": "q-m203-s04-056", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is a hemoximeter (CO-oximeter)?", "choices": ["A multi-wavelength device that measures each Hb type", "A two-wavelength pulse oximeter on the finger", "An electrode that measures only the PO₂", "A heated sensor that estimates PO₂ through skin"], "correct": 0, "explanation": "Each Hb species absorbs different wavelengths, so each can be measured directly.", "srcItem": "Bench hemoximeter"},
    {"id": "q-m203-s04-057", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which values does a CO-oximeter measure directly?", "choices": ["HbO₂, HHb, COHb, MetHb, total Hb", "pH, PCO₂, and PO₂ only", "HCO₃⁻ and base excess only", "SpO₂ and pulse rate only"], "correct": 0, "explanation": "Plus sulfhemoglobin per Heuer. A blood gas analyzer measures only pH, PCO₂, PO₂ and calculates SaO₂.", "srcItem": "Bench hemoximeter"},
    {"id": "q-m203-s04-058", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A smoke inhalation victim needs an oxygenation assessment. Which test is required?", "choices": ["CO-oximetry", "Pulse oximetry", "Transcutaneous PO₂", "A standard ABG SaO₂"], "correct": 0, "explanation": "SpO₂ reads falsely high and PaO₂ may be normal in CO poisoning; the ABG SaO₂ is calculated.", "srcItem": "Bench hemoximeter"},
    {"id": "q-m203-s04-059", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "During inhaled nitric oxide therapy, CO-oximetry is used to monitor:", "choices": ["Methemoglobin", "Carboxyhemoglobin", "Total CO₂", "Lactate"], "correct": 0, "explanation": "iNO can cause methemoglobinemia.", "srcItem": "Bench hemoximeter"},
    {"id": "q-m203-s04-060", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A COHb level of 25% indicates:", "choices": ["CO poisoning", "A normal nonsmoker", "A light smoker", "A heavy smoker"], "correct": 0, "explanation": "COHb: 1–3% normal; 5–10% smokers; 10–15% heavy smokers; > 20% CO poisoning.", "srcItem": "Bench hemoximeter"},
    {"id": "q-m203-s04-061", "topic": "m203-s04", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An SpO₂ disagrees with the lab. What should the SpO₂ be compared against?", "choices": ["The hemoximeter's measured SaO₂", "The ABG analyzer's calculated SaO₂", "The transcutaneous PO₂", "The PaCO₂"], "correct": 0, "explanation": "The ABG SaO₂ is usually computed, so compare to a hemoximeter and use the SaO₂ − SpO₂ difference.", "srcItem": "Bench hemoximeter"},
    {"id": "q-m203-s05-001", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On BiPAP, IPAP mainly affects ______ and EPAP mainly affects ______.", "choices": ["Ventilation (CO₂); oxygenation", "Oxygenation; ventilation (CO₂)", "Heart rate; blood pressure", "Both affect only oxygenation"], "correct": 0, "explanation": "IPAP → VT/CO₂. EPAP is functionally PEEP → FRC, recruitment, SpO₂.", "srcItem": "BiPAP"},
    {"id": "q-m203-s05-002", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the minimum difference between IPAP and EPAP per the decks?", "choices": ["4 cm H₂O", "1 cm H₂O", "10 cm H₂O", "0 cm H₂O"], "correct": 0, "explanation": "ΔP (pressure support) = IPAP − EPAP, never less than 4 cm H₂O.", "srcItem": "BiPAP"},
    {"id": "q-m203-s05-003", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which BiPAP adjustment rule is most often tested?", "choices": ["Never raise EPAP without raising IPAP equally", "Never raise IPAP without raising EPAP equally", "Always lower IPAP and EPAP together", "Raise EPAP by itself to lower the CO₂"], "correct": 0, "explanation": "Raising EPAP alone shrinks ΔP and costs ventilation. Heuer: to avoid changing PaCO₂, keep ΔP constant.", "srcItem": "BiPAP"},
    {"id": "q-m203-s05-004", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient on BiPAP 10/5 needs better OXYGENATION only. Which change is correct?", "choices": ["12/7", "15/5", "10/3", "15/7"], "correct": 0, "explanation": "Raise both equally: ΔP stays 5, baseline rises.", "srcItem": "BiPAP"},
    {"id": "q-m203-s05-005", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient on BiPAP 10/5 needs better VENTILATION only. Which change is correct?", "choices": ["15/5", "12/7", "10/7", "8/5"], "correct": 0, "explanation": "Raise IPAP only: ΔP 5 → 10, baseline unchanged. (If oxygenation is stable, lowering EPAP also widens ΔP.)", "srcItem": "BiPAP"},
    {"id": "q-m203-s05-006", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient on BiPAP 10/5 needs better oxygenation AND ventilation. Which change is correct?", "choices": ["15/7", "12/7", "15/5", "10/8"], "correct": 0, "explanation": "Raise both, IPAP more: ΔP 5 → 8 and baseline rises.", "srcItem": "BiPAP"},
    {"id": "q-m203-s05-007", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A COPD patient on BiPAP has pH 7.28 and PaCO₂ 75 mm Hg. What should be adjusted?", "choices": ["Increase IPAP", "Increase EPAP only", "Increase FiO₂", "Decrease IPAP"], "correct": 0, "explanation": "A ventilation problem → raise IPAP (ΔP).", "srcItem": "BiPAP"},
    {"id": "q-m203-s05-008", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A CHF patient on BiPAP has SpO₂ 84% with a normal PaCO₂. What should be adjusted?", "choices": ["Increase EPAP and IPAP equally", "Increase IPAP only", "Decrease EPAP only", "Decrease the FiO₂"], "correct": 0, "explanation": "An oxygenation problem → raise EPAP, keeping ΔP constant.", "srcItem": "BiPAP"},
    {"id": "q-m203-s05-009", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why does Heuer keep IPAP below 20–25 cm H₂O?", "choices": ["It opens the esophagus and inflates the stomach", "It causes hypoventilation and hypercapnia", "It lowers the delivered FiO₂", "It triggers the apnea alarm"], "correct": 0, "explanation": "20–25 cm H₂O is the esophageal opening pressure — gastric insufflation risk.", "srcItem": "BiPAP"},
    {"id": "q-m203-s05-010", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which is a contraindication to BiPAP?", "choices": ["Active upper GI bleeding", "COPD exacerbation", "Acute cardiogenic pulmonary edema", "Obesity hypoventilation"], "correct": 0, "explanation": "Also: respiratory or cardiac arrest, can't protect airway or clear secretions, facial trauma, vomiting, obtundation.", "srcItem": "BiPAP"},
    {"id": "q-m203-s05-011", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which is a hazard of BiPAP?", "choices": ["Gastric insufflation and aspiration", "Tracheal stenosis", "Pneumothorax from high PEEP only", "Oral thrush"], "correct": 0, "explanation": "Hazards: aerophagia, gastric insufflation, dryness, aspiration, claustrophobia, ↓ cardiac output, eye irritation, pressure sores.", "srcItem": "BiPAP"},
    {"id": "q-m203-s05-012", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Per Heuer, which finding indicates BiPAP failure requiring intubation?", "choices": ["Worsening ABGs in the first 1–2 hours", "A pH of 7.36", "An SpO₂ of 94%", "A respiratory rate of 22/min"], "correct": 0, "explanation": "Heuer: worsening ABGs in 1–2 hr, no improvement after 4 hr, pH < 7.25 with PaCO₂ > 60, P/F < 200, or RR > 35. (Decks: still deteriorating at 30 minutes.)", "srcItem": "BiPAP"},
    {"id": "q-m203-s05-013", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which interface is preferred when starting NPPV for ACUTE respiratory failure?", "choices": ["Oronasal (full face) mask", "Nasal pillows", "Nasal mask", "Mouthpiece only"], "correct": 0, "explanation": "Lower leak. Avoid it if vomiting/aspiration risk is high. For chronic hypercapnia, nasal devices (less deadspace).", "srcItem": "BiPAP"},
    {"id": "q-m203-s05-014", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient on a nasal BiPAP mask is leaking through the mouth. What is the fix?", "choices": ["Add a chin strap", "Tighten the straps", "Switch to nasal pillows", "Increase EPAP"], "correct": 0, "explanation": "Mouth leak → chin strap (Heuer Table 6-24).", "srcItem": "BiPAP"},
    {"id": "q-m203-s05-015", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which interface is used for CPAP but is not recommended for BiPAP?", "choices": ["Nasal pillows", "Oronasal mask", "Full face mask", "Nasal mask"], "correct": 0, "explanation": "Pillows are smallest and most comfortable but cause congestion, dry mouth and nosebleeds.", "srcItem": "BiPAP"},
    {"id": "q-m203-s05-016", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What initial CPAP does Heuer recommend for acute cardiogenic pulmonary edema?", "choices": ["10 cm H₂O with 100% O₂", "2 cm H₂O on room air", "20 cm H₂O with 40% O₂", "5 cm H₂O on 2 L/min"], "correct": 0, "explanation": "Heuer: start at 10 and 100%, titrate to SpO₂ > 90%. Decks: CPAP 8–12 with 100%.", "srcItem": "BiPAP"},
    {"id": "q-m203-s05-017", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "In volume control, how is the tidal volume achieved?", "choices": ["A set VT; pressure varies with the lungs", "A set pressure; the VT varies", "The patient sets each VT", "The backup rate sets the VT"], "correct": 0, "explanation": "Only one of volume or pressure can be controlled; the other varies.", "srcItem": "How VT is achieved"},
    {"id": "q-m203-s05-018", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "In PSV, what determines the tidal volume?", "choices": ["Patient effort, compliance, resistance", "A preset volume on the ventilator", "The set mandatory rate", "The FiO₂ setting"], "correct": 0, "explanation": "The same PS 10 might give 700 mL in good lungs and 300 mL in ARDS.", "srcItem": "How VT is achieved"},
    {"id": "q-m203-s05-019", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "When should a patient be switched from VC to PC per Heuer?", "choices": ["When Pplat exceeds 30 cm H₂O", "When VT falls below 500 mL", "When the rate exceeds 12", "When FiO₂ exceeds 40%"], "correct": 0, "explanation": "Switch VC → PC when Pplat > 30, using a pressure limit ≤ 30.", "srcItem": "How VT is achieved"},
    {"id": "q-m203-s05-020", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On A/C, the rate is set at 12 and the patient triggers 24 breaths/min. How many full breaths are delivered?", "choices": ["24", "12", "36", "0"], "correct": 0, "explanation": "Every breath, assisted or controlled, gets the full preset breath.", "srcItem": "How VT is achieved"},
    {"id": "q-m203-s05-021", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On SIMV, how is the VT of a spontaneous breath determined?", "choices": ["The patient's effort, plus any PS", "The set mandatory VT", "The backup rate", "A fixed 500 mL"], "correct": 0, "explanation": "Mandatory breaths get the set VT; spontaneous breaths are whatever the patient generates.", "srcItem": "How VT is achieved"},
    {"id": "q-m203-s05-022", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On SIMV at a rate of 10, how often is a mandatory breath delivered?", "choices": ["Every 6 seconds", "Every 10 seconds", "Every 1 second", "Every 60 seconds"], "correct": 0, "explanation": "60 ÷ 10 = 6 seconds per mandatory breath.", "srcItem": "How VT is achieved"},
    {"id": "q-m203-s05-023", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient on A/C is hyperventilating because of a high trigger rate. What does Heuer recommend?", "choices": ["Switch to SIMV", "Increase the set rate", "Increase the VT", "Add PEEP"], "correct": 0, "explanation": "SIMV is indicated when full support is needed but the patient's rate causes hyperventilation on A/C.", "srcItem": "How VT is achieved"},
    {"id": "q-m203-s05-024", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How does PSV end inspiration?", "choices": ["When flow falls to ~25% of peak", "When a set volume is delivered", "When a set time has elapsed", "When pressure hits the alarm limit"], "correct": 0, "explanation": "PSV = patient-triggered, pressure-limited, flow-cycled.", "srcItem": "How VT is achieved"},
    {"id": "q-m203-s05-025", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is PRVC's main advantage?", "choices": ["A guaranteed VT at the lowest possible pressure", "A fixed pressure every breath", "No need for alarms", "It works on apneic patients without a rate"], "correct": 0, "explanation": "PRVC adjusts pressure breath to breath. Disadvantage: when patient demand rises, pressure may drop just when support is needed.", "srcItem": "How VT is achieved"},
    {"id": "q-m203-s05-026", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which statement about CPAP is correct?", "choices": ["It oxygenates but does not ventilate", "It delivers set mandatory breaths", "It is best for apneic patients", "It lowers PaCO₂ directly"], "correct": 0, "explanation": "CPAP is wrong for the apneic, oversedated or severely fatigued patient.", "srcItem": "How VT is achieved"},
    {"id": "q-m203-s05-027", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which patient benefits most from APRV?", "choices": ["ALI with Pplat > 30 or refractory hypoxemia", "An apneic post-operative patient", "A COPD patient with severe air trapping", "A patient ready for extubation today"], "correct": 0, "explanation": "APRV needs a patient who can breathe spontaneously; auto-PEEP is usually present and desired.", "srcItem": "How VT is achieved"},
    {"id": "q-m203-s05-028", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is Heuer's initial VT for full ventilatory support?", "choices": ["6–8 mL/kg PBW, Pplat ≤ 30–35", "10–15 mL/kg actual body weight", "4 mL/kg PBW for every patient", "12 mL/kg IBW with no Pplat limit"], "correct": 0, "explanation": "4–6 mL/kg in ARDS.", "srcItem": "How VT is achieved"},
    {"id": "q-m203-s05-029", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the first step when any ventilator alarm sounds?", "choices": ["Look at the patient", "Silence the alarm", "Reset the alarm limits", "Call the physician"], "correct": 0, "explanation": "Alarm → patient → ventilator → cause → fix. Never silence without finding the cause.", "srcItem": "Alarms"},
    {"id": "q-m203-s05-030", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Where is the high pressure alarm set per the decks?", "choices": ["10–15 cm H₂O above observed PIP", "At the set PEEP level", "50 cm H₂O above the PIP", "Exactly equal to the PIP"], "correct": 0, "explanation": "Heuer also allows 50 cm H₂O. It must not be raised without justification.", "srcItem": "Alarms"},
    {"id": "q-m203-s05-031", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "The low exhaled VT and low pressure alarms sound together. What is the problem?", "choices": ["A leak", "An obstruction", "Bronchospasm", "Auto-PEEP"], "correct": 0, "explanation": "Low volume + LOW pressure = leak. Low volume + HIGH pressure = obstruction.", "srcItem": "Alarms"},
    {"id": "q-m203-s05-032", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "The low exhaled VT and high pressure alarms sound together. What is the problem?", "choices": ["An obstruction", "A leak", "A disconnection", "Low compliance only"], "correct": 0, "explanation": "Find it: drain condensate, replace the HME, suction. An expiratory obstruction is the more dangerous kind.", "srcItem": "Alarms"},
    {"id": "q-m203-s05-033", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the apnea alarm delay per Heuer?", "choices": ["20 seconds", "5 seconds", "60 seconds", "2 minutes"], "correct": 0, "explanation": "Heuer 20 seconds; decks 15–20 seconds.", "srcItem": "Alarms"},
    {"id": "q-m203-s05-034", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "The high FiO₂ alarm suddenly sounds. Which is a likely cause?", "choices": ["The 100% O₂/suction button was pressed", "A leak in the patient circuit", "A low internal battery", "Water pooled in the tubing"], "correct": 0, "explanation": "Also gas source failure or analyzer needing calibration.", "srcItem": "Alarms"},
    {"id": "q-m203-s05-035", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "PIP rose from 30 to 45 cm H₂O; Pplat is unchanged at 25. What is the likely cause?", "choices": ["Mucus plug or bronchospasm", "ARDS", "Tension pneumothorax", "Pulmonary edema"], "correct": 0, "explanation": "High PIP with normal Pplat = resistance. \"When only PIP moves, think airways.\"", "srcItem": "Alarms"},
    {"id": "q-m203-s05-036", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "PIP and Pplat both rise suddenly by 15 cm H₂O and breath sounds disappear on one side. What should the RT suspect?", "choices": ["Tension pneumothorax or mainstem ETT", "Acute bronchospasm from asthma", "A leak in the ventilator circuit", "A mucus plug partly blocking the ETT"], "correct": 0, "explanation": "Compliance problem. Sudden = search for the problem; gradual (pneumonia, ARDS) = treat the disease.", "srcItem": "Alarms"},
    {"id": "q-m203-s05-037", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which circuit is used on most critical care ventilators?", "choices": ["Dual-limb (wye) circuit", "Single-limb with leak port", "Single-limb with an expiratory valve", "A T-piece"], "correct": 0, "explanation": "The expiratory limb returns gas to the ventilator, allowing accurate exhaled-volume measurement.", "srcItem": "Circuits"},
    {"id": "q-m203-s05-038", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which circuit is typical for home-care and transport ventilators?", "choices": ["Single-limb with an expiratory valve", "Dual-limb wye", "Single-limb with a leak port", "Heated-wire dual-limb only"], "correct": 0, "explanation": "A pneumatic line closes the valve on inspiration; it can also provide PEEP.", "srcItem": "Circuits"},
    {"id": "q-m203-s05-039", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which circuit is used for noninvasive (NPPV) ventilators?", "choices": ["Single-limb with a leak (exhaust) port", "Dual-limb wye", "Single-limb with a mushroom valve", "Closed circuit with no exhaust"], "correct": 0, "explanation": "Continuous flow flushes exhaled gas out the port — why EPAP must never fall near zero.", "srcItem": "Circuits"},
    {"id": "q-m203-s05-040", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How does high circuit compliance affect the delivered VT?", "choices": ["It lowers the VT reaching the patient", "It raises the VT reaching the patient", "It has no effect on the VT", "It raises the set PEEP"], "correct": 0, "explanation": "At PIP 40, a 5 mL/cm H₂O circuit holds 200 mL; a 3 mL/cm H₂O circuit holds 120 mL.", "srcItem": "Circuits"},
    {"id": "q-m203-s05-041", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How much water vapor must gas reaching the airway of an intubated patient carry?", "choices": ["At least 30 mg/L", "At least 5 mg/L", "At least 100 mg/L", "Any amount"], "correct": 0, "explanation": "Heuer: ≥ 30 mg/L via heated humidifier or HME.", "srcItem": "Circuits"},
    {"id": "q-m203-s05-042", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What temperature range does Heuer give for a heated humidifier?", "choices": ["34–41°C at 100% RH", "20–25°C", "42–45°C", "30–31°C at 70% RH"], "correct": 0, "explanation": "Decks target 37°C. 30–31°C at 70–90% RH describes an HME.", "srcItem": "Circuits"},
    {"id": "q-m203-s05-043", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which patient is the WORST candidate for an HME?", "choices": ["A patient with thick, bloody secretions", "A short post-op ventilation case", "A stable patient going to CT", "A patient with thin, scant secretions"], "correct": 0, "explanation": "Also avoid with NPPV, ARDS on low VT, hypercapnic failure, high VE, hypothermia, large leaks.", "srcItem": "Circuits"},
    {"id": "q-m203-s05-044", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Where is an HME placed?", "choices": ["Between the wye and the artificial airway", "On the inspiratory limb at the ventilator", "On the exhalation valve", "Before the humidifier chamber"], "correct": 0, "explanation": "It always adds deadspace and must allow bidirectional flow.", "srcItem": "Circuits"},
    {"id": "q-m203-s05-045", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the most common threat to ventilator circuit patency?", "choices": ["Condensation", "Kinked oxygen tubing", "A loose temperature probe", "Low battery"], "correct": 0, "explanation": "Fix with heated-wire circuits, inline water traps at low points, or an HME.", "srcItem": "Circuits"},
    {"id": "q-m203-s05-046", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What does hyperventilation cause?", "choices": ["↓ PaCO₂, ↑ pH (respiratory alkalosis)", "↑ PaCO₂, ↓ pH (respiratory acidosis)", "↓ HCO₃⁻, ↓ pH (metabolic acidosis)", "↑ PaCO₂, ↑ pH (mixed disorder)"], "correct": 0, "explanation": "Classic ABG: pH 7.52, PaCO₂ 30, HCO₃⁻ 24.", "srcItem": "Hyperventilation"},
    {"id": "q-m203-s05-047", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How does hyperventilation affect cerebral blood flow and ICP?", "choices": ["Vasoconstriction → ↓ flow → ↓ ICP", "Vasodilation → ↑ flow → ↑ ICP", "No effect on the brain at all", "↑ blood flow with ↓ ICP"], "correct": 0, "explanation": "CO₂ is a potent cerebral vasodilator; lowering it constricts cerebral arterioles.", "srcItem": "Hyperventilation"},
    {"id": "q-m203-s05-048", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why does Heuer say to avoid routine hyperventilation in head injury?", "choices": ["It lowers ICP but risks ischemia", "It raises ICP dangerously", "It causes respiratory acidosis", "It raises cerebral blood flow"], "correct": 0, "explanation": "Reserve it for pre-suctioning spikes, confirmed herniation, or salvage therapy.", "srcItem": "Hyperventilation"},
    {"id": "q-m203-s05-049", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What PaCO₂ does Heuer target for a TBI patient?", "choices": ["35–40 torr", "25–30 torr", "45–50 torr", "20–25 torr"], "correct": 0, "explanation": "Also PIP ≤ 30, SpO₂ > 95%, avoid high PEEP.", "srcItem": "Hyperventilation"},
    {"id": "q-m203-s05-050", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Prolonged respiratory alkalosis (> 24 hours) shifts the oxyhemoglobin curve which way?", "choices": ["Left — hemoglobin holds onto O₂", "Right — hemoglobin releases O₂", "No shift", "Up"], "correct": 0, "explanation": "\"Left = Love.\" Tissues, especially the brain, don't get O₂ efficiently.", "srcItem": "Hyperventilation"},
    {"id": "q-m203-s05-051", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient on VC SIMV (rate 14, VT 6–7 mL/kg) has a low PaCO₂ and PaO₂ 115 on 40%. What should be changed?", "choices": ["Decrease the set rate", "Decrease the VT", "Increase PEEP", "Increase the FiO₂"], "correct": 0, "explanation": "Heuer's NBRC item: VT is already appropriate — the problem is ventilation.", "srcItem": "Hyperventilation"},
    {"id": "q-m203-s05-052", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A weaning patient is hyperventilating because of anxiety and hypoxemia. What should the RT do?", "choices": ["Find and fix the cause before reducing support", "Cut ventilator support to normalize the PaCO₂", "Add deadspace immediately", "Extubate"], "correct": 0, "explanation": "Cutting support worsens hyperventilation, fatigues the muscles and causes ventilatory failure.", "srcItem": "Hyperventilation"},
    {"id": "q-m203-s05-053", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the BEST predictor of weaning success?", "choices": ["Improvement of the underlying disease", "A clear chest x-ray on the day of weaning", "A PaO₂ above 100 mm Hg on any FiO₂", "A normal hemoglobin and hematocrit"], "correct": 0, "explanation": "\"We don't wean the ventilator — we wean the patient.\" No single value determines readiness.", "srcItem": "Weaning"},
    {"id": "q-m203-s05-054", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which oxygenation criteria must be met to begin a weaning assessment?", "choices": ["P/F ≥ 150–200, PEEP ≤ 5–8, FiO₂ ≤ 0.4–0.5", "P/F ≥ 400, PEEP 0, FiO₂ 0.21", "P/F ≥ 100, PEEP ≤ 15, FiO₂ ≤ 0.8", "SpO₂ ≥ 99% on any FiO₂"], "correct": 0, "explanation": "Plus reversal of the cause, pH ≥ 7.25, hemodynamic stability, and inspiratory effort.", "srcItem": "Weaning"},
    {"id": "q-m203-s05-055", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is the rapid shallow breathing index (RSBI) calculated?", "choices": ["Rate ÷ VT in liters", "VT in mL ÷ rate", "Rate × VT", "VE ÷ rate"], "correct": 0, "explanation": "RSBI = f ÷ VT(L). Measure off the ventilator for about 3 minutes.", "srcItem": "Weaning"},
    {"id": "q-m203-s05-056", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient breathes spontaneously at 38/min with a VT of 300 mL. What is the RSBI, and what does it predict?", "choices": ["127 — predicts weaning failure", "11 — predicts success", "127 — predicts success", "87 — predicts success"], "correct": 0, "explanation": "38 ÷ 0.3 = 127, above 105.", "srcItem": "Weaning"},
    {"id": "q-m203-s05-057", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient breathes at 20/min with a VT of 500 mL. What is the RSBI?", "choices": ["40 — favorable for weaning", "100 — borderline", "10 — favorable", "400 — predicts failure"], "correct": 0, "explanation": "20 ÷ 0.5 = 40. < 105 is favorable (< 50 normal).", "srcItem": "Weaning"},
    {"id": "q-m203-s05-058", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Above what RSBI value does weaning failure become likely?", "choices": ["105", "50", "20", "200"], "correct": 0, "explanation": "RSBI > 105 predicts failure. RR and RSBI are the best indicators of tolerance of spontaneous breathing.", "srcItem": "Weaning"},
    {"id": "q-m203-s05-059", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A MIP/NIF of −15 cm H₂O indicates:", "choices": ["Too weak to sustain breathing", "Excellent inspiratory strength", "Normal for a healthy adult", "Ready for extubation now"], "correct": 0, "explanation": "Critical: weaker than −20 to −25 cm H₂O. Normal −80 to −100. More negative = stronger.", "srcItem": "Weaning"},
    {"id": "q-m203-s05-060", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How long is a NIF/MIP maneuver held against the one-way valve?", "choices": ["15–25 seconds", "2–3 seconds", "60 seconds", "5 minutes"], "correct": 0, "explanation": "The patient \"bucks down\" toward RV; maximal effort is ensured and consciousness is not required.", "srcItem": "Weaning"},
    {"id": "q-m203-s05-061", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What spontaneous VT is critically low for weaning (Heuer)?", "choices": ["< 4–5 mL/kg PBW (< 300 mL)", "< 8 mL/kg PBW", "< 10 mL/kg PBW", "< 600 mL total"], "correct": 0, "explanation": "Normal 5–7 mL/kg PBW.", "srcItem": "Weaning"},
    {"id": "q-m203-s05-062", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What vital capacity is critically low for weaning (Heuer)?", "choices": ["Less than 10–15 mL/kg PBW", "Less than 50 mL/kg", "Less than 30 mL/kg", "Less than 70 mL/kg"], "correct": 0, "explanation": "Normal ~70 mL/kg (Heuer) or 50 mL/kg (decks).", "srcItem": "Weaning"},
    {"id": "q-m203-s05-063", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What minute ventilation is associated with poor weaning outcomes?", "choices": ["Greater than 10 L/min", "Between 5 and 8 L/min", "Less than 8 L/min", "Exactly 6 L/min"], "correct": 0, "explanation": "Critical < 4 or > 10 L/min.", "srcItem": "Weaning"},
    {"id": "q-m203-s05-064", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How long should a spontaneous breathing trial last once the screening period is passed?", "choices": ["30–120 minutes", "About 5 minutes", "About 4–6 hours", "About 24 hours"], "correct": 0, "explanation": "Most failures occur within the first 20–30 minutes.", "srcItem": "Weaning"},
    {"id": "q-m203-s05-065", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which SBT methods are acceptable?", "choices": ["T-tube, CPAP, PS 5–8, or CPAP + PS", "SIMV at a rate of 10 only", "A/C at a reduced rate", "Control mode with sedation"], "correct": 0, "explanation": "No method is better than another. SIMV is not recommended as a stand-alone weaning mode.", "srcItem": "Weaning"},
    {"id": "q-m203-s05-066", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "During an SBT, which finding indicates failure?", "choices": ["RR rises > 50% to 38/min", "pH of 7.36", "HR change of 8%", "PaCO₂ rise of 4 torr"], "correct": 0, "explanation": "Pass: SpO₂ ≥ 85–90%, pH ≥ 7.30, PaCO₂ rise ≤ 10, HR < 120–140 (< 20% change), RR ≤ 30–35 (< 50% change).", "srcItem": "Weaning"},
    {"id": "q-m203-s05-067", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient fails an SBT. What happens next?", "choices": ["Full support, fix the cause, retry in 24 hr", "Extubate anyway and watch very closely", "Repeat the same SBT again in 1 hour", "Switch to gradual SIMV weaning instead"], "correct": 0, "explanation": "Repeat the SBT every 24 hours.", "srcItem": "Weaning"},
    {"id": "q-m203-s05-068", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What does a POSITIVE qualitative cuff-leak test indicate?", "choices": ["A leak around the cuff — airway likely patent", "No leak — high risk of post-extubation stridor", "The cuff balloon is damaged and must be replaced", "The patient is ready for a tracheostomy"], "correct": 0, "explanation": "Heuer: deflate the cuff, occlude the tube; leakage during breathing = positive.", "srcItem": "Weaning"},
    {"id": "q-m203-s05-069", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What MEP or peak cough flow indicates adequate secretion clearance before extubation?", "choices": ["MEP > 60 cm H₂O or peak cough flow > 60 L/min", "MEP > 20 or cough flow > 10 L/min", "MEP > 100 or cough flow > 300 L/min", "MEP > 5 cm H₂O"], "correct": 0, "explanation": "Heuer's extubation thresholds for an alert patient.", "srcItem": "Weaning"},
    {"id": "q-m203-s05-070", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Stridor develops right after extubation. What should the RT recommend?", "choices": ["Cool humidified O₂ and racemic epinephrine", "Immediate reintubation in every case", "A bronchodilator by MDI only", "Lower the FiO₂ to reduce swelling"], "correct": 0, "explanation": "Keep racemic epinephrine available at extubation.", "srcItem": "Weaning"},
    {"id": "q-m203-s05-071", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient has a high PaCO₂ on the ventilator. Which setting should be changed?", "choices": ["Rate or VT (ventilation)", "FiO₂", "PEEP", "Trigger sensitivity"], "correct": 0, "explanation": "CO₂ problem → ventilation; O₂ problem → FiO₂/PEEP. FiO₂ does not lower PaCO₂.", "srcItem": "Vent changes from ABG"},
    {"id": "q-m203-s05-072", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "When changing ventilation, which setting is usually adjusted FIRST?", "choices": ["The rate", "The VT", "The PEEP", "The FiO₂"], "correct": 0, "explanation": "Rate first (8–24/min); VT second (4–8 mL/kg, Pplat ≤ 30).", "srcItem": "Vent changes from ABG"},
    {"id": "q-m203-s05-073", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient on rate 14 has a PaCO₂ of 60 mm Hg. The target is 40. What new rate is needed?", "choices": ["21/min", "18/min", "24/min", "16/min"], "correct": 0, "explanation": "New f = (14 × 60) ÷ 40 = 21.", "srcItem": "Vent changes from ABG"},
    {"id": "q-m203-s05-074", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient on rate 12 has a PaCO₂ of 50 mm Hg. The target is 40. What new rate is needed?", "choices": ["15/min", "10/min", "18/min", "20/min"], "correct": 0, "explanation": "(12 × 50) ÷ 40 = 15.", "srcItem": "Vent changes from ABG"},
    {"id": "q-m203-s05-075", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient has VE 6.0 L/min and PaCO₂ 55 mm Hg. The target PaCO₂ is 40. What minute ventilation is needed?", "choices": ["8.25 L/min", "4.4 L/min", "7.0 L/min", "10.5 L/min"], "correct": 0, "explanation": "(6.0 × 55) ÷ 40 = 8.25 L/min.", "srcItem": "Vent changes from ABG"},
    {"id": "q-m203-s05-076", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "VT is 450 mL with PaCO₂ 58 mm Hg; the target is 45. The rate is already near maximum. What VT is needed?", "choices": ["About 580 mL", "About 350 mL", "About 520 mL", "About 650 mL"], "correct": 0, "explanation": "(450 × 58) ÷ 45 = 580 mL — then check Pplat ≤ 30.", "srcItem": "Vent changes from ABG"},
    {"id": "q-m203-s05-077", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "PaO₂ is 70 torr on FiO₂ 0.40. How should oxygenation be improved per the 60-60 rule?", "choices": ["Raise FiO₂ (V/Q problem)", "Raise PEEP (shunt)", "Raise the rate", "Lower the VT"], "correct": 0, "explanation": "PaO₂ > 60 on FiO₂ < 0.6 = V/Q → FiO₂. PaO₂ < 60 on FiO₂ > 0.6 = shunt → PEEP.", "srcItem": "Vent changes from ABG"},
    {"id": "q-m203-s05-078", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "PaO₂ is 52 torr on FiO₂ 0.80. What should be increased?", "choices": ["PEEP", "FiO₂ to 1.0 only", "Rate", "VT"], "correct": 0, "explanation": "Shunt → add or increase PEEP/CPAP.", "srcItem": "Vent changes from ABG"},
    {"id": "q-m203-s05-079", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "When weaning oxygen support, what should be reduced FIRST?", "choices": ["FiO₂ to ≤ 0.50, then PEEP", "PEEP first, then FiO₂", "Both at the same time", "The rate first"], "correct": 0, "explanation": "Drop FiO₂ to ≤ 0.50 first, then lower PEEP.", "srcItem": "Vent changes from ABG"},
    {"id": "q-m203-s05-080", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A ventilated patient has a primary metabolic acidosis from DKA. How should the ventilator be managed?", "choices": ["Treat the cause; don't compensate with the vent", "Raise the rate to normalize the pH", "Lower the rate to raise the PaCO₂", "Add PEEP to improve the acidosis"], "correct": 0, "explanation": "Do not adjust the ventilator for metabolic problems.", "srcItem": "Vent changes from ABG"},
    {"id": "q-m203-s05-081", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is STATIC compliance calculated?", "choices": ["VT ÷ (Pplat − PEEP)", "VT ÷ (PIP − PEEP)", "(PIP − Pplat) ÷ flow", "VT ÷ PIP"], "correct": 0, "explanation": "Static uses plateau (no flow, no resistance). Dynamic uses PIP.", "srcItem": "Compliance"},
    {"id": "q-m203-s05-082", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is DYNAMIC compliance calculated?", "choices": ["VT ÷ (PIP − PEEP)", "VT ÷ (Pplat − PEEP)", "(PIP − Pplat) ÷ flow", "PIP ÷ VT"], "correct": 0, "explanation": "Cdyn includes resistance, so it is always less than Cstat in VC.", "srcItem": "Compliance"},
    {"id": "q-m203-s05-083", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "VT 700 mL, PIP 42, Pplat 35, PEEP 8. What is the static compliance?", "choices": ["About 26 mL/cm H₂O", "About 20 mL/cm H₂O", "About 17 mL/cm H₂O", "About 35 mL/cm H₂O"], "correct": 0, "explanation": "700 ÷ (35 − 8) = 25.9 ≈ 26 (the PIP is a decoy).", "srcItem": "Compliance"},
    {"id": "q-m203-s05-084", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "VT 500 mL, PIP 30, Pplat 25, PEEP 5. What is the dynamic compliance?", "choices": ["20 mL/cm H₂O", "25 mL/cm H₂O", "16.7 mL/cm H₂O", "100 mL/cm H₂O"], "correct": 0, "explanation": "500 ÷ (30 − 5) = 20. (Static = 500 ÷ 20 = 25.)", "srcItem": "Compliance"},
    {"id": "q-m203-s05-085", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "VT 400 mL, flow 75 L/min, PIP 45, Pplat 30. What is the airway resistance?", "choices": ["12 cm H₂O/L/sec", "15 cm H₂O/L/sec", "0.2 cm H₂O/L/sec", "37.5 cm H₂O/L/sec"], "correct": 0, "explanation": "75 L/min = 1.25 L/sec. (45 − 30) ÷ 1.25 = 12.", "srcItem": "Compliance"},
    {"id": "q-m203-s05-086", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the normal static compliance for an INTUBATED adult per Heuer and the 203 deck?", "choices": ["40–80 mL/cm H₂O", "100–200 mL/cm H₂O", "10–20 mL/cm H₂O", "200–300 mL/cm H₂O"], "correct": 0, "explanation": "RCP 105 decks: 60–100. Below 25–30 = ↑ WOB and weaning difficulty; > 30 is the weaning minimum.", "srcItem": "Compliance"},
    {"id": "q-m203-s05-087", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is Pplat read from a pressure–time curve?", "choices": ["Add an end-inspiratory pause; read the flat shelf", "Read the highest point of the pressure curve", "Read the pressure at end-expiration", "Average the pressure over the whole breath"], "correct": 0, "explanation": "Heuer: 0.5–2.0 sec pause during volume ventilation with square flow.", "srcItem": "Compliance"},
    {"id": "q-m203-s05-088", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "During an inspiratory pause, the patient exhales and the plateau rises erratically. What is the effect?", "choices": ["Falsely high Pplat", "Falsely low Pplat", "Accurate Pplat", "Pplat equals PEEP"], "correct": 0, "explanation": "Exhaling during the pause → falsely high; inhaling → falsely low.", "srcItem": "Compliance"},
    {"id": "q-m203-s05-089", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A true descending-ramp breath delivers 1 L/sec for 0.5 sec with PIP 35 cm H₂O (flow reaches zero). What is the compliance?", "choices": ["About 14.3 mL/cm H₂O", "About 28.6 mL/cm H₂O", "About 7 mL/cm H₂O", "About 70 mL/cm H₂O"], "correct": 0, "explanation": "VT = 1 × 0.5 = 500 mL. Flow zero → PIP = Pplat. 500 ÷ 35 = 14.3.", "srcItem": "Compliance"},
    {"id": "q-m203-s05-090", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Over 4 hours, Pplat − PEEP stays constant while PIP − Pplat rises from 20 to 35. What is happening?", "choices": ["Increasing airway resistance", "Decreasing compliance", "Improving compliance", "A circuit leak"], "correct": 0, "explanation": "Heuer Box 4-5: pure resistance problem — bronchospasm, secretions, edema, tube occlusion.", "srcItem": "Compliance"},
    {"id": "q-m203-s05-091", "topic": "m203-s05", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why is static compliance useful as a weaning parameter?", "choices": ["It is independent of patient effort", "It requires maximal patient effort", "It measures inspiratory muscle strength", "It measures oxygenation directly"], "correct": 0, "explanation": "Static compliance, Raw and VD/VT are effort-independent.", "srcItem": "Compliance"},
    {"id": "q-m203-s06-001", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Where is the tip of a MACINTOSH (curved) blade placed?", "choices": ["In the vallecula, lifting the epiglottis indirectly", "Under the epiglottis, lifting it directly", "Into the esophagus", "On the vocal cords"], "correct": 0, "explanation": "Miller (straight) goes under the epiglottis and lifts it directly.", "srcItem": "Intubation"},
    {"id": "q-m203-s06-002", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which ETT sizes should be available at the bedside for intubation?", "choices": ["Chosen size, one larger, one smaller", "Only the chosen size", "Every size from 2 to 10 mm", "The chosen size and one smaller"], "correct": 0, "explanation": "Always have one size larger and one size smaller.", "srcItem": "Intubation"},
    {"id": "q-m203-s06-003", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which statement about the stylet is correct?", "choices": ["Oral only; tip never past the ETT tip", "Always used for nasal intubation", "Tip should extend 2 cm past the ETT", "It replaces the Magill forceps"], "correct": 0, "explanation": "Magill forceps are required for nasal intubation; a stylet is never used nasally.", "srcItem": "Intubation"},
    {"id": "q-m203-s06-004", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How long should each intubation attempt last per Heuer Ch 9?", "choices": ["No more than 20 seconds", "No more than 2 minutes", "No more than 60 seconds", "As long as needed"], "correct": 0, "explanation": "≤ 20 seconds (Ch 16 says ≤ 30), with 1–2 minutes of oxygenation between attempts.", "srcItem": "Intubation"},
    {"id": "q-m203-s06-005", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What position is used for oral intubation?", "choices": ["Sniffing position", "Trendelenburg", "Prone", "Left lateral decubitus"], "correct": 0, "explanation": "Sniffing position, suction the oropharynx, hyperoxygenate 1–2 minutes.", "srcItem": "Intubation"},
    {"id": "q-m203-s06-006", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How far past the vocal cords should the cuff be advanced?", "choices": ["2–3 cm past the cords", "Just to the cords", "10 cm past the cords", "To the carina"], "correct": 0, "explanation": "Advance until the cuff disappears 2–3 cm past the cords, then inflate to 20–30 cm H₂O.", "srcItem": "Intubation"},
    {"id": "q-m203-s06-007", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A colorimetric CO₂ detector confirms tracheal placement when it changes:", "choices": ["Purple → yellow/tan for 6+ breaths", "Yellow → purple for 6+ breaths", "White → blue after 3 breaths", "Any color change after 1 breath"], "correct": 0, "explanation": "Purple → yellow/tan sustained over ≥ 6 breaths. False negative in cardiac arrest.", "srcItem": "Intubation"},
    {"id": "q-m203-s06-008", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Gurgling is heard over the epigastrium after intubation. What should the RT do?", "choices": ["Remove the tube, reoxygenate, reintubate", "Advance the tube 2 cm and recheck", "Pull the tube back 2 cm and recheck", "Increase the cuff pressure"], "correct": 0, "explanation": "Epigastric gurgling = esophageal intubation.", "srcItem": "Intubation"},
    {"id": "q-m203-s06-009", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "After intubation, breath sounds are decreased on the LEFT. What is the likely cause and fix?", "choices": ["Right mainstem — withdraw until bilateral", "Left pneumothorax — insert a chest tube", "Esophageal intubation — remove the tube", "Normal after intubation — no action"], "correct": 0, "explanation": "The tube is too deep, usually into the right mainstem.", "srcItem": "Intubation"},
    {"id": "q-m203-s06-010", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What are the only two ways to confirm the tube is properly above the carina?", "choices": ["Chest x-ray or fiberoptic laryngoscopy", "Breath sounds and CO₂ detection", "SpO₂ and chest rise", "Cuff pressure and depth marking"], "correct": 0, "explanation": "Breath sounds and CO₂ prove the tube is in the airway, not that its depth is right.", "srcItem": "Intubation"},
    {"id": "q-m203-s06-011", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On chest x-ray, where should the ETT tip sit?", "choices": ["4–6 cm above the carina", "Right at the carina", "1 cm below the vocal cords", "In the right mainstem"], "correct": 0, "explanation": "Read with the head neutral — the tube moves with neck flexion and extension.", "srcItem": "Intubation"},
    {"id": "q-m203-s06-012", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the average oral ETT depth at the incisors for an adult male?", "choices": ["21–23 cm", "15–17 cm", "19–21 cm", "25–27 cm"], "correct": 0, "explanation": "Males 21–23 cm; females 19–21 cm; add 2 cm for nasal.", "srcItem": "Intubation"},
    {"id": "q-m203-s06-013", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A Cormack-Lehane Grade IV view shows:", "choices": ["No epiglottis (very difficult)", "The full glottic opening", "The epiglottis only", "The arytenoids only"], "correct": 0, "explanation": "Grade III = epiglottis only; Grade IV = no epiglottis.", "srcItem": "Intubation"},
    {"id": "q-m203-s06-014", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which mnemonic predicts a difficult INTUBATION?", "choices": ["LEMON", "MOANS", "SOAP", "ABCDE"], "correct": 0, "explanation": "LEMON: Look, Evaluate, Mallampati, Obesity/Obstruction, Neck mobility. MOANS predicts difficult BVM ventilation.", "srcItem": "Intubation"},
    {"id": "q-m203-s06-015", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is an OPA sized?", "choices": ["Mouth corner to angle of the jaw", "Tip of the nose to the earlobe", "Chin to the sternal notch", "Patient height ÷ 10"], "correct": 0, "explanation": "80 mm (3) average adult female, 90 mm (4) average adult male.", "srcItem": "Airway devices"},
    {"id": "q-m203-s06-016", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An OPA is appropriate for which patient?", "choices": ["A comatose patient whose tongue blocks the airway", "An alert patient recovering from surgery", "A patient with an intact gag reflex", "A patient with trismus (clenched jaw)"], "correct": 0, "explanation": "Not for conscious patients — gagging, vomiting, aspiration. Remove it immediately if the patient gags.", "srcItem": "Airway devices"},
    {"id": "q-m203-s06-017", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient with a gag reflex needs an airway adjunct to relieve upper airway obstruction. Which should be used?", "choices": ["Nasopharyngeal airway", "Oropharyngeal airway", "LMA", "Tracheostomy button"], "correct": 0, "explanation": "The NPA is the alternative when the gag is intact, or with trismus/seizures preventing mouth opening.", "srcItem": "Airway devices"},
    {"id": "q-m203-s06-018", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What size NPA is typical for an average adult male?", "choices": ["#7 (28 Fr)", "#4 (16 Fr)", "#9 (36 Fr)", "#5 (20 Fr)"], "correct": 0, "explanation": "#6 (24 Fr) average female; #7 (28 Fr) average male.", "srcItem": "Airway devices"},
    {"id": "q-m203-s06-019", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which rule applies to NPA use?", "choices": ["Never cut an NPA — the cut edge is sharp", "Insert it with force if resistance is met", "Lubricate it with petroleum jelly", "Use it in patients with nasal polyps"], "correct": 0, "explanation": "Lubricate with water-soluble jelly; if it won't pass, try the other naris, then a smaller size.", "srcItem": "Airway devices"},
    {"id": "q-m203-s06-020", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "When is a laryngeal mask airway (LMA) indicated?", "choices": ["As a rescue in the \"can ventilate, can't intubate\" scenario", "As a long-term airway for PPV", "To prevent aspiration in a full-stomach patient", "In a conscious patient with a gag reflex"], "correct": 0, "explanation": "The LMA is not a definitive airway and gives no aspiration protection.", "srcItem": "Airway devices"},
    {"id": "q-m203-s06-021", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the maximum LMA cuff pressure?", "choices": ["60 cm H₂O", "30 cm H₂O", "20 cm H₂O", "100 cm H₂O"], "correct": 0, "explanation": "Never exceed 60 cm H₂O. If a leak occurs, reposition — don't just add air.", "srcItem": "Airway devices"},
    {"id": "q-m203-s06-022", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the main advantage of a tracheostomy tube over an ETT for long-term ventilation?", "choices": ["Lower resistance, more comfort, and easier suctioning", "Better aspiration protection only", "It requires no cuff", "It can be placed at the bedside by the RT"], "correct": 0, "explanation": "Also less tube movement and easier reinsertion into a mature stoma.", "srcItem": "Airway devices"},
    {"id": "q-m203-s06-023", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why is the obturator kept at the bedside of a trach patient?", "choices": ["For reinsertion if the tube comes out", "To pass a suction catheter through", "To deflate the cuff quickly", "To measure cuff pressure"], "correct": 0, "explanation": "Remove it immediately after insertion (it blocks the airway) and keep it at the bedside.", "srcItem": "Airway devices"},
    {"id": "q-m203-s06-024", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is a tracheostomy button used for?", "choices": ["Keeping the stoma open after the trach is removed", "Providing positive pressure ventilation", "Sealing the airway with a cuff", "Delivering high-flow oxygen"], "correct": 0, "explanation": "No ventilatory support and no cuff. Distress with an uncapped button = protruding too far into the trachea.", "srcItem": "Airway devices"},
    {"id": "q-m203-s06-025", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "In a \"can't ventilate, can't intubate\" child under 12, what surgical airway does Heuer prefer?", "choices": ["Transtracheal jet ventilation", "Surgical cricothyrotomy", "Nasotracheal intubation", "A tracheostomy button"], "correct": 0, "explanation": "The small trachea makes cricothyrotomy hazardous. Jet ventilation is temporary, not definitive.", "srcItem": "Airway devices"},
    {"id": "q-m203-s06-026", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A tube that is too small for the trachea causes what cuff problem?", "choices": ["High cuff pressure needed to seal", "A cuff that cannot be inflated", "Low cuff pressure", "No effect"], "correct": 0, "explanation": "Fix = exchange for a larger tube, not more air.", "srcItem": "Tube size & cuff pressure"},
    {"id": "q-m203-s06-027", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the recommended cuff pressure range?", "choices": ["20–30 cm H₂O", "10–15 cm H₂O", "35–45 cm H₂O", "5–10 cm H₂O"], "correct": 0, "explanation": "30 = maximum; < 20 invites microaspiration and VAP; 25 is the typical NBRC high limit.", "srcItem": "Tube size & cuff pressure"},
    {"id": "q-m203-s06-028", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is normal tracheal capillary perfusion pressure?", "choices": ["25–35 mm Hg", "5–10 mm Hg", "50–60 mm Hg", "100 mm Hg"], "correct": 0, "explanation": "Keep the cuff < 25 mm Hg, and lower still in a hypotensive patient.", "srcItem": "Tube size & cuff pressure"},
    {"id": "q-m203-s06-029", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "30 cm H₂O is approximately how many mm Hg?", "choices": ["22 mm Hg", "41 mm Hg", "30 mm Hg", "14.7 mm Hg"], "correct": 0, "explanation": "mm Hg = cm H₂O ÷ 1.36. 30 ÷ 1.36 ≈ 22; 20 ÷ 1.36 ≈ 14.7.", "srcItem": "Tube size & cuff pressure"},
    {"id": "q-m203-s06-030", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A leak-free seal cannot be achieved at 30 cm H₂O. What does Heuer recommend?", "choices": ["Stay < 25–30 and change to a larger tube", "Keep adding air until the leak stops", "Switch to the minimal leak technique", "Increase the ventilator tidal volume"], "correct": 0, "explanation": "Never just keep adding air.", "srcItem": "Tube size & cuff pressure"},
    {"id": "q-m203-s06-031", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why does Heuer say to avoid the minimal leak technique in ventilated patients?", "choices": ["It increases the risk of VAP", "It raises cuff pressure too high", "It damages the pilot balloon", "It prevents suctioning"], "correct": 0, "explanation": "Maintain 20–30 cm H₂O instead. The deck presents MOV and MLT as equal options.", "srcItem": "Tube size & cuff pressure"},
    {"id": "q-m203-s06-032", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why must cuff pressure be ADJUSTED, not just measured, when a manometer is attached?", "choices": ["The manometer steals volume and lowers it", "The manometer adds extra pressure", "The cuff deflates completely", "It triggers the high-pressure alarm"], "correct": 0, "explanation": "Check at least once per shift and whenever the tube is moved or a leak appears.", "srcItem": "Tube size & cuff pressure"},
    {"id": "q-m203-s06-033", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Using the uncuffed formula, what size ETT does a 4-year-old need?", "choices": ["5.0 mm", "4.0 mm", "6.0 mm", "3.5 mm"], "correct": 0, "explanation": "(4 ÷ 4) + 4 = 5.0. Cuffed: (4 ÷ 4) + 3 = 4.0.", "srcItem": "ETT sizes"},
    {"id": "q-m203-s06-034", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Using the CUFFED formula, what size ETT does a 4-year-old need?", "choices": ["4.0 mm", "5.0 mm", "4.5 mm", "3.0 mm"], "correct": 0, "explanation": "Cuffed = (age ÷ 4) + 3 → 4.0 mm.", "srcItem": "ETT sizes"},
    {"id": "q-m203-s06-035", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Using the uncuffed formula, what size ETT does an 8-year-old need?", "choices": ["6.0 mm", "5.0 mm", "7.0 mm", "5.5 mm"], "correct": 0, "explanation": "(8 ÷ 4) + 4 = 6.0 mm; insertion length 15–17 cm.", "srcItem": "ETT sizes"},
    {"id": "q-m203-s06-036", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What ETT is used for a premature infant under 3 kg?", "choices": ["2.5–3.0 mm uncuffed", "4.0 mm cuffed", "3.5 mm cuffed", "5.0 mm uncuffed"], "correct": 0, "explanation": "Uncuffed tubes are recommended for premature infants and anyone < 3 kg.", "srcItem": "ETT sizes"},
    {"id": "q-m203-s06-037", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What ETT size does Heuer give for an adult female?", "choices": ["7.0–8.0 mm", "8.0–9.0 mm", "6.0–6.5 mm", "9.0–10.0 mm"], "correct": 0, "explanation": "Heuer: female 7.0–8.0, male 8.0–9.0 (deck: 7–7.5 and 8–8.5).", "srcItem": "ETT sizes"},
    {"id": "q-m203-s06-038", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Using Hess's rule, how deep should an ETT be at the lips in a 3-kg neonate?", "choices": ["About 9 cm", "About 3 cm", "About 12 cm", "About 6 cm"], "correct": 0, "explanation": "Weight in kg + 6 cm = 9 cm.", "srcItem": "ETT sizes"},
    {"id": "q-m203-s06-039", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the purpose of the WATER-SEAL chamber in a chest drainage system?", "choices": ["A one-way valve that lets air out, not in", "It collects blood and pleural fluid", "It sets the amount of suction", "It humidifies the pleural space"], "correct": 0, "explanation": "The tube is submerged 2 cm; refill if the level falls below 2 cm.", "srcItem": "Chest tube"},
    {"id": "q-m203-s06-040", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What determines the suction applied to the pleural space in a water-filled system?", "choices": ["Water depth in the suction-control chamber", "The wall vacuum regulator setting", "The collection chamber volume", "The depth of the water seal"], "correct": 0, "explanation": "Fill to 20 cm → −20 cm H₂O, whether the wall reads 80 or 150 mm Hg.", "srcItem": "Chest tube"},
    {"id": "q-m203-s06-041", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What suction level is usually applied to a chest tube?", "choices": ["−10 to −20 cm H₂O", "−60 to −80 cm H₂O", "−2 cm H₂O", "−100 mm Hg"], "correct": 0, "explanation": "Deck −10 to −20; Heuer usually −20.", "srcItem": "Chest tube"},
    {"id": "q-m203-s06-042", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Gentle continuous bubbling is seen in the SUCTION-CONTROL chamber. What does it mean?", "choices": ["Normal operation", "An air leak", "An obstruction", "The suction is too low"], "correct": 0, "explanation": "Vigorous bubbling means the wall vacuum is too high — more noise and evaporation, not more suction.", "srcItem": "Chest tube"},
    {"id": "q-m203-s06-043", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Continuous bubbling is seen in the WATER-SEAL chamber. What does it indicate?", "choices": ["An air leak", "Normal operation", "An obstructed tube", "Correct suction level"], "correct": 0, "explanation": "Pinch the tube at the insertion site: bubbling stops → leak at site or patient; continues → leak in the system.", "srcItem": "Chest tube"},
    {"id": "q-m203-s06-044", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "The water-seal chamber shows no tidaling. What does this mean?", "choices": ["Obstruction (or the lung re-expanded)", "The system is working perfectly", "There is an air leak", "The suction is set too high"], "correct": 0, "explanation": "Check for kinks and dependent loops, milk the tubing; if it fails, assess for pneumothorax.", "srcItem": "Chest tube"},
    {"id": "q-m203-s06-045", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How does the water-seal level move during spontaneous breathing?", "choices": ["Rises on inspiration, falls on expiration", "Falls on inspiration, rises on expiration", "Stays still", "Bubbles continuously"], "correct": 0, "explanation": "Reversed during positive pressure ventilation.", "srcItem": "Chest tube"},
    {"id": "q-m203-s06-046", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Drainage eyelets on the chest tube become visible outside the chest. What should the RT do?", "choices": ["Notify the physician; don't push it in", "Push the tube back in gently", "Clamp the tube immediately", "Increase the suction level"], "correct": 0, "explanation": "The tube has partially pulled out.", "srcItem": "Chest tube"},
    {"id": "q-m203-s06-047", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How should a patient with a chest tube be transported?", "choices": ["Unit below chest level, tube NOT clamped", "Tube clamped to prevent leaks", "Unit above chest level", "Disconnect the unit for transport"], "correct": 0, "explanation": "Clamping can convert an air leak into a tension pneumothorax.", "srcItem": "Chest tube"},
    {"id": "q-m203-s06-048", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which direction is a chest tube aimed for a pneumothorax versus a hemothorax?", "choices": ["Superiorly for air; inferiorly/posteriorly for fluid", "Inferiorly for air; superiorly for fluid", "Always superiorly", "Always inferiorly"], "correct": 0, "explanation": "Air rises, fluid falls.", "srcItem": "Chest tube"},
    {"id": "q-m203-s06-049", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Where is needle decompression performed for a tension pneumothorax?", "choices": ["2nd intercostal space, midclavicular line", "5th intercostal space, midaxillary line", "8th intercostal space, posterior", "Subxiphoid"], "correct": 0, "explanation": "Then a chest tube at the 4th–5th ICS.", "srcItem": "Chest tube"},
    {"id": "q-m203-s06-050", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What are the deck's criteria for chest tube removal?", "choices": ["< 100 mL/day, lung up, no air leak", "< 500 mL/day, any leak is acceptable", "Any time 24 hours after insertion", "As soon as suction bubbling stops"], "correct": 0, "explanation": "Follow up with a CXR in 4 hours; crepitus at the site suggests air leaking back.", "srcItem": "Chest tube"},
    {"id": "q-m203-s06-051", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On chest x-ray, which finding suggests a PNEUMOTHORAX?", "choices": ["Black space with no lung markings at the edge", "Blunted costophrenic angle with a meniscus", "Air bronchograms in a white area", "An elevated hemidiaphragm"], "correct": 0, "explanation": "Supine films may show a deep sulcus sign. Exam: hyperresonance, absent breath sounds.", "srcItem": "Chest x-ray"},
    {"id": "q-m203-s06-052", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On chest x-ray, what is the earliest sign of a pleural effusion?", "choices": ["Blunted costophrenic angles", "A deep sulcus sign", "Air bronchograms", "Hyperlucent lung fields"], "correct": 0, "explanation": "Also a meniscus; confirm with a lateral decubitus film.", "srcItem": "Chest x-ray"},
    {"id": "q-m203-s06-053", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which way does the trachea shift with a large pneumothorax or pleural effusion?", "choices": ["Away from the affected side", "Toward the affected side", "No shift", "Always to the right"], "correct": 0, "explanation": "Toward areas of collapse; away from space-occupying processes.", "srcItem": "Chest x-ray"},
    {"id": "q-m203-s06-054", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which way does the trachea shift with lobar atelectasis?", "choices": ["Toward the affected side", "Away from the affected side", "No shift", "Always to the left"], "correct": 0, "explanation": "Atelectasis also elevates the hemidiaphragm on the affected side.", "srcItem": "Chest x-ray"},
    {"id": "q-m203-s06-055", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "White (radiopaque) areas with air bronchograms on chest x-ray indicate:", "choices": ["Infiltrates (consolidation, ARDS)", "Pneumothorax", "Emphysema", "Normal lung"], "correct": 0, "explanation": "ARDS = bilateral diffuse infiltrates; VAP = new or progressive infiltrate.", "srcItem": "Chest x-ray"},
    {"id": "q-m203-s06-056", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A hemothorax is confirmed when the pleural fluid hematocrit is:", "choices": ["≥ 50% of the blood hematocrit", "Below 10% of blood hematocrit", "Equal to zero", "Above 100% of blood hematocrit"], "correct": 0, "explanation": "Treat with a large-bore chest tube (about 36 Fr), directed inferiorly.", "srcItem": "Chest x-ray"},
    {"id": "q-m203-s06-057", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is pleurisy recognized?", "choices": ["Friction rub with pain on deep breaths", "A distinct white shadow on the CXR", "Tracheal shift toward the affected side", "Hyperresonance on percussion"], "correct": 0, "explanation": "Pleurisy has no distinct CXR appearance of its own unless an effusion develops.", "srcItem": "Chest x-ray"},
    {"id": "q-m203-s06-058", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which effusion is caused by systemic pressure changes like CHF or cirrhosis?", "choices": ["Transudate", "Exudate", "Empyema", "Hemothorax"], "correct": 0, "explanation": "Transudate: thin, low-protein, few cells — fix the systemic problem. Exudate: high protein from local disease.", "srcItem": "Pleural effusion"},
    {"id": "q-m203-s06-059", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An effusion with high protein and many cells from pneumonia or cancer is a:", "choices": ["Exudate", "Transudate", "Chylothorax", "Simple effusion"], "correct": 0, "explanation": "High protein = local pleural disease. Exudates need antibiotics, drainage or a cancer workup.", "srcItem": "Pleural effusion"},
    {"id": "q-m203-s06-060", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "When is therapeutic thoracentesis recommended?", "choices": ["When the effusion causes distress", "For every small effusion found", "Only for transudative effusions", "Only after pleurodesis has failed"], "correct": 0, "explanation": "Diagnostic thoracentesis determines transudate vs exudate.", "srcItem": "Pleural effusion"},
    {"id": "q-m203-s06-061", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Before thoracentesis, what should the RT recommend?", "choices": ["A cough suppressant", "A bronchodilator", "Chest physiotherapy", "Incentive spirometry"], "correct": 0, "explanation": "Coughing during the procedure can injure the lung or pleura.", "srcItem": "Pleural effusion"},
    {"id": "q-m203-s06-062", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "After thoracentesis, what imaging is needed?", "choices": ["CXR or ultrasound to rule out pneumothorax", "No imaging — breath sounds are enough", "A CT scan of the head", "A V/Q scan of the lungs"], "correct": 0, "explanation": "Call the physician for dyspnea, hypotension, chest pain, or hemoptysis.", "srcItem": "Pleural effusion"},
    {"id": "q-m203-s06-063", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is a recurrent malignant pleural effusion treated long term?", "choices": ["Pleurodesis (talc or tetracycline)", "Repeated courses of antibiotics", "Incentive spirometry at home", "Scheduled bronchodilators"], "correct": 0, "explanation": "The sclerosant fuses the pleura; painful pleurisy is the trade-off.", "srcItem": "Pleural effusion"},
    {"id": "q-m203-s06-064", "topic": "m203-s06", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is an empyema treated?", "choices": ["Drain it — antibiotics alone won't reach pus", "Antibiotics alone for two full weeks", "Diuretics to pull the fluid off", "Observation until it resolves by itself"], "correct": 0, "explanation": "Chest tube drainage; may need thoracotomy.", "srcItem": "Pleural effusion"},
    {"id": "q-m203-s07-001", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On chest x-ray, what does radiopacity (white) indicate?", "choices": ["More tissue or fluid", "More air in the lung", "Normal lung tissue", "Air under the diaphragm"], "correct": 0, "explanation": "Radiopacity = white = more stuff; radiolucency = black = more air.", "srcItem": "CXR correlation"},
    {"id": "q-m203-s07-002", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Percussion over a pneumothorax is:", "choices": ["Hyperresonant", "Dull", "Flat", "Normal"], "correct": 0, "explanation": "Pneumothorax: hyperresonant, decreased fremitus, absent breath sounds, trachea shifted away.", "srcItem": "CXR correlation"},
    {"id": "q-m203-s07-003", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which set of findings fits lobar pneumonia (consolidation)?", "choices": ["Dull percussion, increased fremitus, bronchial breath sounds", "Hyperresonance, decreased fremitus, absent breath sounds", "Dull percussion, absent fremitus, trachea shifted away", "Normal percussion and fremitus, stridor"], "correct": 0, "explanation": "Denser tissue transmits sound better — increased fremitus and bronchial breath sounds in the periphery.", "srcItem": "CXR correlation"},
    {"id": "q-m203-s07-004", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which set of findings fits a large pleural effusion?", "choices": ["Dull percussion, absent fremitus, absent breath sounds, trachea shifted away", "Hyperresonance, increased fremitus, bronchial breath sounds", "Dull percussion, increased fremitus, trachea shifted toward", "Normal percussion and fremitus"], "correct": 0, "explanation": "Fluid separates the lung from the chest wall.", "srcItem": "CXR correlation"},
    {"id": "q-m203-s07-005", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which set of findings fits atelectasis per Heuer?", "choices": ["Dull, absent fremitus, trachea shifted toward", "Hyperresonant, trachea shifted away", "Normal note, increased fremitus, no shift", "Dull, increased fremitus, trachea shifted away"], "correct": 0, "explanation": "Heuer Table 2-18: absent vocal fremitus; elevated hemidiaphragm; shift toward.", "srcItem": "CXR correlation"},
    {"id": "q-m203-s07-006", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Percussion over the chest of a patient with COPD or acute asthma is typically:", "choices": ["Increased resonance", "Dull", "Flat", "Decreased resonance"], "correct": 0, "explanation": "Hyperinflation → increased resonance; COPD CXR shows a flattened diaphragm.", "srcItem": "CXR correlation"},
    {"id": "q-m203-s07-007", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What does a dull percussion note indicate?", "choices": ["Denser tissue — pneumonia, atelectasis, tumor", "Hyperinflation from COPD or asthma", "Air in the pleural space", "Normal air-filled lung"], "correct": 0, "explanation": "Dull/flat = short, muted, high-pitched.", "srcItem": "CXR correlation"},
    {"id": "q-m203-s07-008", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is normal diaphragmatic excursion by percussion in adults?", "choices": ["5–7 cm", "1–2 cm", "10–15 cm", "0.5 cm"], "correct": 0, "explanation": "Reduced in neuromuscular disease and severe hyperinflation.", "srcItem": "CXR correlation"},
    {"id": "q-m203-s07-009", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On CXR, an ELEVATED hemidiaphragm suggests:", "choices": ["Atelectasis or phrenic nerve paralysis", "Emphysema with hyperinflation", "Tension pneumothorax", "Acute asthma"], "correct": 0, "explanation": "A flattened diaphragm suggests hyperinflation, tension pneumothorax, or a large effusion.", "srcItem": "CXR correlation"},
    {"id": "q-m203-s07-010", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which CXR findings suggest heart failure?", "choices": ["Cardiomegaly, upper-lobe vessels, Kerley B", "Hyperlucent lungs and a flat diaphragm", "Upper-lobe cavities with calcification", "A deep sulcus sign on a supine film"], "correct": 0, "explanation": "Plus pleural effusions.", "srcItem": "CXR correlation"},
    {"id": "q-m203-s07-011", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is crepitus?", "choices": ["A crackling feeling from air trapped under the skin", "A breath sound heard with a stethoscope", "A pleural friction rub", "A type of wheeze"], "correct": 0, "explanation": "Subcutaneous emphysema — the \"Rice Krispies\" feel on palpation.", "srcItem": "Crepitus"},
    {"id": "q-m203-s07-012", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Crepitus is found in the neck of a patient on positive pressure ventilation. What should the RT do?", "choices": ["Assess for pneumothorax; notify the physician", "Ignore it — crepitus is always harmless", "Increase the PEEP to seal the leak", "Increase the tidal volume"], "correct": 0, "explanation": "Subcutaneous emphysema itself is harmless but often occurs with a pneumothorax; recommend a CXR.", "srcItem": "Crepitus"},
    {"id": "q-m203-s07-013", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Crepitus appears at a chest tube insertion site after the tube is removed. What does it suggest?", "choices": ["Air leaking back into the pleura", "Normal healing of the incision", "A wound infection developing", "A new pleural effusion"], "correct": 0, "explanation": "Heuer: it always suggests recurrence of air leakage.", "srcItem": "Crepitus"},
    {"id": "q-m203-s07-014", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is orthopnea?", "choices": ["Breathlessness lying flat, eased by sitting up", "Breathlessness only during exercise", "Breathlessness only when standing", "Rapid breathing only during sleep"], "correct": 0, "explanation": "A patient \"always elevated with pillows\" implies orthopnea and CHF.", "srcItem": "Orthopnea"},
    {"id": "q-m203-s07-015", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What quick bedside question helps quantify orthopnea?", "choices": ["\"How many pillows do you use?\"", "\"How far can you walk?\"", "\"Do you snore at night?\"", "\"When did you last eat?\""], "correct": 0, "explanation": "Formally, breathlessness is graded with the Borg scale (0–10).", "srcItem": "Orthopnea"},
    {"id": "q-m203-s07-016", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A BNP of 60 pg/mL in a dyspneic patient suggests:", "choices": ["CHF is unlikely (< 100)", "Severe CHF", "Moderate CHF", "Acute MI"], "correct": 0, "explanation": "Heuer: < 100 rules out CHF; > 500 rules it in. Distinguishes cardiac from pulmonary dyspnea.", "srcItem": "Orthopnea"},
    {"id": "q-m203-s07-017", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A BNP of 800 pg/mL in a dyspneic patient suggests:", "choices": ["CHF is likely", "COPD exacerbation", "Normal findings", "Pneumothorax"], "correct": 0, "explanation": "> 500 rules in CHF (Heuer).", "srcItem": "Orthopnea"},
    {"id": "q-m203-s07-018", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which test is used to detect an acute MI as a cause of dyspnea?", "choices": ["Troponin I", "BNP", "D-dimer", "Sweat chloride"], "correct": 0, "explanation": "Troponin rises 3–6 hours after injury, peaks at 12 hours, and lasts about 7 days.", "srcItem": "Orthopnea"},
    {"id": "q-m203-s07-019", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient answers correctly for person, place and time. How is this documented?", "choices": ["Oriented × 3", "Lethargic", "Obtunded", "Oriented × 1"], "correct": 0, "explanation": "Add situation for × 4.", "srcItem": "Level of consciousness"},
    {"id": "q-m203-s07-020", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A very drowsy patient can be aroused but has a reduced cough and gag reflex. What LOC is this, and what is the concern?", "choices": ["Obtunded — aspiration risk", "Lethargic — no concern", "Stuporous — normal airway", "Alert — no concern"], "correct": 0, "explanation": "Obtunded patients may not protect the airway.", "srcItem": "Level of consciousness"},
    {"id": "q-m203-s07-021", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient responds only to strong or painful stimuli. What LOC is this?", "choices": ["Stuporous", "Lethargic", "Obtunded", "Comatose"], "correct": 0, "explanation": "Comatose = no response to any stimulus.", "srcItem": "Level of consciousness"},
    {"id": "q-m203-s07-022", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the range of the Glasgow Coma Scale?", "choices": ["3 to 15", "0 to 10", "1 to 5", "0 to 100"], "correct": 0, "explanation": "3 = deep coma; 15 = fully alert.", "srcItem": "Level of consciousness"},
    {"id": "q-m203-s07-023", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What GCS score indicates the need to intubate for airway protection?", "choices": ["8 or less", "13 or less", "15", "12"], "correct": 0, "explanation": "≤ 8 = coma/severe impairment. 9–12 moderate; 13–15 mild.", "srcItem": "Level of consciousness"},
    {"id": "q-m203-s07-024", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient's GCS is charted E3, V2, M2. What is the total and severity?", "choices": ["7 — severe impairment", "12 — moderate impairment", "14 — mild impairment", "5 — brain death"], "correct": 0, "explanation": "3 + 2 + 2 = 7.", "srcItem": "Level of consciousness"},
    {"id": "q-m203-s07-025", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What does the AVPU scale assess?", "choices": ["Alert, Verbal, Pain, Unresponsive", "Airway, Ventilation, Perfusion, Urine", "Age, Vitals, Pulse, Unit", "Aspiration, Vomiting, Pain, Urgency"], "correct": 0, "explanation": "A quick consciousness check; GCS is the most objective.", "srcItem": "Level of consciousness"},
    {"id": "q-m203-s07-026", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Where is CENTRAL cyanosis seen?", "choices": ["Lips, mouth and tongue", "Only the fingertips", "Only the feet", "The earlobes only"], "correct": 0, "explanation": "Central = oxygenation problem. Peripheral = perfusion problem, seen in the extremities and nail beds.", "srcItem": "Cyanosis"},
    {"id": "q-m203-s07-027", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How much reduced hemoglobin must be present for cyanosis to be visible?", "choices": ["At least 5 g/dL", "At least 1 g/dL", "At least 15 g/dL", "Any amount"], "correct": 0, "explanation": "The deck's figure. It depends on an absolute amount of desaturated Hb.", "srcItem": "Cyanosis"},
    {"id": "q-m203-s07-028", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why can an anemic patient be severely hypoxic without cyanosis?", "choices": ["There isn't 5 g/dL of reduced Hb to be seen", "Anemia makes skin darker", "Anemia raises SaO₂", "Cyanosis only appears in children"], "correct": 0, "explanation": "Polycythemic patients can look cyanotic yet have adequate O₂ content.", "srcItem": "Cyanosis"},
    {"id": "q-m203-s07-029", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Peripheral cyanosis with cool extremities and capillary refill ≥ 3 seconds indicates:", "choices": ["Circulatory failure", "Normal findings", "Central hypoxemia", "CO poisoning"], "correct": 0, "explanation": "Peripheral cyanosis can occur with a completely normal SaO₂.", "srcItem": "Cyanosis"},
    {"id": "q-m203-s07-030", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "With normal hemoglobin, central cyanosis generally appears when SaO₂ falls below about:", "choices": ["About 80%", "About 95%", "About 90%", "About 60%"], "correct": 0, "explanation": "Cyanosis is a late, unreliable sign.", "srcItem": "Cyanosis"},
    {"id": "q-m203-s07-031", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is PEA?", "choices": ["Organized rhythm on the monitor, no pulse", "Chaotic quivering of the ventricles", "A normal rhythm with a weak pulse", "A flat line with no electrical activity"], "correct": 0, "explanation": "One of four pulseless rhythms: VF, pulseless VT, PEA, asystole.", "srcItem": "PEA"},
    {"id": "q-m203-s07-032", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is PEA treated?", "choices": ["CPR and epinephrine every 3–5 min", "Immediate defibrillation at 200 J", "Synchronized cardioversion", "Atropine alone every 3–5 min"], "correct": 0, "explanation": "PEA and asystole are NOT shockable.", "srcItem": "PEA"},
    {"id": "q-m203-s07-033", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which of the following is one of the reversible causes of PEA (H's and T's)?", "choices": ["Tension pneumothorax", "Hyperglycemia", "Acute asthma", "Hypertension"], "correct": 0, "explanation": "5 H's: hypovolemia, hypoxia, H⁺ (acidosis), hypo/hyperkalemia, hypothermia. 5 T's: tension pneumothorax, tamponade, toxins, pulmonary and coronary thrombosis.", "srcItem": "PEA"},
    {"id": "q-m203-s07-034", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which reversible causes of PEA does the RT directly address?", "choices": ["Hypoxia, acidosis, tension pneumothorax", "Hypothermia, toxins, and tamponade", "Tamponade, hypovolemia, and thrombosis", "Hyperkalemia, thrombosis, and toxins"], "correct": 0, "explanation": "Airway/O₂, ventilation, and decompression.", "srcItem": "PEA"},
    {"id": "q-m203-s07-035", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "If IV access is unavailable, how is epinephrine given by ETT?", "choices": ["Double the dose, then a saline flush", "The same dose with no flush", "Half the IV dose, no flush", "It cannot be given by ETT"], "correct": 0, "explanation": "Intraosseous access is another option.", "srcItem": "PEA"},
    {"id": "q-m203-s07-036", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "During CPR, a PetCO₂ below 10 mm Hg indicates:", "choices": ["CPR quality must be improved", "Excellent CPR", "Return of spontaneous circulation", "Hyperventilation"], "correct": 0, "explanation": "Failure to reach PetCO₂ > 10 after 20 minutes can be used to consider terminating resuscitation.", "srcItem": "PEA"},
    {"id": "q-m203-s07-037", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How many electrodes are placed to record a 12-lead ECG?", "choices": ["10", "12", "6", "3"], "correct": 0, "explanation": "10 electrodes; the augmented leads (aVR, aVL, aVF) are derived.", "srcItem": "ECG"},
    {"id": "q-m203-s07-038", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Where is V1 placed?", "choices": ["4th intercostal space, right sternal border", "4th intercostal space, left sternal border", "5th intercostal space, midclavicular line", "5th intercostal space, midaxillary line"], "correct": 0, "explanation": "V2 = 4th ICS left sternal border; V4 = 5th ICS midclavicular; V6 = 5th ICS midaxillary.", "srcItem": "ECG"},
    {"id": "q-m203-s07-039", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Where is V4 placed?", "choices": ["5th intercostal space, midclavicular line", "4th intercostal space, left sternal border", "5th intercostal space, anterior axillary line", "2nd intercostal space, midclavicular line"], "correct": 0, "explanation": "V5 = 5th ICS anterior axillary.", "srcItem": "ECG"},
    {"id": "q-m203-s07-040", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which limb electrode placement is correct?", "choices": ["White on right arm, black on left arm", "Black on right arm, white on left arm", "Red on right arm, green on left leg", "Green on left leg, red on right leg"], "correct": 0, "explanation": "\"White on right\"; \"smoke over fire\" (black over red); \"clouds over grass\" (white over green).", "srcItem": "ECG"},
    {"id": "q-m203-s07-041", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "The ECG machine fails to obtain a signal from one lead. What is the most likely cause?", "choices": ["A loose or bad lead, or hair", "Patient hyperventilation", "A pneumothorax", "The wrong paper speed"], "correct": 0, "explanation": "A noisy signal = poor connection, motion, or filtering (sweaty skin, shivering, 60-Hz interference).", "srcItem": "ECG"},
    {"id": "q-m203-s07-042", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A 12-lead tracing suddenly looks bizarre. What should the RT do first?", "choices": ["Look at the patient", "Call a code", "Defibrillate", "Replace the machine"], "correct": 0, "explanation": "Check the patient before calling it an arrhythmia; then check snaps, electrode gel, cable, motion, filters.", "srcItem": "ECG"},
    {"id": "q-m203-s07-043", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Using the rule of 300, what is the heart rate if there are 4 large boxes between R waves?", "choices": ["75/min", "60/min", "100/min", "150/min"], "correct": 0, "explanation": "300 ÷ 4 = 75.", "srcItem": "ECG"},
    {"id": "q-m203-s07-044", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Tall, peaked T waves suggest:", "choices": ["Hyperkalemia", "Hypokalemia", "Hypocalcemia", "Hypothermia"], "correct": 0, "explanation": "Prominent U waves = hypokalemia or hypomagnesemia. ST elevation = acute STEMI.", "srcItem": "ECG"},
    {"id": "q-m203-s07-045", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is ventricular fibrillation treated?", "choices": ["CPR and unsynchronized defibrillation", "Synchronized cardioversion at 100 J", "Atropine 0.5 mg IV every 3–5 min", "Adenosine 6 mg by rapid IV push"], "correct": 0, "explanation": "Biphasic 120–200 J; monophasic 360 J; then epinephrine and amiodarone or lidocaine.", "srcItem": "ECG"},
    {"id": "q-m203-s07-046", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is pulseless ventricular tachycardia treated?", "choices": ["Unsynchronized defibrillation", "Synchronized cardioversion", "Atropine 0.5 mg IV", "Observation only"], "correct": 0, "explanation": "Never cardiovert VF, pulseless VT, or polymorphic VT.", "srcItem": "ECG"},
    {"id": "q-m203-s07-047", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which rhythm is treated with SYNCHRONIZED cardioversion?", "choices": ["Stable VT with a pulse", "Ventricular fibrillation", "Asystole", "Pulseless VT"], "correct": 0, "explanation": "Also SVT, A-fib and atrial flutter. VF and pulseless VT need unsynchronized defibrillation.", "srcItem": "ECG"},
    {"id": "q-m203-s07-048", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is symptomatic bradycardia treated?", "choices": ["Atropine 0.5 mg, up to 3 mg", "Defibrillation at 200 J", "Adenosine 6 mg rapid push", "Amiodarone 300 mg IV"], "correct": 0, "explanation": "Also epinephrine, dopamine, and pacing.", "srcItem": "ECG"},
    {"id": "q-m203-s07-049", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A sawtooth pattern appears between QRS complexes with no PR interval. What is the rhythm?", "choices": ["Atrial flutter", "Atrial fibrillation", "Ventricular tachycardia", "Sinus rhythm"], "correct": 0, "explanation": "Flutter is treated with synchronized cardioversion (50–100 J biphasic).", "srcItem": "ECG"},
    {"id": "q-m203-s07-050", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Frequent PVCs appear during a respiratory treatment. What should the RT do?", "choices": ["Stop, give O₂, notify the physician", "Continue the treatment as ordered", "Defibrillate the patient", "Give atropine 0.5 mg"], "correct": 0, "explanation": "Stop, stabilize with supplemental O₂, notify.", "srcItem": "ECG"},
    {"id": "q-m203-s07-051", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the initial pediatric defibrillation dose?", "choices": ["2 J/kg", "10 J/kg", "0.5 J/kg", "360 J"], "correct": 0, "explanation": "Subsequent shocks at least 4 J/kg.", "srcItem": "ECG"},
    {"id": "q-m203-s07-052", "topic": "m203-s07", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which drug is used for SVT and should be given centrally with an immediate flush?", "choices": ["Adenosine", "Atropine", "Amiodarone", "Epinephrine"], "correct": 0, "explanation": "Adenosine has a 12-second half-life; side effects include bronchospasm.", "srcItem": "ECG"},
    {"id": "q-m203-s08-001", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A lung CAPACITY is always:", "choices": ["Two or more lung volumes added together", "A single volume that cannot be divided", "Measured only by body box", "The same as tidal volume"], "correct": 0, "explanation": "Primary volumes: VT, IRV, ERV, RV. Capacities: IC, FRC, VC, TLC.", "srcItem": "Lung volumes"},
    {"id": "q-m203-s08-002", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which lung volume cannot be measured by simple spirometry?", "choices": ["Residual volume", "Tidal volume", "Inspiratory reserve volume", "Expiratory reserve volume"], "correct": 0, "explanation": "RV can never be exhaled, so FRC (and RV, TLC) must be measured indirectly.", "srcItem": "Lung volumes"},
    {"id": "q-m203-s08-003", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Functional residual capacity (FRC) equals:", "choices": ["ERV + RV", "IRV + VT", "VT + ERV", "IRV + VT + ERV"], "correct": 0, "explanation": "FRC = RV + ERV = TLC − IC.", "srcItem": "Lung volumes"},
    {"id": "q-m203-s08-004", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Vital capacity equals:", "choices": ["IRV + VT + ERV", "IRV + VT + RV", "ERV + RV", "TLC + RV"], "correct": 0, "explanation": "VC = IRV + VT + ERV = TLC − RV.", "srcItem": "Lung volumes"},
    {"id": "q-m203-s08-005", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Inspiratory capacity equals:", "choices": ["IRV + VT", "ERV + RV", "VT + ERV", "TLC − IRV"], "correct": 0, "explanation": "IC = IRV + VT. Normal ≈ 3.6 L.", "srcItem": "Lung volumes"},
    {"id": "q-m203-s08-006", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "FRC is 3800 mL and ERV is 1300 mL. What is the RV?", "choices": ["2500 mL", "5100 mL", "1300 mL", "3400 mL"], "correct": 0, "explanation": "RV = FRC − ERV = 3800 − 1300 = 2500 mL (Heuer B.16).", "srcItem": "Lung volumes"},
    {"id": "q-m203-s08-007", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "TLC is 6.0 L and VC is 4.8 L. What is the RV?", "choices": ["1.2 L", "10.8 L", "2.4 L", "3.6 L"], "correct": 0, "explanation": "RV = TLC − VC = 1.2 L.", "srcItem": "Lung volumes"},
    {"id": "q-m203-s08-008", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the normal adult TLC?", "choices": ["About 6.0 L", "About 2.4 L", "About 4.8 L", "About 1.2 L"], "correct": 0, "explanation": "TLC 6.0; FRC 2.4; VC 4.8; RV 1.2; IC 3.6.", "srcItem": "Lung volumes"},
    {"id": "q-m203-s08-009", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the normal adult FRC?", "choices": ["About 2.4 L", "About 1.2 L", "About 3.6 L", "About 6.0 L"], "correct": 0, "explanation": "FRC = ERV (1.2) + RV (1.2) = 2.4 L.", "srcItem": "Lung volumes"},
    {"id": "q-m203-s08-010", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What FEV₁/FVC ratio indicates obstruction?", "choices": ["Less than 70%", "Less than 90%", "Greater than 70%", "Greater than 100%"], "correct": 0, "explanation": "A normal FEV₁% is 70% or more.", "srcItem": "Lung volumes"},
    {"id": "q-m203-s08-011", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A reduced FEF25–75% (≤ 70% predicted) indicates:", "choices": ["Small airway obstruction", "Large airway obstruction", "Restrictive disease", "Normal lungs"], "correct": 0, "explanation": "FEF200–1200 ≤ 70% indicates large airway obstruction.", "srcItem": "Lung volumes"},
    {"id": "q-m203-s08-012", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What percent-predicted range is considered normal for PFT values?", "choices": ["80–120%", "50–69%", "70–79%", "Below 49%"], "correct": 0, "explanation": "Mild 70–79%; moderate 50–69%; severe < 49%.", "srcItem": "Lung volumes"},
    {"id": "q-m203-s08-013", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Measured FVC is 3.25 L; predicted is 3.82 L. What is the percent predicted?", "choices": ["About 85%", "About 118%", "About 57%", "About 72%"], "correct": 0, "explanation": "3.25 ÷ 3.82 × 100 = 85% (Heuer B.19).", "srcItem": "PFTs"},
    {"id": "q-m203-s08-014", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Pre-bronchodilator FEV₁ is 2.4 L; post is 2.7 L. What is the percent change?", "choices": ["12.5%", "11.1%", "30.0%", "8.0%"], "correct": 0, "explanation": "(2.7 − 2.4) ÷ 2.4 = 12.5% — meets the 12–15% bar.", "srcItem": "PFTs"},
    {"id": "q-m203-s08-015", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Pre-bronchodilator FEV₁ is 3.0 L; post is 3.3 L. Is this a significant response?", "choices": ["No — 10% is below the 12% threshold", "Yes — any increase is significant", "Yes — 300 mL is enough", "No — it is a 30% change"], "correct": 0, "explanation": "(3.3 − 3.0) ÷ 3.0 = 10%.", "srcItem": "PFTs"},
    {"id": "q-m203-s08-016", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What FEV₁ improvement after bronchodilator indicates reversible obstruction?", "choices": ["≥ 12–15% and/or ≥ 200 mL", "≥ 5% and ≥ 50 mL", "≥ 50% and ≥ 1 L", "≥ 25% only"], "correct": 0, "explanation": "Heuer says \"or\"; the 203 and asthma decks say \"and.\"", "srcItem": "PFTs"},
    {"id": "q-m203-s08-017", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "After giving a bronchodilator, how long should the RT wait before post-spirometry?", "choices": ["15–30 minutes", "1–2 minutes", "2 hours", "24 hours"], "correct": 0, "explanation": "Wait for peak drug effect (10–30 min for peak flow).", "srcItem": "PFTs"},
    {"id": "q-m203-s08-018", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is PEFR best used for?", "choices": ["Monitoring obstruction over time", "Diagnosing COPD", "Measuring residual volume", "Measuring diffusing capacity"], "correct": 0, "explanation": "Heuer: use PEFR to monitor obstruction, not to diagnose it.", "srcItem": "PFTs"},
    {"id": "q-m203-s08-019", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which test is used to follow interstitial lung disease or emphysema and separate emphysema from chronic bronchitis?", "choices": ["DLCO", "PEFR", "MVV", "Methacholine challenge"], "correct": 0, "explanation": "DLCO is low in emphysema and fibrosis; normal in chronic bronchitis and asthma.", "srcItem": "PFTs"},
    {"id": "q-m203-s08-020", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is a hazard of the helium dilution test?", "choices": ["Hypercapnia or hypoxemia", "Claustrophobia in the box", "Depressed drive from 100% O₂", "Bronchospasm from methacholine"], "correct": 0, "explanation": "Leaks (poor seal, perforated eardrum, trach) also invalidate it.", "srcItem": "PFTs"},
    {"id": "q-m203-s08-021", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which patient may not tolerate body plethysmography?", "choices": ["A claustrophobic patient", "A patient with emphysema", "A patient who can't hold their breath", "A patient on home O₂"], "correct": 0, "explanation": "The patient sits in a sealed box.", "srcItem": "PFTs"},
    {"id": "q-m203-s08-022", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "If three acceptable maneuvers cannot be obtained, the results should be:", "choices": ["Not reported", "Reported as the best single effort", "Averaged", "Doubled"], "correct": 0, "explanation": "Report the two largest FVC and FEV₁ values from acceptable efforts.", "srcItem": "PFTs"},
    {"id": "q-m203-s08-023", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which PFT pattern is OBSTRUCTIVE?", "choices": ["↓ FEV₁/FVC, ↑ TLC, ↑ RV", "Normal FEV₁/FVC, ↓ TLC, ↓ RV", "All values normal", "↓ FVC with ↑ FEV₁/FVC and ↓ TLC"], "correct": 0, "explanation": "Obstructive: FEV₁ falls more than FVC; hyperinflation and air trapping.", "srcItem": "PFT patterns"},
    {"id": "q-m203-s08-024", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which PFT pattern is RESTRICTIVE?", "choices": ["↓ FVC, normal FEV₁/FVC, ↓ TLC", "↓ FEV₁/FVC, ↑ TLC, ↑ RV", "↑ RV and ↑ TLC, ↓ FEV₁", "Normal FVC, TLC and ratio"], "correct": 0, "explanation": "FEV₁ and FVC fall together, so the ratio is preserved; TLC < 80% predicted.", "srcItem": "PFT patterns"},
    {"id": "q-m203-s08-025", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "FEV₁/FVC < 70%, VC and TLC both reduced. What pattern is this?", "choices": ["Mixed (combined)", "Pure obstructive", "Pure restrictive", "Normal"], "correct": 0, "explanation": "\"All three ↓ = Combined.\"", "srcItem": "PFT patterns"},
    {"id": "q-m203-s08-026", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "FEV₁/FVC is < 70% and DLCO is low. What is the likely diagnosis?", "choices": ["Emphysema", "Asthma", "Chronic bronchitis", "Kyphoscoliosis"], "correct": 0, "explanation": "Heuer's algorithm: obstructive + low DLCO = emphysema; normal DLCO = asthma or chronic bronchitis.", "srcItem": "PFT patterns"},
    {"id": "q-m203-s08-027", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A restrictive pattern with a LOW DLCO suggests:", "choices": ["Pulmonary fibrosis (ILD)", "Neuromuscular disease", "Obesity", "Kyphoscoliosis"], "correct": 0, "explanation": "Restrictive + normal DLCO = chest wall or neuromuscular; low DLCO = ILD.", "srcItem": "PFT patterns"},
    {"id": "q-m203-s08-028", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which is an example of RESTRICTIVE disease?", "choices": ["Kyphoscoliosis", "Emphysema", "Asthma", "Bronchiectasis"], "correct": 0, "explanation": "Also fibrosis, neuromuscular disease, obesity, large effusion.", "srcItem": "PFT patterns"},
    {"id": "q-m203-s08-029", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "FVC efforts vary widely and aren't reproducible. What does this suggest?", "choices": ["Poor effort or technique", "Restrictive disease", "Obstructive disease", "Normal lungs"], "correct": 0, "explanation": "Consider poor effort whenever PEFR is significantly low; also check patient data entry.", "srcItem": "PFT patterns"},
    {"id": "q-m203-s08-030", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Percent-predicted values look falsely high or low for all tests. What should the RT check first?", "choices": ["The entered age, height, sex, ethnicity", "The patient's effort on each trial", "The 3-L calibration syringe", "The DLCO test gas mixture"], "correct": 0, "explanation": "Heuer: incorrect data entry is the usual cause — re-enter and recompute.", "srcItem": "PFT patterns"},
    {"id": "q-m203-s08-031", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What result is a POSITIVE methacholine challenge?", "choices": ["FEV₁ falls by 20% or more", "FEV₁ rises by 12%", "FVC rises by 200 mL", "PEFR falls by 5%"], "correct": 0, "explanation": "≥ 20% fall = airway hyperresponsiveness, consistent with asthma.", "srcItem": "Bronchoprovocation"},
    {"id": "q-m203-s08-032", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient's baseline FEV₁ is 3.0 L before a methacholine challenge. At what FEV₁ is the test positive?", "choices": ["2.4 L or below", "2.7 L or below", "1.5 L or below", "3.6 L or above"], "correct": 0, "explanation": "20% of 3.0 = 0.6 → 3.0 − 0.6 = 2.4 L.", "srcItem": "Bronchoprovocation"},
    {"id": "q-m203-s08-033", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "When is bronchoprovocation testing used?", "choices": ["Asthma suspected, spirometry nondiagnostic", "To confirm COPD after bronchodilator", "To measure the FRC and RV", "To measure diffusing capacity"], "correct": 0, "explanation": "Also occupational asthma and response to therapy.", "srcItem": "Bronchoprovocation"},
    {"id": "q-m203-s08-034", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which FRC method measures ALL gas in the chest, including trapped gas?", "choices": ["Body plethysmography", "Helium dilution", "Nitrogen washout", "Simple spirometry"], "correct": 0, "explanation": "The body box measures thoracic gas volume (TGV). Dilution methods measure only communicating lung.", "srcItem": "Lung volume methods"},
    {"id": "q-m203-s08-035", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "TGV by body box is larger than FRC by helium dilution. What does this indicate?", "choices": ["Trapped gas not reaching the airways", "A leak in the helium circuit", "Restrictive lung disease", "Normal lungs"], "correct": 0, "explanation": "Seen in bullous emphysema and air trapping.", "srcItem": "Lung volume methods"},
    {"id": "q-m203-s08-036", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How long does the multi-breath nitrogen washout test run?", "choices": ["7 min or until N₂ < 1%", "30 seconds", "1 hour", "Until the patient tires"], "correct": 0, "explanation": "The patient breathes 100% O₂; ventilatory drive may be depressed.", "srcItem": "Lung volume methods"},
    {"id": "q-m203-s08-037", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which lung volume method UNDERESTIMATES FRC in air trapping?", "choices": ["Helium dilution", "Body plethysmography", "Both equally", "Neither"], "correct": 0, "explanation": "Helium only reaches lung that communicates with the airways.", "srcItem": "Lung volume methods"},
    {"id": "q-m203-s08-038", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "In the single-breath N₂ test, Phase III represents:", "choices": ["Alveolar gas (the alveolar plateau)", "Pure dead space", "Mixed dead space and alveolar gas", "Closing volume"], "correct": 0, "explanation": "Phase I = dead space; II = mixed; III = alveolar plateau; IV = closing volume.", "srcItem": "Single-breath N₂"},
    {"id": "q-m203-s08-039", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A steep Phase III slope on a single-breath N₂ test indicates:", "choices": ["Uneven distribution of ventilation", "Normal, uniform ventilation", "A restrictive disease", "A leak in the system"], "correct": 0, "explanation": "The slope steepens in COPD, asthma, bronchiectasis, CF and with aging.", "srcItem": "Single-breath N₂"},
    {"id": "q-m203-s08-040", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What does Phase IV of the single-breath N₂ test represent?", "choices": ["Closing volume", "Pure dead space", "The alveolar plateau", "Inspiratory reserve"], "correct": 0, "explanation": "Closing volume increases with age and obstructive disease.", "srcItem": "Single-breath N₂"},
    {"id": "q-m203-s08-041", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is a shunt?", "choices": ["Perfusion without ventilation — wasted blood", "Ventilation without perfusion — wasted air", "Normal gas exchange", "A diffusion defect"], "correct": 0, "explanation": "Shunt produces refractory hypoxemia that doesn't respond to more FiO₂.", "srcItem": "Shunt"},
    {"id": "q-m203-s08-042", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Using Heuer's rule of thumb on 100% O₂, how much shunt does each 100 torr of P(A-a)O₂ represent?", "choices": ["About 5%", "About 1%", "About 10%", "About 20%"], "correct": 0, "explanation": "% shunt ≈ (P(A-a)O₂ ÷ 100) × 5.", "srcItem": "Shunt"},
    {"id": "q-m203-s08-043", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient on 100% O₂ has a P(A-a)O₂ of 300 torr. What is the estimated shunt?", "choices": ["15%", "30%", "3%", "60%"], "correct": 0, "explanation": "300 ÷ 100 × 5 = 15%.", "srcItem": "Shunt"},
    {"id": "q-m203-s08-044", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "FiO₂ 1.0, PB 760, PaCO₂ 60, PaO₂ 250. What is the PAO₂?", "choices": ["638 torr", "713 torr", "463 torr", "388 torr"], "correct": 0, "explanation": "PAO₂ = 1.0 × (760 − 47) − (1.25 × 60) = 713 − 75 = 638.", "srcItem": "Shunt"},
    {"id": "q-m203-s08-045", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Same patient: PAO₂ 638, PaO₂ 250 on 100% O₂. What is the estimated shunt?", "choices": ["About 19%", "About 39%", "About 5%", "About 13%"], "correct": 0, "explanation": "A-a = 388 → 388 ÷ 100 × 5 ≈ 19%.", "srcItem": "Shunt"},
    {"id": "q-m203-s08-046", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the classic physiologic shunt equation?", "choices": ["Qs/Qt = (CcO₂ − CaO₂) ÷ (CcO₂ − Cv̄O₂)", "Qs/Qt = (CaO₂ − Cv̄O₂) ÷ CcO₂", "Qs/Qt = PaO₂ ÷ PAO₂", "Qs/Qt = VD ÷ VT"], "correct": 0, "explanation": "The gold standard (from the deck; not in Heuer).", "srcItem": "Shunt"},
    {"id": "q-m203-s08-047", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "CcO₂ 22.1, CaO₂ 18.3, Cv̄O₂ 15.2 mL/dL. What is the shunt fraction?", "choices": ["About 55%", "About 17%", "About 83%", "About 25%"], "correct": 0, "explanation": "(22.1 − 18.3) ÷ (22.1 − 15.2) = 3.8 ÷ 6.9 = 0.55.", "srcItem": "Shunt"},
    {"id": "q-m203-s08-048", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What shunt fraction is considered normal?", "choices": ["Less than 5–10%", "20–30%", "Greater than 30%", "50%"], "correct": 0, "explanation": "Deck: < 5%, or ≤ 10% calculated. 10–20% mild, 20–30% significant, > 30% critical.", "srcItem": "Shunt"},
    {"id": "q-m203-s08-049", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the maximum shunt fraction for a weaning attempt?", "choices": ["Less than 20%", "Less than 50%", "Less than 40%", "Less than 35%"], "correct": 0, "explanation": "Qs/Qt < 20% with P/F ≥ 150.", "srcItem": "Shunt"},
    {"id": "q-m203-s08-050", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What does an a/A ratio below 0.35 suggest?", "choices": ["Hypoxemia due to shunting", "Normal oxygenation", "V/Q mismatch only", "Hypoventilation"], "correct": 0, "explanation": "Normal > 0.75; 0.35–0.75 likely V/Q mismatch.", "srcItem": "Shunt"},
    {"id": "q-m203-s08-051", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "FiO₂ 1.0, mean airway pressure 20 cm H₂O, PaO₂ 50. What is the Oxygenation Index?", "choices": ["40", "4", "10", "25"], "correct": 0, "explanation": "(1.0 × 20 × 100) ÷ 50 = 40 — high mortality / ECMO range.", "srcItem": "Shunt"},
    {"id": "q-m203-s08-052", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What does MIP (NIF) measure?", "choices": ["Inspiratory muscle strength", "Expiratory muscle strength", "Lung compliance", "Airway resistance"], "correct": 0, "explanation": "MEP measures expiratory strength (the cough).", "srcItem": "NIF"},
    {"id": "q-m203-s08-053", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the normal adult MIP per Heuer?", "choices": ["−80 to −100 cm H₂O", "−5 to −10 cm H₂O", "−20 to −25 cm H₂O", "+60 cm H₂O"], "correct": 0, "explanation": "The 203 deck says normal NIF is > −60.", "srcItem": "NIF"},
    {"id": "q-m203-s08-054", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which statement about MIP and MEP measurement is correct per Heuer?", "choices": ["MIP needs no consciousness; MEP does", "Both require an unconscious patient", "Neither requires patient cooperation", "MEP needs a one-way valve; MIP doesn't"], "correct": 0, "explanation": "The one-way valve ensures maximal MIP effort. The 203 deck says both need an alert patient.", "srcItem": "NIF"},
    {"id": "q-m203-s08-055", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A Guillain-Barré patient should be intubated when MIP falls below:", "choices": ["Weaker than −25 cm H₂O", "Weaker than −80 cm H₂O", "Weaker than −100 cm H₂O", "Weaker than −60 cm H₂O"], "correct": 0, "explanation": "Or MEP < 40 cm H₂O, or rapidly declining values.", "srcItem": "NIF"},
    {"id": "q-m203-s08-056", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Per the 203 deck, what minimum NIF does a COPD patient need?", "choices": ["More negative than −40 cm H₂O", "More negative than −10", "More negative than −100", "Any value"], "correct": 0, "explanation": "> −40 for COPD; > −20 for myasthenia gravis; −20 minimum for vent patients to extubate.", "srcItem": "NIF"},
    {"id": "q-m203-s08-057", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An ABG shows pH 7.22, PaCO₂ 65, HCO₃⁻ 26. Interpret.", "choices": ["Acute respiratory acidosis", "Chronic compensated respiratory acidosis", "Metabolic acidosis", "Combined acidosis"], "correct": 0, "explanation": "HCO₃⁻ is still normal — the kidneys haven't responded yet.", "srcItem": "ABG patterns"},
    {"id": "q-m203-s08-058", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An ABG shows pH 7.36, PaCO₂ 58, HCO₃⁻ 34. Interpret.", "choices": ["Compensated respiratory acidosis", "Acute respiratory acidosis", "Compensated metabolic alkalosis", "Normal acid-base status"], "correct": 0, "explanation": "Typical COPD CO₂ retainer. pH normal on the acid side.", "srcItem": "ABG patterns"},
    {"id": "q-m203-s08-059", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An ABG shows pH 7.57, PaCO₂ 25, HCO₃⁻ 22. Interpret.", "choices": ["Acute respiratory alkalosis", "Metabolic alkalosis", "Compensated respiratory alkalosis", "Metabolic acidosis"], "correct": 0, "explanation": "Often hyperventilation from hypoxemia (pneumonia, asthma, PE).", "srcItem": "ABG patterns"},
    {"id": "q-m203-s08-060", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An ABG shows pH 7.32, PaCO₂ 28, HCO₃⁻ 14 in a DKA patient. Interpret.", "choices": ["Partially compensated metabolic acidosis", "Acute respiratory alkalosis", "Compensated respiratory acidosis", "Metabolic alkalosis"], "correct": 0, "explanation": "Low HCO₃⁻ with a low PaCO₂ (compensating); pH still low → partial.", "srcItem": "ABG patterns"},
    {"id": "q-m203-s08-061", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An ABG shows pH 7.05, PaCO₂ 60, HCO₃⁻ 16 during cardiac arrest. Interpret.", "choices": ["Combined respiratory and metabolic acidosis", "Acute respiratory acidosis only", "Metabolic acidosis only", "Compensated acidosis"], "correct": 0, "explanation": "High PaCO₂ + low base = the two diverge = combined acidosis.", "srcItem": "ABG patterns"},
    {"id": "q-m203-s08-062", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An ABG shows pH 7.44, PaCO₂ 28, HCO₃⁻ 19. Interpret.", "choices": ["Compensated respiratory alkalosis", "Acute respiratory alkalosis", "Compensated metabolic acidosis", "Combined alkalosis"], "correct": 0, "explanation": "Both PaCO₂ and HCO₃⁻ are low (same direction = compensation) and pH is on the alkaline side.", "srcItem": "ABG patterns"},
    {"id": "q-m203-s08-063", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Using the deck's rule, PaCO₂ rises acutely from 40 to 60 mm Hg. What is the expected pH?", "choices": ["About 7.28", "About 7.34", "About 7.20", "About 7.40"], "correct": 0, "explanation": "Every 10 mm Hg rise → pH falls ~0.06: 7.40 − 0.12 = 7.28; HCO₃⁻ rises ~2 to 26.", "srcItem": "ABG patterns"},
    {"id": "q-m203-s08-064", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How fast does renal compensation for a respiratory problem occur?", "choices": ["Slowly, over hours to days", "Within minutes", "Within seconds", "It never occurs"], "correct": 0, "explanation": "Respiratory compensation for a metabolic problem is fast (minutes).", "srcItem": "ABG patterns"},
    {"id": "q-m203-s08-065", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A COPD patient's usual ABG is 7.36 / 77 / HCO₃⁻ 43. Today it is 7.28 / 99 / 44. What is this?", "choices": ["Acute-on-chronic ventilatory failure", "Improvement from baseline", "Acute metabolic alkalosis", "Acute alveolar hyperventilation"], "correct": 0, "explanation": "The PaCO₂ rose and the pH fell beyond the patient's baseline.", "srcItem": "ABG patterns"},
    {"id": "q-m203-s08-066", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the normal adult inspiratory flow?", "choices": ["40–60 L/min", "5–10 L/min", "100–120 L/min", "15–20 L/min"], "correct": 0, "explanation": "Compare every calculated answer against this.", "srcItem": "Inspiratory flow"},
    {"id": "q-m203-s08-067", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is %I-time calculated from an I:E ratio of 1:4?", "choices": ["1 ÷ 5 = 20%", "1 ÷ 4 = 25%", "4 ÷ 5 = 80%", "1 × 4 = 4%"], "correct": 0, "explanation": "1:1 = 50%; 1:2 = 33%; 1:3 = 25%; 1:4 = 20%.", "srcItem": "Inspiratory flow"},
    {"id": "q-m203-s08-068", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Rate 15, VT 600 mL, I:E 1:4. What inspiratory flow should be set?", "choices": ["45 L/min", "36 L/min", "9 L/min", "60 L/min"], "correct": 0, "explanation": "VE = 9 L/min ÷ 0.20 = 45 L/min (Heuer Box 13-1).", "srcItem": "Inspiratory flow"},
    {"id": "q-m203-s08-069", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Rate 20, VT 500 mL, I:E 1:3. What inspiratory flow is needed?", "choices": ["40 L/min", "30 L/min", "10 L/min", "60 L/min"], "correct": 0, "explanation": "VE = 10 L/min ÷ 0.25 = 40 L/min.", "srcItem": "Inspiratory flow"},
    {"id": "q-m203-s08-070", "topic": "m203-s08", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What happens if inspiratory flow is set too LOW?", "choices": ["Long I-time, air trapping, auto-PEEP", "Short I-time and hyperventilation", "A higher delivered FiO₂", "Lower PIP with no side effects"], "correct": 0, "explanation": "Fix by raising the flow to shorten I-time and lengthen E-time.", "srcItem": "Inspiratory flow"},
    {"id": "q-m203-s09-001", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the difference between capnometry and capnography?", "choices": ["Capnometry = number; capnography = number + waveform", "They are two names for the same measurement", "Capnometry measures O₂; capnography measures CO₂", "Capnography is measured in arterial blood"], "correct": 0, "explanation": "Capnogram = the waveform itself.", "srcItem": "Capnography"},
    {"id": "q-m203-s09-002", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On a normal capnogram, Phase I (A–B) represents:", "choices": ["Deadspace gas, CO₂ near zero", "The alveolar plateau", "Inspiration of fresh gas", "Deadspace mixing with alveolar gas"], "correct": 0, "explanation": "I = deadspace; II = rapid upstroke (mixing); III = alveolar plateau; IV = inspiratory downstroke.", "srcItem": "Capnography"},
    {"id": "q-m203-s09-003", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Where on the capnogram is PETCO₂ measured?", "choices": ["At the end of the alveolar plateau (Phase III)", "At the start of exhalation", "At the lowest point of inspiration", "At the middle of the upstroke"], "correct": 0, "explanation": "End-tidal = the very end of Phase III.", "srcItem": "Capnography"},
    {"id": "q-m203-s09-004", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "The capnogram baseline does not return to zero during inspiration. What does this suggest?", "choices": ["Rebreathing or an equipment problem", "A normal finding on inspiration", "Hyperventilation from anxiety", "Esophageal intubation"], "correct": 0, "explanation": "A good tracing has a zero inspiratory baseline.", "srcItem": "Capnography"},
    {"id": "q-m203-s09-005", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which capnogram shape suggests bronchospasm or obstruction?", "choices": ["A sloped, blunted \"shark fin\" shape", "A tall, square-shaped wave", "A flat line at zero", "A baseline rising off zero"], "correct": 0, "explanation": "The obstructive (\"shark fin\") pattern.", "srcItem": "Capnography"},
    {"id": "q-m203-s09-006", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is an advantage of a MAINSTREAM capnography sensor?", "choices": ["Fast response; not affected by water", "It can attach to a nasal cannula", "It adds no deadspace or weight", "Secretions never affect its readings"], "correct": 0, "explanation": "Disadvantages: weight on the ETT, added deadspace, secretions on the windows.", "srcItem": "Capnography"},
    {"id": "q-m203-s09-007", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is a disadvantage of a SIDESTREAM capnography sensor?", "choices": ["Water and secretions can occlude the sample line", "It adds heavy weight to the ETT", "It can only be used on intubated patients", "It is not affected by condensation"], "correct": 0, "explanation": "Advantages: easy handling, usable with a cannula or mask.", "srcItem": "Capnography"},
    {"id": "q-m203-s09-008", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "The PETCO₂ waveform and value suddenly drop to zero on a ventilated patient. What is the likely cause?", "choices": ["Disconnection or complete obstruction", "Rapidly improving ventilation", "A sudden rise in cardiac output", "A fever with high CO₂ output"], "correct": 0, "explanation": "Also esophageal intubation (no waveform).", "srcItem": "Capnography"},
    {"id": "q-m203-s09-009", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "PETCO₂ suddenly drops (but not to zero) in a patient whose blood pressure is falling. What is the likely cause?", "choices": ["Falling cardiac output", "Hypoventilation", "Rebreathing", "Increased metabolic rate"], "correct": 0, "explanation": "Values drop suddenly and proportionally with cardiac arrest or falling CO.", "srcItem": "Capnography"},
    {"id": "q-m203-s09-010", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "PETCO₂ falls suddenly because of a pulmonary embolism. Which action would be a MISTAKE?", "choices": ["Lowering the ventilator rate", "Notifying the physician", "Checking an ABG", "Assessing the patient"], "correct": 0, "explanation": "The drop reflects increased alveolar deadspace, not improved ventilation.", "srcItem": "Capnography"},
    {"id": "q-m203-s09-011", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "PETCO₂ gradually rises over several hours. What does this suggest?", "choices": ["Hypoventilation or ↑ CO₂ production", "Hyperventilation or ↓ CO₂ production", "A circuit disconnection", "A sudden cardiac arrest"], "correct": 0, "explanation": "Confirm with an ABG.", "srcItem": "Capnography"},
    {"id": "q-m203-s09-012", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "During CPR, PETCO₂ suddenly rises from 12 to 38 mm Hg. What does this suggest?", "choices": ["Return of spontaneous circulation", "Circuit disconnection", "Poor-quality CPR", "Esophageal intubation"], "correct": 0, "explanation": "PETCO₂ < 10 = poor pulmonary blood flow; a rise signals effective compressions or ROSC.", "srcItem": "Capnography"},
    {"id": "q-m203-s09-013", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the gold standard for confirming tracheal tube placement?", "choices": ["Waveform capnography", "Bilateral breath sounds", "Symmetric chest rise", "A rising SpO₂"], "correct": 0, "explanation": "Esophageal intubation gives no waveform.", "srcItem": "Capnography"},
    {"id": "q-m203-s09-014", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How does PETCO₂ normally compare to PaCO₂?", "choices": ["1–5 torr lower", "1–5 torr higher", "Exactly equal", "About half"], "correct": 0, "explanation": "Exhaled gas is diluted by deadspace gas. Normal PETCO₂ ≈ 30–43 mm Hg.", "srcItem": "PaCO₂ vs PETCO₂"},
    {"id": "q-m203-s09-015", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the normal P(a–et)CO₂ gradient per Chang?", "choices": ["About 2 mm Hg", "About 20 mm Hg", "About 10 mm Hg", "Zero"], "correct": 0, "explanation": "The 203 deck gives 1–5 torr.", "srcItem": "PaCO₂ vs PETCO₂"},
    {"id": "q-m203-s09-016", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What primarily WIDENS the PaCO₂–PETCO₂ gradient?", "choices": ["Increased alveolar deadspace (PE)", "Hypoventilation", "Increased cardiac output", "Intrapulmonary shunt"], "correct": 0, "explanation": "Also age, pulmonary disease and ventilator changes.", "srcItem": "PaCO₂ vs PETCO₂"},
    {"id": "q-m203-s09-017", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Once a good PaCO₂–PETCO₂ correlation is established, what can be reduced?", "choices": ["The number of routine ABGs", "The ventilator rate", "The FiO₂", "PEEP"], "correct": 0, "explanation": "PETCO₂ trends can stand in for routine ABGs.", "srcItem": "PaCO₂ vs PETCO₂"},
    {"id": "q-m203-s09-018", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Where is the phlebostatic axis for leveling a hemodynamic transducer?", "choices": ["4th intercostal space, midaxillary line", "2nd intercostal space, midclavicular line", "5th intercostal space, anterior axillary line", "The sternal notch"], "correct": 0, "explanation": "Improper leveling causes false high or low readings.", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-019", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "When should CVP and PCWP be read?", "choices": ["At end-expiration, without removing PEEP", "At end-inspiration", "After disconnecting from the ventilator", "At any point in the cycle"], "correct": 0, "explanation": "If PEEP > 10, correct: measured − [0.5 × (PEEP ÷ 1.36)].", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-020", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient on PEEP 15 has a measured PCWP of 20 mm Hg. What is the corrected PCWP?", "choices": ["About 14.5 mm Hg", "About 12.5 mm Hg", "About 20 mm Hg", "About 25.5 mm Hg"], "correct": 0, "explanation": "20 − [0.5 × (15 ÷ 1.36)] = 20 − 5.5 ≈ 14.5.", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-021", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the normal CVP (Chang)?", "choices": ["0–6 mm Hg", "8–12 mm Hg", "15–25 mm Hg", "25–35 mm Hg"], "correct": 0, "explanation": "RCP 103 deck gives 2–6. RAP 2–7 mm Hg.", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-022", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What does CVP estimate?", "choices": ["Right ventricular preload", "Left ventricular preload", "Left ventricular afterload", "Right ventricular afterload"], "correct": 0, "explanation": "CVP = RV preload; PCWP = LV preload; PVR = RV afterload; SVR = LV afterload.", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-023", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient with cor pulmonale is likely to have which CVP?", "choices": ["Elevated", "Low", "Normal", "Zero"], "correct": 0, "explanation": "CVP rises with RV failure, fluid overload and positive pressure; falls with hypovolemia.", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-024", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the normal pulmonary artery pressure (systolic/diastolic)?", "choices": ["15–25 / 6–12 mm Hg", "120 / 80 mm Hg", "0–6 mm Hg", "40–50 / 20–25 mm Hg"], "correct": 0, "explanation": "Mean PAP 10–20. Pulmonary hypertension = mean PAP > 25 at rest.", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-025", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the normal PCWP?", "choices": ["8–12 mm Hg", "0–6 mm Hg", "20–25 mm Hg", "30–40 mm Hg"], "correct": 0, "explanation": "PCWP estimates left atrial pressure and LV preload.", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-026", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient in pulmonary edema has a PCWP of 24 mm Hg. What type of edema is this?", "choices": ["Cardiogenic", "Noncardiogenic (ARDS)", "Neither — PCWP is normal", "Neurogenic"], "correct": 0, "explanation": "Cardiogenic > 18 mm Hg; noncardiogenic (ARDS) < 18.", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-027", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient with bilateral infiltrates and hypoxemia has a PCWP of 9 mm Hg. What does this suggest?", "choices": ["Noncardiogenic edema (ARDS)", "Left heart failure", "Mitral stenosis", "Fluid overload"], "correct": 0, "explanation": "A normal/low PCWP points away from a cardiac cause.", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-028", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the normal cardiac output?", "choices": ["4–8 L/min", "1–2 L/min", "10–15 L/min", "0.5–1 L/min"], "correct": 0, "explanation": "Cardiac index 2.5–3.5 L/min/m².", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-029", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "CO is 5 L/min and BSA is 2.0 m². What is the cardiac index?", "choices": ["2.5 L/min/m² — normal", "10 L/min/m² — high", "1.5 L/min/m² — low", "5.0 L/min/m² — high"], "correct": 0, "explanation": "CI = CO ÷ BSA = 5 ÷ 2 = 2.5.", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-030", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "CO is 5 L/min and HR is 80. What is the stroke volume?", "choices": ["About 62 mL", "About 400 mL", "About 16 mL", "About 0.6 mL"], "correct": 0, "explanation": "SV = 5000 mL ÷ 80 = 62.5 mL. Normal 60–130.", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-031", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "MAP 90, CVP 5, CO 5 L/min. What is the SVR?", "choices": ["1360 dynes·sec/cm⁵ — normal", "136 dynes·sec/cm⁵ — low", "2720 dynes·sec/cm⁵ — high", "85 dynes·sec/cm⁵ — low"], "correct": 0, "explanation": "SVR = [(MAP − CVP) ÷ CO] × 80 = (85 ÷ 5) × 80 = 1360. Normal 900–1400.", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-032", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Mean PAP 20, PCWP 10, CO 5 L/min. What is the PVR?", "choices": ["160 dynes·sec/cm⁵ — normal", "400 dynes·sec/cm⁵ — high", "16 dynes·sec/cm⁵ — low", "1600 dynes·sec/cm⁵ — high"], "correct": 0, "explanation": "PVR = [(MPAP − PCWP) ÷ CO] × 80 = (10 ÷ 5) × 80 = 160. Normal 110–250.", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-033", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the normal mixed venous O₂ saturation (SvO₂)?", "choices": ["About 75%", "About 98%", "About 50%", "About 25%"], "correct": 0, "explanation": "SvO₂ < 30–50% signals lactic acidosis; < 25% cellular death.", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-034", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which condition LOWERS the SvO₂?", "choices": ["Low cardiac output or anemia", "Hypothermia and sedation", "Cyanide poisoning", "Sepsis with poor O₂ use"], "correct": 0, "explanation": "↓ O₂ delivery or ↑ consumption lowers SvO₂. Sepsis and cyanide can raise it.", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-035", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What pulse pressure is normal?", "choices": ["30–40 mm Hg", "5–10 mm Hg", "60–80 mm Hg", "100 mm Hg"], "correct": 0, "explanation": "Wide > 40; narrow < 30.", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-036", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What MAP is needed for tissue perfusion?", "choices": ["At least 60 mm Hg", "At least 30 mm Hg", "At least 120 mm Hg", "At least 45 mm Hg"], "correct": 0, "explanation": "≥ 70 mm Hg to maintain cerebral perfusion pressure.", "srcItem": "Hemodynamics"},
    {"id": "q-m203-s09-037", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the maximum inflation volume of a PA catheter balloon?", "choices": ["1.5 mL", "5 mL", "10 mL", "0.5 mL"], "correct": 0, "explanation": "Inflate only momentarily to wedge, then deflate immediately.", "srcItem": "PA catheters"},
    {"id": "q-m203-s09-038", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "In what order does a PA catheter travel after insertion?", "choices": ["SVC → right atrium → right ventricle → pulmonary artery → wedge", "Aorta → left ventricle → left atrium → pulmonary vein", "Right atrium → left atrium → pulmonary artery", "Pulmonary vein → left atrium → right ventricle"], "correct": 0, "explanation": "The balloon is inflated in the RA so blood flow carries it forward.", "srcItem": "PA catheters"},
    {"id": "q-m203-s09-039", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is cardiac output measured with a PA catheter?", "choices": ["Thermodilution with cold injectate", "By reading the wedge pressure", "By measuring SvO₂ only", "From the arterial line pressure"], "correct": 0, "explanation": "The thermistor at the tip detects the temperature change.", "srcItem": "PA catheters"},
    {"id": "q-m203-s09-040", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is PAP read versus PCWP?", "choices": ["PAP deflated; PCWP briefly inflated", "Both read with the balloon inflated", "Both read with the balloon deflated", "PAP inflated; PCWP deflated"], "correct": 0, "explanation": "Read the wedge at end-expiration, then deflate immediately.", "srcItem": "PA catheters"},
    {"id": "q-m203-s09-041", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Where does the proximal (injectate) port of a PA catheter sit?", "choices": ["In the right atrium", "In the pulmonary artery", "In the left ventricle", "In the aorta"], "correct": 0, "explanation": "The distal port is in the pulmonary artery.", "srcItem": "PA catheters"},
    {"id": "q-m203-s09-042", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What does the dicrotic notch on a PA tracing represent?", "choices": ["Closure of the pulmonic valve", "Opening of the mitral valve", "Atrial contraction", "Tricuspid closure"], "correct": 0, "explanation": "Hess: systolic, diastolic, and dicrotic notch.", "srcItem": "PA catheters"},
    {"id": "q-m203-s09-043", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What temperature is used for a transcutaneous sensor monitoring both PtcO₂ and PtcCO₂?", "choices": ["44°C", "37°C only", "30°C", "50°C"], "correct": 0, "explanation": "Heat arterializes the capillary bed. As low as 37°C for PtcCO₂ only; max 45°C.", "srcItem": "Transcutaneous"},
    {"id": "q-m203-s09-044", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Where should a transcutaneous sensor be placed?", "choices": ["Well-perfused skin — chest, abdomen, thigh", "Directly over a bony prominence", "On an edematous area", "Over a healing burn"], "correct": 0, "explanation": "Clean with alcohol, apply gel without bubbles, seal edges, and allow 5–20 minutes to stabilize.", "srcItem": "Transcutaneous"},
    {"id": "q-m203-s09-045", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why must transcutaneous sensor sites be rotated?", "choices": ["To prevent burns from the heated sensor", "To recalibrate the monitor", "To improve the PtcCO₂ reading", "To use less contact gel"], "correct": 0, "explanation": "Chang: every 4 hours; the 203 deck: every 2–6 hours.", "srcItem": "Transcutaneous"},
    {"id": "q-m203-s09-046", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "In which patients does PtcO₂ most closely approximate PaO₂?", "choices": ["Neonates and infants", "Obese adults", "Elderly adults", "Patients in shock"], "correct": 0, "explanation": "Adult skin is thicker so PtcO₂ reads low; pulse oximetry is preferred in adults.", "srcItem": "Transcutaneous"},
    {"id": "q-m203-s09-047", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which condition makes transcutaneous readings inaccurate?", "choices": ["Poor perfusion or shock", "Normal cardiac output", "Warm, well-perfused skin", "A newborn patient"], "correct": 0, "explanation": "Also edema, hypothermia, underheating, bony sites, excess gel, PaO₂ > 80–100.", "srcItem": "Transcutaneous"},
    {"id": "q-m203-s09-048", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How does PtcCO₂ normally compare to PaCO₂?", "choices": ["Higher, from heat-increased CO₂", "Lower, from diffusion loss", "Always identical", "Zero"], "correct": 0, "explanation": "Correlate with a simultaneous arterial or capillary sample after setup.", "srcItem": "Transcutaneous"},
    {"id": "q-m203-s09-049", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why is infant PtcO₂ monitoring valuable?", "choices": ["Screens for hyperoxemia to prevent ROP", "Measures the infant's hemoglobin", "Replaces all ABGs in infants", "Detects CO poisoning in infants"], "correct": 0, "explanation": "Keep PtcO₂ about 50–80 torr; high alarm around 80.", "srcItem": "Transcutaneous"},
    {"id": "q-m203-s09-050", "topic": "m203-s09", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Dual-site PtcO₂ shows the right upper chest 20 torr higher than the lower abdomen in a newborn. What does this suggest?", "choices": ["Critical congenital heart disease", "Normal transitional circulation", "Sensor malfunction", "Hyperoxia from excess O₂"], "correct": 0, "explanation": "Suspect CCHD if pre-ductal is ≥ 15 torr higher than post-ductal.", "srcItem": "Transcutaneous"},
    {"id": "q-m203-s10-001", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "When is the Apgar score assigned?", "choices": ["At 1 and 5 minutes", "Only at birth", "At 30 minutes", "At 24 hours"], "correct": 0, "explanation": "Also at 10 minutes when the 5-minute score is below 7 (Hess).", "srcItem": "APGAR"},
    {"id": "q-m203-s10-002", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What does the \"G\" in APGAR stand for, and what does it assess?", "choices": ["Grimace — reflex irritability", "Growth — birth weight", "Gasping — respiratory effort", "Glucose — blood sugar"], "correct": 0, "explanation": "Appearance (color), Pulse (HR), Grimace (reflex), Activity (tone), Respirations (effort).", "srcItem": "APGAR"},
    {"id": "q-m203-s10-003", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An Apgar score of 4–6 means the infant is:", "choices": ["Moderately depressed", "Normal", "Severely depressed", "Stillborn"], "correct": 0, "explanation": "7–10 normal; 4–6 moderately depressed; 0–3 severely depressed.", "srcItem": "APGAR"},
    {"id": "q-m203-s10-004", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A newborn is apneic and limp at birth. When should resuscitation begin?", "choices": ["Immediately — don't wait for the score", "After the 1-minute Apgar is done", "After the 5-minute Apgar is done", "Only if the Apgar is 0"], "correct": 0, "explanation": "Needed interventions must never be delayed to obtain the Apgar.", "srcItem": "APGAR"},
    {"id": "q-m203-s10-005", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A newborn has HR 110, a weak irregular cry, pink body with blue extremities, grimaces to suction, and some flexion. What is the Apgar score?", "choices": ["6", "8", "4", "10"], "correct": 0, "explanation": "HR > 100 = 2; weak/irregular = 1; body pink/extremities blue = 1; grimace = 1; some flexion = 1 → 6.", "srcItem": "APGAR"},
    {"id": "q-m203-s10-006", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How many points does a heart rate below 100 beats/min earn in the Apgar score?", "choices": ["1", "2", "0", "3"], "correct": 0, "explanation": "None = 0; < 100 = 1; > 100 = 2.", "srcItem": "APGAR"},
    {"id": "q-m203-s10-007", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why is the Apgar score less useful in premature babies?", "choices": ["3 criteria depend on neurologic maturity", "Premature babies always score 10", "Their heart rate is always low", "It can't be scored before 5 minutes"], "correct": 0, "explanation": "Hess: three of the five criteria depend on maturity.", "srcItem": "APGAR"},
    {"id": "q-m203-s10-008", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What L/S ratio indicates fetal lung maturity?", "choices": ["Greater than 2:1", "Less than 1:1", "Exactly 1:2", "Greater than 10:1"], "correct": 0, "explanation": "Lecithin rises near term while sphingomyelin stays flat. (Your instructor de-emphasized this; it is standard NBRC content.)", "srcItem": "L/S ratio"},
    {"id": "q-m203-s10-009", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which marker confirms lung maturity, especially in infants of diabetic mothers?", "choices": ["Phosphatidylglycerol (PG)", "Rising sphingomyelin", "Bilirubin level", "Falling albumin"], "correct": 0, "explanation": "The L/S ratio can mislead in diabetic mothers; PG confirms.", "srcItem": "L/S ratio"},
    {"id": "q-m203-s10-010", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Lecithin is another name for:", "choices": ["DPPC", "Sphingomyelin", "Surfactant protein B", "Phosphatidylglycerol"], "correct": 0, "explanation": "DPPC is the surfactant component mainly responsible for lowering surface tension.", "srcItem": "L/S ratio"},
    {"id": "q-m203-s10-011", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Where is surfactant made and stored?", "choices": ["Type II cells; lamellar bodies", "Type I alveolar cells", "Goblet cells", "Alveolar macrophages"], "correct": 0, "explanation": "Lung inflation is the major stimulus for secretion.", "srcItem": "L/S ratio"},
    {"id": "q-m203-s10-012", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "An immature L/S ratio predicts which condition?", "choices": ["Infant RDS", "Croup", "Epiglottitis", "Bronchiolitis"], "correct": 0, "explanation": "Surfactant deficiency → high surface tension → higher ventilating pressures.", "srcItem": "L/S ratio"},
    {"id": "q-m203-s10-013", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Prophylactic surfactant is indicated for which premature infants?", "choices": ["< 29 weeks or < 1250 g", "> 37 weeks", "> 2500 g", "Any infant with jaundice"], "correct": 0, "explanation": "1–2 doses usually suffice because 90–95% is recycled.", "srcItem": "L/S ratio"},
    {"id": "q-m203-s10-014", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What organism causes croup?", "choices": ["Viral — parainfluenza", "Bacterial — H. influenzae", "Fungal — Candida", "Bacterial — S. aureus"], "correct": 0, "explanation": "Croup (laryngotracheobronchitis) is viral.", "srcItem": "Croup vs epiglottitis"},
    {"id": "q-m203-s10-015", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What organism classically causes epiglottitis?", "choices": ["H. influenzae (bacteria)", "Parainfluenza virus", "RSV", "Mycoplasma"], "correct": 0, "explanation": "Much less common since Hib vaccination.", "srcItem": "Croup vs epiglottitis"},
    {"id": "q-m203-s10-016", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which x-ray sign and view indicate CROUP?", "choices": ["Steeple sign on the AP view", "Thumb sign on the lateral neck view", "Air bronchograms", "Deep sulcus sign"], "correct": 0, "explanation": "Subglottic narrowing below the cords.", "srcItem": "Croup vs epiglottitis"},
    {"id": "q-m203-s10-017", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which x-ray sign and view indicate EPIGLOTTITIS?", "choices": ["Thumb sign on the lateral neck view", "Steeple sign on the AP view", "Kerley B lines", "Honeycombing"], "correct": 0, "explanation": "The swollen epiglottis looks like a thumb.", "srcItem": "Croup vs epiglottitis"},
    {"id": "q-m203-s10-018", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Where is the swelling in croup versus epiglottitis?", "choices": ["Croup subglottic; epiglottitis supraglottic", "Croup supraglottic; epiglottitis subglottic", "Both subglottic", "Both in the bronchioles"], "correct": 0, "explanation": "Croup = below the cords; epiglottitis = the epiglottis above.", "srcItem": "Croup vs epiglottitis"},
    {"id": "q-m203-s10-019", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the hallmark sign of croup?", "choices": ["A harsh, barking cough with stridor", "Drooling and tripod position", "Expiratory wheezing only", "Pink frothy sputum"], "correct": 0, "explanation": "Classic epiglottitis signs (drooling, tripod) are not in the decks but are standard.", "srcItem": "Croup vs epiglottitis"},
    {"id": "q-m203-s10-020", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which drug is used to reduce upper airway swelling in croup?", "choices": ["Racemic epinephrine", "Albuterol only", "Cromolyn", "Montelukast"], "correct": 0, "explanation": "Also used for post-extubation stridor.", "srcItem": "Croup vs epiglottitis"},
    {"id": "q-m203-s10-021", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A child with suspected epiglottitis is in distress. What takes priority?", "choices": ["Securing the airway before any x-ray", "Obtaining a lateral neck x-ray first", "Examining the throat with a tongue blade", "Drawing an ABG"], "correct": 0, "explanation": "Airway management takes priority over imaging if unstable. Never depress the tongue to inspect.", "srcItem": "Croup vs epiglottitis"},
    {"id": "q-m203-s10-022", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why do small children deteriorate so fast with airway swelling?", "choices": ["1 mm of edema cuts the airway by > 50%", "Children have larger airways than adults", "Children have no cricoid ring", "Children breathe more slowly"], "correct": 0, "explanation": "The child's narrowest point is the cricoid ring and the airway is funnel-shaped.", "srcItem": "Croup vs epiglottitis"},
    {"id": "q-m203-s10-023", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A febrile patient with productive rust-colored sputum has consolidation with air bronchograms and a high WBC. What is the diagnosis?", "choices": ["Bacterial pneumonia", "Pulmonary embolism", "Emphysema", "Pulmonary fibrosis"], "correct": 0, "explanation": "Air bronchograms + ↑ WBC + fever > 101°F.", "srcItem": "Disease comparison"},
    {"id": "q-m203-s10-024", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why is the hypoxemia in pneumonia often refractory to O₂ therapy?", "choices": ["It is caused by capillary shunting", "It is caused by hypoventilation", "It is caused by anemia", "It is caused by deadspace"], "correct": 0, "explanation": "Shunt doesn't respond well to more FiO₂.", "srcItem": "Disease comparison"},
    {"id": "q-m203-s10-025", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How do bacterial and viral pneumonia typically differ on the CBC?", "choices": ["Bacterial ↑ WBC; viral ↓ or normal WBC", "Bacterial ↓ WBC; viral ↑ WBC", "Both ↑ WBC equally", "Neither changes WBC"], "correct": 0, "explanation": "Sputum culture and sensitivity identifies the organism.", "srcItem": "Disease comparison"},
    {"id": "q-m203-s10-026", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A thin patient with a barrel chest, hyperresonance, a quiet chest and low DLCO most likely has:", "choices": ["Emphysema", "Pulmonary fibrosis", "Bacterial pneumonia", "Pulmonary embolism"], "correct": 0, "explanation": "Emphysema is the only obstructive disease of the four.", "srcItem": "Disease comparison"},
    {"id": "q-m203-s10-027", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which CXR findings are typical of emphysema?", "choices": ["Hyperlucency, flattened diaphragms, bullae", "Honeycombing and reticulonodular opacities", "Consolidation with air bronchograms", "Usually normal"], "correct": 0, "explanation": "Plus increased A-P diameter.", "srcItem": "Disease comparison"},
    {"id": "q-m203-s10-028", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What alpha-1 antitrypsin level strongly suggests AATD emphysema?", "choices": ["Less than 15–20% of normal", "Greater than 100% of normal", "Exactly normal", "Greater than 50% of normal"], "correct": 0, "explanation": "AAT deficiency causes early emphysema.", "srcItem": "Disease comparison"},
    {"id": "q-m203-s10-029", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient has sudden dyspnea, pleuritic chest pain, tachycardia and a normal chest x-ray. What should be suspected?", "choices": ["Pulmonary embolism", "Pneumonia", "Emphysema", "Pulmonary fibrosis"], "correct": 0, "explanation": "Classic triad: sudden dyspnea + tachycardia + chest pain. CXR mainly rules out other causes.", "srcItem": "Disease comparison"},
    {"id": "q-m203-s10-030", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the gold-standard test for pulmonary embolism?", "choices": ["CT pulmonary angiography", "Chest x-ray", "D-dimer", "Spirometry"], "correct": 0, "explanation": "V/Q scan if CT is contraindicated.", "srcItem": "Disease comparison"},
    {"id": "q-m203-s10-031", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What does a normal D-dimer mean in suspected PE?", "choices": ["It helps rule out PE", "It confirms PE", "It confirms DVT", "It has no value"], "correct": 0, "explanation": "An elevated D-dimer (> 500 ng/mL) only suggests clot — not specific.", "srcItem": "Disease comparison"},
    {"id": "q-m203-s10-032", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is the hallmark physiology of pulmonary embolism?", "choices": ["Deadspace ventilation", "Shunt", "Hypoventilation", "Diffusion defect only"], "correct": 0, "explanation": "Ventilation without perfusion.", "srcItem": "Disease comparison"},
    {"id": "q-m203-s10-033", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What ABG is typical of mild-to-moderate PE?", "choices": ["Acute alveolar hyperventilation with hypoxemia", "Chronic compensated respiratory acidosis", "Metabolic alkalosis", "Normal ABG"], "correct": 0, "explanation": "Severe PE → acute ventilatory failure; severe hypoxia adds lactic acidosis.", "srcItem": "Disease comparison"},
    {"id": "q-m203-s10-034", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A patient has a dry cough, clubbing, fine crackles and a bilateral reticulonodular pattern with honeycombing. What is the diagnosis?", "choices": ["Pulmonary fibrosis", "Emphysema", "Bacterial pneumonia", "Pulmonary embolism"], "correct": 0, "explanation": "Fibrosis: restrictive PFTs, ↓ DLCO, polycythemia from chronic hypoxemia.", "srcItem": "Disease comparison"},
    {"id": "q-m203-s10-035", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which PFT pattern fits pulmonary fibrosis?", "choices": ["↓ FVC, normal FEV₁/FVC, ↓ volumes", "↓ FEV₁/FVC with ↑ TLC", "All values normal", "↑ FVC with ↓ TLC"], "correct": 0, "explanation": "Restrictive.", "srcItem": "Disease comparison"},
    {"id": "q-m203-s10-036", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "How is tactile fremitus in pulmonary fibrosis?", "choices": ["Increased", "Decreased", "Absent", "Normal"], "correct": 0, "explanation": "Also dull percussion and bronchial breath sounds.", "srcItem": "Disease comparison"},
    {"id": "q-m203-s10-037", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which lab finding is common in chronic pulmonary fibrosis?", "choices": ["Polycythemia (↑ Hct, Hgb)", "A low WBC", "A high D-dimer", "Anemia (↓ Hgb)"], "correct": 0, "explanation": "From chronic hypoxemia.", "srcItem": "Disease comparison"},
    {"id": "q-m203-s10-038", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which of the four diseases produces an OBSTRUCTIVE PFT pattern?", "choices": ["Emphysema", "Pulmonary fibrosis", "Bacterial pneumonia", "Pulmonary embolism"], "correct": 0, "explanation": "↓ FEV₁, ↓ FEV₁/FVC, ↓ FEF25–75.", "srcItem": "Disease comparison"},
    {"id": "q-m203-s10-039", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is usually the EARLIEST compensation for hypoxemia in an infant?", "choices": ["Tachypnea", "Bradycardia", "Apnea", "Hypothermia"], "correct": 0, "explanation": "Hypoxemia stimulates peripheral chemoreceptors.", "srcItem": "Hypoxia in infants"},
    {"id": "q-m203-s10-040", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Why are retractions more noticeable in infants than adults?", "choices": ["Their chest wall is more compliant", "Their ribs are stiffer than adults'", "Their lungs are larger for their size", "They breathe more slowly than adults"], "correct": 0, "explanation": "The chest wall is pulled inward on inspiration.", "srcItem": "Hypoxia in infants"},
    {"id": "q-m203-s10-041", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which sign of hypoxia is seen in infants but not typically in adults?", "choices": ["Apnea", "Tachycardia", "Cyanosis", "Tachypnea"], "correct": 0, "explanation": "E.g., RSV/bronchiolitis can progress to apnea.", "srcItem": "Hypoxia in infants"},
    {"id": "q-m203-s10-042", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What does expiratory grunting do physiologically?", "choices": ["Creates auto-PEEP to keep alveoli open", "Clears secretions from the airway", "Increases inspiratory flow", "Lowers the FRC"], "correct": 0, "explanation": "Exhalation against a partly closed glottis. Scored on the Silverman-Anderson index.", "srcItem": "Hypoxia in infants"},
    {"id": "q-m203-s10-043", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "What is \"see-saw\" breathing in an infant?", "choices": ["Chest sinks in as the abdomen rises", "Alternating fast and slow breaths", "Breathing only through the mouth", "Normal quiet infant breathing"], "correct": 0, "explanation": "Thoracoabdominal paradox = abnormally high work of breathing.", "srcItem": "Hypoxia in infants"},
    {"id": "q-m203-s10-044", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A high-risk infant suddenly develops retractions, cyanosis, hypotension and asymmetrical chest movement. What should be suspected?", "choices": ["Pneumothorax", "Croup", "Normal transition", "Hypoglycemia"], "correct": 0, "explanation": "Transillumination at the bedside.", "srcItem": "Hypoxia in infants"},
    {"id": "q-m203-s10-045", "topic": "m203-s10", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Nasal flaring in an infant indicates:", "choices": ["Increased effort — a distress sign", "Normal breathing", "Nasal obstruction only", "Hyperventilation from pain"], "correct": 0, "explanation": "Nasal flaring is a classic pediatric distress sign.", "srcItem": "Hypoxia in infants"},
    {"id": "q-m203-s12-001", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On an exam, \"bronchoprovocation test\" means the same thing as:", "choices": ["Methacholine challenge", "Bronchodilator response test", "Peak flow test", "Sweat chloride test"], "correct": 0, "explanation": "Bronchoprovocation test = Methacholine Challenge.", "srcItem": "Same thing"},
    {"id": "q-m203-s12-002", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A question describes a patient as a \"CO₂ retainer.\" Which phrase means the same thing?", "choices": ["Chronic hypercarbia", "Acute hyperventilation", "Oxygen toxicity", "Metabolic alkalosis"], "correct": 0, "explanation": "Chronic Hypercarbia = CO₂ Retainer.", "srcItem": "Same thing"},
    {"id": "q-m203-s12-003", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A question asks for a device that delivers a \"controlled O₂ concentration.\" This means:", "choices": ["A specific FiO₂", "A high flow rate only", "Any nasal cannula", "Room air"], "correct": 0, "explanation": "Controlled O₂ concentration = Specific FiO₂ (e.g., an air-entrainment mask).", "srcItem": "Same thing"},
    {"id": "q-m203-s12-004", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "\"Inclusion criteria\" means the same thing as:", "choices": ["Indication", "Contraindication", "Hazard", "Complication"], "correct": 0, "explanation": "Inclusion Criteria = Indication. Exclusion Criteria = Contraindication.", "srcItem": "Same thing"},
    {"id": "q-m203-s12-005", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "\"Liberation parameters\" refers to:", "choices": ["Weaning", "Extubation equipment", "Discharge planning", "Sedation holidays only"], "correct": 0, "explanation": "Liberation Parameters = Weaning.", "srcItem": "Same thing"},
    {"id": "q-m203-s12-006", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On the exam, \"mainstay\" of therapy means:", "choices": ["Therapy of choice", "A last-resort therapy", "A therapy to avoid", "An adjunct only"], "correct": 0, "explanation": "Mainstay = Best suited for / Therapy of choice.", "srcItem": "Same thing"},
    {"id": "q-m203-s12-007", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On the exam, SIMV means the same thing as:", "choices": ["IMV", "A/C", "CMV", "CPAP"], "correct": 0, "explanation": "SIMV = IMV on the word-play list.", "srcItem": "Same thing"},
    {"id": "q-m203-s12-008", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "PBW (predicted body weight) means the same thing as:", "choices": ["IBW (ideal body weight)", "Actual body weight", "BMI", "Body surface area"], "correct": 0, "explanation": "PBW = IBW.", "srcItem": "Same thing"},
    {"id": "q-m203-s12-009", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "\"Oxygen-induced hypoventilation\" means:", "choices": ["Knocked out the hypoxic drive", "Oxygen toxicity", "Absorption atelectasis only", "Retinopathy of prematurity"], "correct": 0, "explanation": "Oxygen-induced Hypoventilation = Knocked out the Hypoxic Drive.", "srcItem": "Same thing"},
    {"id": "q-m203-s12-010", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "\"No purposeful movement to command\" means the patient is:", "choices": ["Unconscious", "Paralyzed but awake", "Agitated", "Sleeping lightly"], "correct": 0, "explanation": "No purposeful movement to command = Unconscious.", "srcItem": "Same thing"},
    {"id": "q-m203-s12-011", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On the exam, HFNC refers to:", "choices": ["VapoTherm or Optiflow", "Any nasal cannula at 6 L/min", "A nonrebreather mask", "A regular cannula up to 15 L/min"], "correct": 0, "explanation": "HFNC = VapoTherm or Optiflow (Fisher & Paykel), not \"HFNC up to 15 L.\"", "srcItem": "Same thing"},
    {"id": "q-m203-s12-012", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A Rapid Response Team (RRT) is the same as a:", "choices": ["Medical Emergency Team (MET)", "Respiratory Therapy Team", "Code Blue team only", "Transport team"], "correct": 0, "explanation": "RRT = MET.", "srcItem": "Same thing"},
    {"id": "q-m203-s12-013", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "\"Induction agents\" on the exam means:", "choices": ["Anesthetic drugs", "Paralytic drugs", "Bronchodilators", "Reversal agents"], "correct": 0, "explanation": "Induction Agents = Anesthetic Meds.", "srcItem": "Same thing"},
    {"id": "q-m203-s12-014", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "\"Imbalance\" (as in V/Q imbalance) means the same as:", "choices": ["Mismatch", "Shunt only", "Dead space only", "Equilibrium"], "correct": 0, "explanation": "Imbalance = Mismatch.", "srcItem": "Same thing"},
    {"id": "q-m203-s12-015", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "\"Long-standing\" in a question stem means:", "choices": ["Chronic", "Acute", "Severe", "Resolved"], "correct": 0, "explanation": "Long-standing = Chronic.", "srcItem": "Same thing"},
    {"id": "q-m203-s12-016", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Per the study guide's word-play list, \"Heart failure\" is equated with cardiac arrest / cardiac failure, with which reminder?", "choices": ["O₂ does NOT help", "O₂ always cures it", "Only BiPAP helps", "It is the same as COPD"], "correct": 0, "explanation": "Heart Failure = Cardiac Arrest = Cardiac Failure (O₂ does NOT help!) — as written on the study guide.", "srcItem": "Same thing"},
    {"id": "q-m203-s12-017", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On the exam, \"mechanical ventilation\" can refer to:", "choices": ["A ventilator or BiPAP", "Ventilators only", "CPAP only", "Manual resuscitation bags only"], "correct": 0, "explanation": "Mechanical Ventilation = Vent or BiPAP; it is NOT specific to vents only.", "srcItem": "Precaution words"},
    {"id": "q-m203-s12-018", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A question asks which organ \"eliminates\" CO₂. How should \"eliminate\" be read?", "choices": ["Lungs eliminate (e.g., CO₂); kidneys filter", "Kidneys eliminate CO₂; lungs filter it", "Eliminate and filter mean the same thing", "The liver eliminates CO₂"], "correct": 0, "explanation": "Eliminate does NOT mean Filter (lungs vs. kidneys).", "srcItem": "Precaution words"},
    {"id": "q-m203-s12-019", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "A question says a treatment plan change was suggested. Why must you be careful?", "choices": ["A plan change is not the same as an order", "A plan change is always an actual order", "Plan changes never need an order", "Only the RT can change orders"], "correct": 0, "explanation": "Changes to treatment plan and \"actual orders\" are NOT the same.", "srcItem": "Precaution words"},
    {"id": "q-m203-s12-020", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "\"Aggressive pain control\" in a question stem means:", "choices": ["Adequate pain control, not too much", "Overdosing the patient on opioids", "Withholding pain medication", "Using only non-drug therapy"], "correct": 0, "explanation": "Aggressive pain control does NOT mean too much meds.", "srcItem": "Precaution words"},
    {"id": "q-m203-s12-021", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "On the exam, \"recommend at this time\" usually asks for:", "choices": ["The first step", "The final long-term plan", "Any acceptable step in any order", "The most expensive option"], "correct": 0, "explanation": "The 203 list: Recommend at this time (First step).", "srcItem": "Precaution words"},
    {"id": "q-m203-s12-022", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "According to the study guide, how do \"severe\" and \"significant\" relate on an exam?", "choices": ["They are different words and must be read differently", "They mean exactly the same thing", "\"Significant\" always means more urgent", "\"Severe\" only applies to asthma"], "correct": 0, "explanation": "Severe and Significant are NOT THE SAME.", "srcItem": "Precaution words"},
    {"id": "q-m203-s12-023", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which exam strategy does the study guide stress most about changing answers?", "choices": ["Trust your first instinct", "Always change your first answer", "Choose the longest answer", "Pick the answer with the most numbers"], "correct": 0, "explanation": "TRUST YOUR \"FIRST\" INSTINCT. Also: NBRC WORLD ONLY.", "srcItem": "Strategy"},
    {"id": "q-m203-s12-024", "topic": "m203-s12", "course": "rcp203", "pool": "both", "difficulty": 2, "q": "Which terms all mean the same thing on the study guide's list?", "choices": ["NIPPV = NPPV = NIV = BiPAP", "CPAP = BiPAP = PEEP", "SIMV = A/C = CMV", "HFNC = any cannula up to 15 L"], "correct": 0, "explanation": "NIPPV = NPPV = NIV = BiPAP.", "srcItem": "Same thing"}
